DG.put("akaal-usatti/1",{"n":1,"title":null,"title_roman":null,"page":98,"blocks":[{"type":"heading","kind":"chhand","name":"ਉਤਾਰ ਖਾਸੇ ਦਸਖਤ ਕਾ","gurmukhi":"ਉਤਾਰ ਖਾਸੇ ਦਸਖਤ ਕਾ। ਪਾਤਿਸਾਹੀ ੧੦।","roman":"Utaar khaase daskhat kaa | paatisaahee 10 |","meaning_en":"","page":98,"invocation":"ਪਾਤਿਸਾਹੀ ੧੦"},{"type":"verse","number":null,"number_text":null,"page":98,"lines":[{"gurmukhi":"ਅਕਾਲ ਪੁਰਖ ਕੀ ਰਛਾ ਹਮਨੈ। ਸਰਬ ਲੋਹ ਕੀ ਰਛਿਆ ਹਮਨੈ।","roman":"Akaal purakh kee rachhaa hamnai | sarab loh kee rachhiaa hamnai |","meaning_en":"","page":98},{"gurmukhi":"ਸਰਬ ਕਾਲ ਜੀ ਦੀ ਰਛਿਆ ਹਮਨੈ। ਸਰਬ ਲੋਹ ਜੀ ਦੀ ਸਦਾ ਰਛਿਆ ਹਮਨੈ।","roman":"Sarab kaal jee dee rachhiaa hamnai | sarab loh jee dee sadaa rachhiaa hamnai |","meaning_en":"","page":98}],"flags":[{"code":"structure","reason":"verse has no number (ended by heading)"}]},{"type":"heading","kind":"note","name":"ਆਗੇ ਲਿਖਾਰੀ ਕੇ ਦਸਖਤ","gurmukhi":"ਆਗੇ ਲਿਖਾਰੀ ਕੇ ਦਸਖਤ","roman":"Aage likhaaree ke daskhat","meaning_en":"","page":98},{"type":"heading","kind":"chhand","name":"ਚਉਪਈ","gurmukhi":"ਤ੍ਵਪ੍ਰਸਾਦਿ। ਚਉਪਈ","roman":"Tvaprasaadi | chaupaee","meaning_en":"","page":98,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[1],"number_text":"੧।","page":98,"lines":[{"gurmukhi":"ਪ੍ਰਣਵੇ ਆਦਿ ਏਕੰਕਾਰਾ। ਜਲ ਥਲ ਮਹੀਅਲ ਕੀਓ ਪਸਾਰਾ।","roman":"Pranve aadi ekankaaraa | jal thal maheeal keeo pasaaraa |","meaning_en":"","page":98},{"gurmukhi":"ਆਦਿ ਪੁਰੁਖ ਅਬਗਤਿ ਅਬਿਨਾਸੀ। ਲੋਕ ਚਤ੍ਰ ਦਸਿ ਜੋਤ ਪ੍ਰਕਾਸੀ। ੧।","roman":"Aadi purukh abagti abinaasee | lok chatr dasi jot prakaasee | 1 |","meaning_en":"","page":98}]},{"type":"verse","number":[2],"number_text":"੨।","page":98,"lines":[{"gurmukhi":"ਹਸਤਿ ਕੀਟ ਕੇ ਬੀਚ ਸਮਾਨਾ। ਰਾਵ ਰੰਕ ਜਿਹ ਇਕਸਰ ਜਾਨਾ।","roman":"Hasti keet ke beech samaanaa | raav rank jih iksar jaanaa |","meaning_en":"","page":98},{"gurmukhi":"ਅਦ੍ਵੈ ਅਲਖ ਪੁਰਖ ਅਬਿਗਾਮੀ। ਸਭ ਘਟ ਘਟ ਕੇ ਅੰਤਰਜਾਮੀ। ੨।","roman":"Advai alakh purakh abigaamee | sabh ghat ghat ke antarjaamee | 2 |","meaning_en":"","page":98}]},{"type":"verse","number":[3],"number_text":"੩।","page":98,"lines":[{"gurmukhi":"ਅਲਖ ਰੂਪ ਅਛੈ ਅਨਭੇਖਾ। ਰਾਗ ਰੰਗ ਜਿਹ ਰੂਪ ਨ ਰੇਖਾ।","roman":"Alakh roop achhai anbhekhaa | raag rang jih roop na rekhaa |","meaning_en":"","page":98},{"gurmukhi":"ਬਰਨ ਚਿਹਨ ਸਭਹੂੰ ਤੇ ਨਿਆਰਾ। ਆਦਿ ਪੁਰਖ ਅਦ੍ਵੈ ਅਬਿਕਾਰਾ। ੩।","roman":"Baran chihan sabhhoon te niaaraa | aadi purakh advai abikaaraa | 3 |","meaning_en":"","page":98}]},{"type":"verse","number":[4],"number_text":"੪।","page":98,"lines":[{"gurmukhi":"ਬਰਨ ਚਿਹਨ ਜਿਹ ਜਾਤਿ ਨ ਪਾਤਾ। ਸਤ੍ਰ ਮਿਤ੍ਰ ਜਿਹ ਤਾਤ ਨ ਮਾਤਾ।","roman":"Baran chihan jih jaati na paataa | satr mitr jih taat na maataa |","meaning_en":"","page":98},{"gurmukhi":"ਸਭ ਤੇ ਦੂਰਿ ਸਭਨ ਤੇ ਨੇਰਾ। ਜਲਿ ਥਲਿ ਮਹੀਅਲਿ ਜਾਹਿ ਬਸੇਰਾ। ੪।","roman":"Sabh te doori sabhan te neraa | jali thali maheeali jaahi baseraa | 4 |","meaning_en":"","page":98}]},{"type":"verse","number":[5],"number_text":"੫।","page":98,"lines":[{"gurmukhi":"ਅਨਹਦ ਰੂਪ ਅਨਾਹਦ ਬਾਨੀ। ਚਰਨ ਸਰਨਿ ਜਿਹ ਬਸਤ ਭਵਾਨੀ।","roman":"Anhad roop anaahad baanee | charan sarni jih basat bhavaanee |","meaning_en":"","page":98},{"gurmukhi":"ਬ੍ਰਹਮਾ ਬਿਸਨੁ ਅੰਤੁ ਨਹੀ ਪਾਇਓ। ਨੇਤਿ ਨੇਤਿ ਮੁਖ ਚਾਰ ਬਤਾਇਓ। ੫।","roman":"Brahmaa bisnu antu nahee paaio | neti neti mukh chaar bataaio | 5 |","meaning_en":"","page":98}]},{"type":"verse","number":[6],"number_text":"੬।","page":98,"lines":[{"gurmukhi":"ਕੋਟਿ ਇੰਦ੍ਰ ਉਪਇੰਦ੍ਰ ਬਨਾਏ। ਬ੍ਰਹਮ ਰੁਦ੍ਰ ਉਪਾਇ ਖਪਾਏ।","roman":"Koti indr upaindr banaae | braham rudr upaai khapaae |","meaning_en":"","page":98},{"gurmukhi":"ਲੋਕ ਚਤ੍ਰ ਦਸ ਖੇਲ ਰਚਾਇਓ। ਬਹੁਰਿ ਆਪ ਹੀ ਬੀਚ ਮਿਲਾਇਓ। ੬।","roman":"Lok chatr das khel rachaaio | bahuri aap hee beech milaaio | 6 |","meaning_en":"","page":98}]},{"type":"verse","number":[7],"number_text":"੭।","page":98,"lines":[{"gurmukhi":"ਦਾਨਵ ਦੇਵ ਫਨਿੰਦ ਅਪਾਰਾ। ਗੰਧ੍ਰਬ ਜਛ ਰਚੇ ਸੁਭ ਚਾਰਾ।","roman":"Daanav dev phanind apaaraa | gandhrab jachh rache subh chaaraa |","meaning_en":"","page":98},{"gurmukhi":"ਭੂਤ ਭਵਿਖ ਭਵਾਨ ਕਹਾਨੀ। ਘਟ ਘਟ ਕੇ ਪਟ ਪਟ ਕੀ ਜਾਨੀ। ੭।","roman":"Bhoot bhavikh bhavaan kahaanee | ghat ghat ke pat pat kee jaanee | 7 |","meaning_en":"","page":98}]},{"type":"verse","number":[8],"number_text":"੮।","page":99,"lines":[{"gurmukhi":"ਤਾਤ ਮਾਤ ਜਿਹ ਜਾਤਿ ਨ ਪਾਤਾ। ਏਕ ਰੰਗ ਕਾਹੂੰ ਨਹਿ ਰਾਤਾ।","roman":"Taat maat jih jaati na paataa | ek rang kaahoon nahi raataa |","meaning_en":"","page":99},{"gurmukhi":"ਸਰਬ ਜੋਤਿ ਕੇ ਬੀਚ ਸਮਾਨਾ। ਸਭਹੂੰ ਸਰਬ ਠੌਰਿ ਪਹਿਚਾਨਾ। ੮।","roman":"Sarab joti ke beech samaanaa | sabhhoon sarab thauri pahichaanaa | 8 |","meaning_en":"","page":99}]},{"type":"verse","number":[9],"number_text":"੯।","page":99,"lines":[{"gurmukhi":"ਕਾਲ ਰਹਿਤ ਅਨਕਾਲ ਸਰੂਪਾ। ਅਲਖ ਪੁਰੁਖ ਅਵਿਗਤਿ ਅਵਧੂਤਾ।","roman":"Kaal rahit ankaal saroopaa | alakh purukh avigti avdhootaa |","meaning_en":"","page":99},{"gurmukhi":"ਜਾਤਿ ਪਾਤਿ ਜਿਹ ਚਿਹਨ ਨ ਬਰਨਾ। ਅਬਿਗਤਿ ਦੇਵ ਅਛੈ ਅਨਭਰਮਾ। ੯।","roman":"Jaati paati jih chihan na barnaa | abigti dev achhai anbharmaa | 9 |","meaning_en":"","page":99}]},{"type":"verse","number":[10],"number_text":"੧੦।","page":99,"lines":[{"gurmukhi":"ਸਭ ਕੋ ਕਾਲ ਸਭਨ ਕੋ ਕਰਤਾ। ਰੋਗ ਸੋਗ ਦੋਖਨ ਕੋ ਹਰਤਾ।","roman":"Sabh ko kaal sabhan ko kartaa | rog sog dokhan ko hartaa |","meaning_en":"","page":99},{"gurmukhi":"ਏਕ ਚਿਤ ਜਿਹ ਇਕ ਛਿਨ ਧਿਆਇਓ। ਕਾਲ ਫਾਸਿ ਕੇ ਬੀਚ ਨ ਆਇਓ। ੧੦।","roman":"Ek chit jih ik chhin dhiaaio | kaal phaasi ke beech na aaio | 10 |","meaning_en":"","page":99}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤ","gurmukhi":"ਤ੍ਵਪ੍ਰਸਾਦਿ। ਕਬਿਤ","roman":"Tvaprasaadi | kabit","meaning_en":"","page":99,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[1,11],"number_text":"੧। ੧੧।","page":99,"lines":[{"gurmukhi":"ਕਤਹੂੰ ਸੁਚੇਤ ਹੁਇ ਕੈ ਚੇਤਨਾ ਕੋ ਚਾਰੁ ਕੀਓ","roman":"Kathoon suchet hui kai chetnaa ko chaaru keeo","meaning_en":"","page":99},{"gurmukhi":"ਕਤਹੂੰ ਅਚਿੰਤ ਹੁਇ ਕੈ ਸੋਵਤ ਅਚੇਤ ਹੋ।","roman":"Kathoon achint hui kai sovat achet ho |","meaning_en":"","page":99},{"gurmukhi":"ਕਤਹੂੰ ਭਿਖਾਰੀ ਹੁਇ ਕੈ ਮਾਂਗਤ ਫਿਰਤ ਭੀਖ","roman":"Kathoon bhikhaaree hui kai maangat phirat bheekh","meaning_en":"","page":99},{"gurmukhi":"ਕਹੂੰ ਮਹਾ ਦਾਨਿ ਹੁਇ ਕੈ ਮਾਂਗਿਓ ਧਨ ਦੇਤ ਹੋ।","roman":"Kahoon mahaa daani hui kai maangio dhan det ho |","meaning_en":"","page":99},{"gurmukhi":"ਕਹੂੰ ਮਹਾ ਰਾਜਨ ਕੋ ਦੀਜਤ ਅਨੰਤ ਦਾਨ","roman":"Kahoon mahaa raajan ko deejat anant daan","meaning_en":"","page":99},{"gurmukhi":"ਕਹੂੰ ਮਹਾ ਰਾਜਨ ਤੇ ਛੀਨ ਛਿਤ ਲੇਤ ਹੋ।","roman":"Kahoon mahaa raajan te chheen chhit let ho |","meaning_en":"","page":99},{"gurmukhi":"ਕਹੂੰ ਬੇਦਿ ਰੀਤਿ ਕਹੂੰ ਤਾ ਸਿਉ ਬਿਪਰੀਤਿ","roman":"Kahoon bedi reeti kahoon taa siu bipreeti","meaning_en":"","page":99},{"gurmukhi":"ਕਹੂੰ ਤ੍ਰਿਗੁਨ ਅਤੀਤ ਕਹੂੰ ਸਰਗੁਨ ਸਮੇਤ ਹੋ। ੧। ੧੧।","roman":"Kahoon trigun ateet kahoon sargun samet ho | 1 | 11 |","meaning_en":"","page":99}]},{"type":"verse","number":[2,12],"number_text":"੨। ੧੨।","page":99,"lines":[{"gurmukhi":"ਕਹੂੰ ਜਛ ਗੰਧ੍ਰਬ ਉਰਗ ਕਹੂੰ ਬਿਦਿਆਧਰ","roman":"Kahoon jachh gandhrab urag kahoon bidiaadhar","meaning_en":"","page":99},{"gurmukhi":"ਕਹੂੰ ਭਏ ਕਿੰਨਰ ਪਿਸਾਚ ਕਹੂੰ ਪ੍ਰੇਤ ਹੋ।","roman":"Kahoon bhae kinnar pisaach kahoon pret ho |","meaning_en":"","page":99},{"gurmukhi":"ਕਹੂੰ ਹੋਇ ਕੈ ਹਿੰਦੂਆ ਗਾਇਤ੍ਰੀ ਕੋ ਗੁਪਤ ਜਪਿਓ","roman":"Kahoon hoi kai hindooaa gaaitree ko gupat japio","meaning_en":"","page":99},{"gurmukhi":"ਕਹੂੰ ਹੋਇ ਕੇ ਤੁਰਕਾ ਪੁਕਾਰੇ ਬਾਂਗ ਦੇਤ ਹੋ।","roman":"Kahoon hoi ke turkaa pukaare baang det ho |","meaning_en":"","page":99},{"gurmukhi":"ਕਹੂੰ ਕੋਕ ਕਾਬਿ ਹੁਇ ਕੈ ਪੁਰਾਨ ਕੋ ਪੜਤ ਮਤਿ","roman":"Kahoon kok kaabi hui kai puraan ko parat mati","meaning_en":"","page":99},{"gurmukhi":"ਕਤਹੂੰ ਕੁਰਾਨ ਕੋ ਨਿਦਾਨ ਜਾਨ ਲੇਤ ਹੋ।","roman":"Kathoon kuraan ko nidaan jaan let ho |","meaning_en":"","page":99},{"gurmukhi":"ਕਹੂੰ ਬੇਦ ਰੀਤ ਕਹੂੰ ਤਾ ਸਿਉ ਬਿਪਰੀਤ","roman":"Kahoon bed reet kahoon taa siu bipreet","meaning_en":"","page":99},{"gurmukhi":"ਕਹੂੰ ਤ੍ਰਿਗੁਨ ਅਤੀਤ ਕਹੂੰ ਸਰਗੁਨ ਸਮੇਤ ਹੋ। ੨। ੧੨।","roman":"Kahoon trigun ateet kahoon sargun samet ho | 2 | 12 |","meaning_en":"","page":99}]},{"type":"verse","number":[3,13],"number_text":"੩। ੧੩।","page":99,"lines":[{"gurmukhi":"ਕਹੂੰ ਦੇਵਤਾਨ ਕੇ ਦਿਵਾਨ ਮੈ ਬਿਰਾਜਮਾਨ","roman":"Kahoon devtaan ke divaan mai biraajmaan","meaning_en":"","page":99},{"gurmukhi":"ਕਹੂੰ ਦਾਨਵਾਨ ਕੋ ਗੁਮਾਨ ਮਤਿ ਦੇਤ ਹੋ।","roman":"Kahoon daanvaan ko gumaan mati det ho |","meaning_en":"","page":99},{"gurmukhi":"ਕਹੂੰ ਇੰਦ੍ਰ ਰਾਜਾ ਕੋ ਮਿਲਤ ਇੰਦ੍ਰ ਪਦਵੀ ਸੀ","roman":"Kahoon indr raajaa ko milat indr padvee see","meaning_en":"","page":99},{"gurmukhi":"ਕਹੂੰ ਇੰਦ੍ਰ ਪਦਵੀ ਛਪਾਇ ਛੀਨ ਲੇਤ ਹੋ।","roman":"Kahoon indr padvee chhapaai chheen let ho |","meaning_en":"","page":99},{"gurmukhi":"ਕਤਹੂੰ ਬਿਚਾਰ ਅਬਿਚਾਰ ਕੋ ਬਿਚਾਰਤ ਹੋ","roman":"Kathoon bichaar abichaar ko bichaarat ho","meaning_en":"","page":99},{"gurmukhi":"ਕਹੂੰ ਨਿਜ ਨਾਰਿ ਪਰਨਾਰਿ ਕੇ ਨਿਕੇਤ ਹੋ।","roman":"Kahoon nij naari parnaari ke niket ho |","meaning_en":"","page":99},{"gurmukhi":"ਕਹੂੰ ਬੇਦ ਰੀਤਿ ਕਹੂੰ ਤਾਂ ਸਿਉ ਬਿਪਰੀਤ","roman":"Kahoon bed reeti kahoon taan siu bipreet","meaning_en":"","page":99},{"gurmukhi":"ਕਹੂੰ ਤ੍ਰਿਗੁਨ ਅਤੀਤ ਕਹੂੰ ਸਰਗੁਨ ਸਮੇਤ ਹੋ। ੩। ੧੩।","roman":"Kahoon trigun ateet kahoon sargun samet ho | 3 | 13 |","meaning_en":"","page":99}]},{"type":"verse","number":[4,14],"number_text":"੪। ੧੪।","page":99,"lines":[{"gurmukhi":"ਕਹੂੰ ਸਸਤ੍ਰ ਧਾਰੀ ਕਹੂੰ ਬਿਦਿਆ ਕੇ ਬਿਚਾਰੀ","roman":"Kahoon sasatr dhaaree kahoon bidiaa ke bichaaree","meaning_en":"","page":99},{"gurmukhi":"ਕਹੂੰ ਮਾਰੁਤ ਅਹਾਰੀ ਕਹੂੰ ਨਾਰ ਕੇ ਨਿਕੇਤ ਹੋ।","roman":"Kahoon maarut ahaaree kahoon naar ke niket ho |","meaning_en":"","page":99},{"gurmukhi":"ਕਹੂੰ ਦੇਵਬਾਨੀ ਕਹੂੰ ਸਾਰਦਾ ਭਵਾਨੀ","roman":"Kahoon devbaanee kahoon saardaa bhavaanee","meaning_en":"","page":100},{"gurmukhi":"ਕਹੂੰ ਮੰਗਲਾ ਮ੍ਰਿੜਾਨੀ ਕਹੂੰ ਸਿਆਮ ਕਹੂੰ ਸੇਤ ਹੋ।","roman":"Kahoon manglaa mriraanee kahoon siaam kahoon set ho |","meaning_en":"","page":100},{"gurmukhi":"ਕਹੂੰ ਧਰਮ ਧਾਮੀ ਕਹੂੰ ਸਰਬ ਠਉਰ ਗਾਮੀ","roman":"Kahoon dharam dhaamee kahoon sarab thaur gaamee","meaning_en":"","page":100},{"gurmukhi":"ਕਹੂੰ ਜਤੀ ਕਹੂੰ ਕਾਮੀ ਕਹੂੰ ਦੇਤ ਕਹੂੰ ਲੇਤ ਹੋ।","roman":"Kahoon jatee kahoon kaamee kahoon det kahoon let ho |","meaning_en":"","page":100},{"gurmukhi":"ਕਹੂੰ ਬੇਦ ਰੀਤਿ ਕਹੂੰ ਤਾ ਸਿਉ ਬਿਪਰੀਤ","roman":"Kahoon bed reeti kahoon taa siu bipreet","meaning_en":"","page":100},{"gurmukhi":"ਕਹੂੰ ਤ੍ਰਿਗੁਨ ਅਤੀਤ ਕਹੂੰ ਸਰਗੁਨ ਸਮੇਤ ਹੋ। ੪। ੧੪।","roman":"Kahoon trigun ateet kahoon sargun samet ho | 4 | 14 |","meaning_en":"","page":100}]},{"type":"verse","number":[5,15],"number_text":"੫। ੧੫।","page":100,"lines":[{"gurmukhi":"ਕਹੂੰ ਜਟਾਧਾਰੀ ਕਹੂੰ ਕੰਠੀ ਧਰੇ ਬ੍ਰਹਮਚਾਰੀ","roman":"Kahoon jataadhaaree kahoon kanthee dhare brahamchaaree","meaning_en":"","page":100},{"gurmukhi":"ਕਹੂੰ ਜੋਗ ਸਾਧੀ ਕਹੂੰ ਸਾਧਨਾ ਕਰਤ ਹੋ।","roman":"Kahoon jog saadhee kahoon saadhnaa karat ho |","meaning_en":"","page":100},{"gurmukhi":"ਕਹੂੰ ਕਾਨ ਫਾਰੇ ਕਹੂੰ ਡੰਡੀ ਹੁਇ ਪਧਾਰੇ","roman":"Kahoon kaan phaare kahoon dandee hui padhaare","meaning_en":"","page":100},{"gurmukhi":"ਕਹੂੰ ਫੂਕਿ ਫੂਕਿ ਪਾਵਨ ਕੌ ਪ੍ਰਿਥੀ ਪੈ ਧਰਤ ਹੋ।","roman":"Kahoon phooki phooki paavan kau prithee pai dharat ho |","meaning_en":"","page":100},{"gurmukhi":"ਕਤਹੂੰ ਸਿਪਾਹੀ ਹੁਇ ਕੈ ਸਾਧਤ ਸਿਲਾਹਨ ਕੌ","roman":"Kathoon sipaahee hui kai saadhat silaahan kau","meaning_en":"","page":100},{"gurmukhi":"ਕਹੂੰ ਛਤ੍ਰੀ ਹੁਇ ਕੈ ਅਰਿ ਮਾਰਤ ਮਰਤ ਹੋ।","roman":"Kahoon chhatree hui kai ari maarat marat ho |","meaning_en":"","page":100},{"gurmukhi":"ਕਹੂੰ ਭੂਮਿ ਭਾਰ ਕੌ ਉਤਾਰਤ ਹੋ ਮਹਾਰਾਜ","roman":"Kahoon bhoomi bhaar kau utaarat ho mahaaraaj","meaning_en":"","page":100},{"gurmukhi":"ਕਹੂੰ ਭਵ ਭੂਤਨ ਕੀ ਭਾਵਨਾ ਭਰਤ ਹੋ। ੫। ੧੫।","roman":"Kahoon bhav bhootan kee bhaavnaa bharat ho | 5 | 15 |","meaning_en":"","page":100}]},{"type":"verse","number":[6,16],"number_text":"੬।੧੬।","page":100,"lines":[{"gurmukhi":"ਕਹੂੰ ਗੀਤ ਨਾਦ ਕੇ ਨਿਦਾਨ ਕੌ ਬਤਾਵਤ ਹੋ","roman":"Kahoon geet naad ke nidaan kau bataavat ho","meaning_en":"","page":100},{"gurmukhi":"ਕਹੂੰ ਨ੍ਰਿਤਕਾਰੀ ਚਿਤ੍ਰਕਾਰੀ ਕੇ ਨਿਧਾਨ ਹੋ।","roman":"Kahoon nritkaaree chitrakaaree ke nidhaan ho |","meaning_en":"","page":100},{"gurmukhi":"ਕਤਹੂੰ ਪਯੂਖ ਹੁਇ ਕੈ ਪੀਵਤ ਪਿਵਾਵਤ ਹੋ","roman":"Kathoon payookh hui kai peevat pivaavat ho","meaning_en":"","page":100},{"gurmukhi":"ਕਤਹੂੰ ਮਯੂਖ ਊਖ ਕਹੂੰ ਮਦਿ ਪਾਨਿ ਹੋ।","roman":"Kathoon mayookh ookh kahoon madi paani ho |","meaning_en":"","page":100},{"gurmukhi":"ਕਹੂੰ ਮਹਾ ਸੂਰ ਹੁਇ ਕੈ ਮਾਰਤ ਮਵਾਸਨ ਕੌ","roman":"Kahoon mahaa soor hui kai maarat mavaasan kau","meaning_en":"","page":100},{"gurmukhi":"ਕਹੂੰ ਮਹਾਦੇਵ ਦੇਵਤਾਨ ਕੇ ਸਮਾਨ ਹੋ।","roman":"Kahoon mahaadev devtaan ke samaan ho |","meaning_en":"","page":100},{"gurmukhi":"ਕਹੂੰ ਮਹਾਦੀਨ ਕਹੂੰ ਦ੍ਰਬ ਕੇ ਅਧੀਨ","roman":"Kahoon mahaadeen kahoon drab ke adheen","meaning_en":"","page":100},{"gurmukhi":"ਕਹੂੰ ਬਿਦਿਆ ਮੈ ਪ੍ਰਬੀਨ ਕਹੂੰ ਭੂਮਿ ਕਹੂੰ ਭਾਨੁ ਹੋ। ੬।੧੬।","roman":"Kahoon bidiaa mai prabeen kahoon bhoomi kahoon bhaanu ho | 6 | 16 |","meaning_en":"","page":100}]},{"type":"verse","number":[7,17],"number_text":"੭। ੧੭।","page":100,"lines":[{"gurmukhi":"ਕਹੂੰ ਅਕਲੰਕ ਕਹੂੰ ਮਾਰੁਤ ਮਯੰਕ","roman":"Kahoon aklank kahoon maarut mayank","meaning_en":"","page":100},{"gurmukhi":"ਕਹੂੰ ਪੂਰਨ ਪ੍ਰਜੰਕ ਕਹੂੰ ਸੁਧਤਾ ਕੀ ਸਾਰ ਹੋ।","roman":"Kahoon pooran prajank kahoon sudhtaa kee saar ho |","meaning_en":"","page":100},{"gurmukhi":"ਕਹੂੰ ਦੇਵ ਧਰਮ ਕਹੂੰ ਸਾਧਨਾ ਕੇ ਹਰਮ","roman":"Kahoon dev dharam kahoon saadhnaa ke haram","meaning_en":"","page":100},{"gurmukhi":"ਕਹੂੰ ਕੁਤਸਤਿ ਕੁਕਰਮ ਕਹੂੰ ਧਰਮ ਕੇ ਪ੍ਰਕਾਰ ਹੋ।","roman":"Kahoon kutasti kukram kahoon dharam ke prakaar ho |","meaning_en":"","page":100},{"gurmukhi":"ਕਹੂੰ ਪਉਨਹਾਰੀ ਕਹੂੰ ਬਿਦਿਆ ਕੇ ਬੀਚਾਰੀ","roman":"Kahoon paunhaaree kahoon bidiaa ke beechaaree","meaning_en":"","page":100},{"gurmukhi":"ਕਹੂੰ ਜੋਗੀ ਜਤੀ ਬ੍ਰਹਮਚਾਰੀ ਨਰ ਕਹੂੰ ਨਾਰਿ ਹੋ।","roman":"Kahoon jogee jatee brahamchaaree nar kahoon naari ho |","meaning_en":"","page":100},{"gurmukhi":"ਕਹੂੰ ਛਤ੍ਰਧਾਰੀ ਕਹੂੰ ਛਾਲਾ ਧਰੇ ਛੈਲ ਭਾਰੀ","roman":"Kahoon chhatradhaaree kahoon chhaalaa dhare chhail bhaaree","meaning_en":"","page":100},{"gurmukhi":"ਕਹੂੰ ਛਕਵਾਰੀ ਕਹੂੰ ਛਲ ਕੇ ਪ੍ਰਕਾਰ ਹੋ। ੭। ੧੭।","roman":"Kahoon chhakvaaree kahoon chhal ke prakaar ho | 7 | 17 |","meaning_en":"","page":100}]},{"type":"verse","number":[8,18],"number_text":"੮। ੧੮।","page":100,"lines":[{"gurmukhi":"ਕਹੂੰ ਗੀਤ ਕੇ ਗਵਯਾ ਕਹੂੰ ਬੇਨੁ ਕੇ ਬਜਯਾ","roman":"Kahoon geet ke gavyaa kahoon benu ke bajyaa","meaning_en":"","page":100},{"gurmukhi":"ਕਹੂੰ ਨ੍ਰਿਤ ਕੇ ਨਚਯਾ ਕਹੂੰ ਨਰ ਕੋ ਅਕਾਰ ਹੋ।","roman":"Kahoon nrit ke nachyaa kahoon nar ko akaar ho |","meaning_en":"","page":100},{"gurmukhi":"ਕਹੂੰ ਬੇਦ ਬਾਨੀ ਕਹੂੰ ਕੋਕ ਕੀ ਕਹਾਨੀ","roman":"Kahoon bed baanee kahoon kok kee kahaanee","meaning_en":"","page":100},{"gurmukhi":"ਕਹੂੰ ਰਾਜਾ ਕਹੂੰ ਰਾਨੀ ਕਹੂੰ ਨਾਰਿ ਕੇ ਪ੍ਰਕਾਰ ਹੋ।","roman":"Kahoon raajaa kahoon raanee kahoon naari ke prakaar ho |","meaning_en":"","page":101},{"gurmukhi":"ਕਹੂੰ ਬੇਨ ਕੇ ਬਜਯਾ ਕਹੂੰ ਧੇਨ ਕੇ ਚਰਯਾ","roman":"Kahoon ben ke bajyaa kahoon dhen ke charyaa","meaning_en":"","page":101},{"gurmukhi":"ਕਹੂੰ ਲਾਖਨ ਲਵਯਾ ਕਹੂੰ ਸੁੰਦਰ ਕੁਮਾਰ ਹੋ।","roman":"Kahoon laakhan lavyaa kahoon sundar kumaar ho |","meaning_en":"","page":101},{"gurmukhi":"ਸੁਧਤਾ ਕੀ ਸਾਨ ਹੋ ਕਿ ਸੰਤਨ ਕੇ ਪ੍ਰਾਨ ਹੋ","roman":"Sudhtaa kee saan ho ki santan ke praan ho","meaning_en":"","page":101},{"gurmukhi":"ਕਿ ਦਾਤਾ ਮਹਾ ਦਾਨਿ ਹੋ ਕਿ ਨ੍ਰਿਦੋਖੀ ਨਿਰੰਕਾਰ ਹੋ। ੮। ੧੮।","roman":"Ki daataa mahaa daani ho ki nridokhee nirankaar ho | 8 | 18 |","meaning_en":"","page":101}]},{"type":"verse","number":[9,19],"number_text":"੯। ੧੯।","page":101,"lines":[{"gurmukhi":"ਨਿਰਜੁਰ ਨਿਰੂਪ ਹੋ ਕਿ ਸੁੰਦਰ ਸਰੂਪ ਹੋ","roman":"Nirjur niroop ho ki sundar saroop ho","meaning_en":"","page":101},{"gurmukhi":"ਕਿ ਭੂਪਨ ਕੇ ਭੂਪ ਹੋ ਕਿ ਦਾਤਾ ਮਹਾ ਦਾਨ ਹੋ।","roman":"Ki bhoopan ke bhoop ho ki daataa mahaa daan ho |","meaning_en":"","page":101},{"gurmukhi":"ਪ੍ਰਾਨ ਕੇ ਬਚਯਾ ਦੂਧ ਪੂਤ ਕੇ ਦਿਵਯਾ","roman":"Praan ke bachyaa doodh poot ke divyaa","meaning_en":"","page":101},{"gurmukhi":"ਰੋਗ ਸੋਗ ਕੇ ਮਿਟਯਾ ਕਿਧੌ ਮਾਨੀ ਮਹਾ ਮਾਨ ਹੋ।","roman":"Rog sog ke mityaa kidhau maanee mahaa maan ho |","meaning_en":"","page":101},{"gurmukhi":"ਬਿਦਿਆ ਕੇ ਬਿਚਾਰ ਹੋ ਕਿ ਅਦ੍ਵੈ ਅਵਤਾਰ ਹੋ","roman":"Bidiaa ke bichaar ho ki advai avtaar ho","meaning_en":"","page":101},{"gurmukhi":"ਕਿ ਸਿਧਤਾ ਕੀ ਸੂਰਤਿ ਹੋ ਕਿ ਸੁਧਤਾ ਕੀ ਸਾਨ ਹੋ।","roman":"Ki sidhtaa kee soorti ho ki sudhtaa kee saan ho |","meaning_en":"","page":101},{"gurmukhi":"ਜੋਬਨ ਕੇ ਜਾਲ ਹੋ ਕਿ ਕਾਲ ਹੂੰ ਕੇ ਕਾਲ ਹੋ","roman":"Joban ke jaal ho ki kaal hoon ke kaal ho","meaning_en":"","page":101},{"gurmukhi":"ਕਿ ਸਤ੍ਰਨ ਕੇ ਸੂਲ ਹੋ ਕਿ ਮਿਤ੍ਰਨ ਕੇ ਪ੍ਰਾਨ ਹੋ। ੯। ੧੯।","roman":"Ki satran ke sool ho ki mitran ke praan ho | 9 | 19 |","meaning_en":"","page":101}]},{"type":"verse","number":[10,20],"number_text":"੧੦। ੨੦।","page":101,"lines":[{"gurmukhi":"ਕਹੂੰ ਬ੍ਰਹਮਬਾਦ ਕਹੂੰ ਬਿਦਿਆ ਕੋ ਬਿਖਾਦ","roman":"Kahoon brahambaad kahoon bidiaa ko bikhaad","meaning_en":"","page":101},{"gurmukhi":"ਕਹੂੰ ਨਾਦ ਕੇ ਨਿਨਾਦ ਕਹੂੰ ਪੂਰਨ ਭਗਤ ਹੋ।","roman":"Kahoon naad ke ninaad kahoon pooran bhagat ho |","meaning_en":"","page":101},{"gurmukhi":"ਕਹੂੰ ਬੇਦ ਰੀਤਿ ਕਹੂੰ ਬਿਦਿਆ ਕੀ ਪ੍ਰਤੀਤਿ","roman":"Kahoon bed reeti kahoon bidiaa kee prateeti","meaning_en":"","page":101},{"gurmukhi":"ਕਹੂੰ ਨੀਤਿ ਅਉ ਅਨੀਤਿ ਕਹੂੰ ਜ੍ਵਾਲਾ ਸੀ ਜਗਤ ਹੋ।","roman":"Kahoon neeti au aneeti kahoon jvaalaa see jagat ho |","meaning_en":"","page":101},{"gurmukhi":"ਪੂਰਨ ਪ੍ਰਤਾਪ ਕਹੂੰ ਇਕਾਤੀ ਕੋ ਜਾਪ ਕਹੂੰ","roman":"Pooran prataap kahoon ikaatee ko jaap kahoon","meaning_en":"","page":101},{"gurmukhi":"ਤਾਪ ਕੋ ਅਤਾਪ ਕਹੂੰ ਜੋਗ ਤੇ ਡਿਗਤ ਹੋ।","roman":"Taap ko ataap kahoon jog te digat ho |","meaning_en":"","page":101},{"gurmukhi":"ਕਹੂੰ ਬਰ ਦੇਤ ਕਹੂੰ ਛਲ ਸੋ ਛਿਨਾਇ ਲੇਤ","roman":"Kahoon bar det kahoon chhal so chhinaai let","meaning_en":"","page":101},{"gurmukhi":"ਸਰਬ ਕਾਲਿ ਸਰਬ ਠੌਰਿ ਏਕ ਸੇ ਲਗਤ ਹੋ। ੧੦। ੨੦।","roman":"Sarab kaali sarab thauri ek se lagat ho | 10 | 20 |","meaning_en":"","page":101,"flags":[{"code":"ੋੋ","reason":"same sign typed twice; written once (prints as one)"}]}]},{"type":"heading","kind":"chhand","name":"ਸ੍ਵੈਯੇ","gurmukhi":"ਤ੍ਵਪ੍ਰਸਾਦਿ। ਸ੍ਵੈਯੇ","roman":"Tvaprasaadi | svaiye","meaning_en":"By Your grace. Savaiye.","page":101,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ","meaning_status":"draft","note":"These ten savaiye (Akal Ustat verses 21-30) are recited as 'Tav Prasad Savaiye'."},{"type":"verse","number":[1,21],"number_text":"੧। ੨੧।","page":101,"lines":[{"gurmukhi":"ਸ੍ਰਾਵਗ ਸੁਧ ਸਮੂਹ ਸਿਧਾਨ ਕੇ ਦੇਖਿ ਫਿਰਿਓ ਘਰਿ ਜੋਗਿ ਜਤੀ ਕੇ।","roman":"Sraavag sudh samooh sidhaan ke dekhi phirio ghari jogi jatee ke |","meaning_en":"I have seen the pure Jains (Shravaks), the hosts of Siddhas, and the homes of yogis and celibates;","page":101,"meaning_status":"draft","note":"ਸ੍ਰਾਵਗ: Jain lay devotees / ascetics. ਸਿਧਾਨ: Siddhas, perfected yogis. ਜਤੀ: celibates."},{"gurmukhi":"ਸੂਰ ਸੁਰਾਰਦਨ ਸੁਧ ਸੁਧਾਦਿਕ ਸੰਤ ਸਮੂਹ ਅਨੇਕ ਮਤੀ ਕੇ।","roman":"Soor suraardan sudh sudhaadik sant samooh anek matee ke |","meaning_en":"warriors, slayers of demons, pure drinkers of nectar (gods), and hosts of saints of many creeds;","page":101,"meaning_status":"draft","note":"ਸੁਰਾਰਦਨ: slayers of the enemies of the gods (demon-slayers). ਸੁਧਾਦਿਕ: read as 'drinkers of nectar (the gods)'; some read 'the pure and the like'."},{"gurmukhi":"ਸਾਰੇ ਹੀ ਦੇਸ ਕੋ ਦੇਖਿ ਰਹਿਯੋ ਮਤ ਕੋਊ ਨ ਦੇਖੀਅਤ ਪ੍ਰਾਨ ਪਤੀ ਕੇ।","roman":"Saare hee des ko dekhi rahiyo mat ko'oo na dekheeat praan patee ke |","meaning_en":"I have looked at the creeds of every land, but I see none of the Lord of life;","page":101,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਰੀ ਭਗਵਾਨ ਕੀ ਭਾਇ ਕ੍ਰਿਪਾ ਹੂੰ ਤੇ ਏਕ ਰਤੀ ਬਿਨੁ ਏਕ ਰਤੀ ਕੇ। ੧। ੨੧।","roman":"Sree bhagvaan kee bhaai kripaa hoon te ek ratee binu ek ratee ke | 1 | 21 |","meaning_en":"without even a tiny bit of the love and grace of the revered Lord, they are not worth a tiny bit.","page":101,"meaning_status":"draft","note":"ਏਕ ਰਤੀ ਬਿਨੁ ਏਕ ਰਤੀ ਕੇ: 'without one particle (of His love/grace) they are not worth one particle'. ਭਾਇ: love."}]},{"type":"verse","number":[2,22],"number_text":"੨। ੨੨।","page":101,"lines":[{"gurmukhi":"ਮਾਤੇ ਮਤੰਗ ਜਰੇ ਜਰ ਸੰਗਿ ਅਨੂਪ ਉਤੰਗ ਸੁਰੰਗ ਸਵਾਰੇ।","roman":"Maate matang jare jar sangi anoop utang surang savaare |","meaning_en":"Intoxicated elephants, decked with gold, incomparable, tall and finely adorned;","page":101,"meaning_status":"draft","note":"ਜਰ: gold. ਸੁਰੰਗ: beautifully coloured."},{"gurmukhi":"ਕੋਟਿ ਤੁਰੰਗ ਕੁਰੰਗ ਸੇ ਕੂਦਤ ਪਉਨ ਕੇ ਗਉਨ ਕੋ ਜਾਤ ਨਿਵਾਰੇ।","roman":"Koti turang kurang se koodat paun ke gaun ko jaat nivaare |","meaning_en":"millions of horses that leap like deer and outrun the wind;","page":101,"meaning_status":"draft","note":"ਕੁਰੰਗ: deer."},{"gurmukhi":"ਭਾਰੀ ਭੁਜਾਨ ਕੇ ਭੂਪ ਭਲੀ ਬਿਧਿ ਨਿਆਵਤ ਸੀਸ ਨ ਜਾਤ ਬਿਚਾਰੇ।","roman":"Bhaaree bhujaan ke bhoop bhalee bidhi niaavat sees na jaat bichaare |","meaning_en":"mighty-armed kings who bow their heads in fine manner, more than can be counted;","page":101,"meaning_status":"draft","note":"ਨਿਆਵਤ ਸੀਸ: who bow their heads (before the owner of all this)."},{"gurmukhi":"ਏਤੇ ਭਏ ਤੋ ਕਹਾ ਭਏ ਭੂਪਤਿ ਅੰਤ ਕੈ ਨਾਗੇ ਹੀ ਪਾਇ ਪਧਾਰੇ। ੨। ੨੨।","roman":"Ete bhae to kahaa bhae bhoopti ant kai naage hee paai padhaare | 2 | 22 |","meaning_en":"even if one becomes such a king, what of it? In the end he departs barefoot.","page":101,"meaning_status":"draft","note":"ਨਾਗੇ ਹੀ ਪਾਇ: with bare feet, i.e. taking nothing along."}]},{"type":"verse","number":[3,23],"number_text":"੩। ੨੩।","page":102,"lines":[{"gurmukhi":"ਜੀਤ ਫਿਰੇ ਸਭ ਦੇਸ ਦਿਸਾਨ ਕੋ ਬਾਜਤ ਢੋਲ ਮ੍ਰਿਦੰਗ ਨਗਾਰੇ।","roman":"Jeet phire sabh des disaan ko baajat dhol mridang nagaare |","meaning_en":"They went about conquering every land and direction, with drums, mridangs and kettle-drums sounding;","page":102,"meaning_status":"draft","note":"ਮ੍ਰਿਦੰਗ: a two-headed drum; ਨਗਾਰੇ: kettle-drums."},{"gurmukhi":"ਗੁੰਜਤ ਗੂੜ ਗਜਾਨ ਕੇ ਸੁੰਦਰ ਹਿੰਤਸਤ ਹੀ ਹਯ ਰਾਜ ਹਜਾਰੇ।","roman":"Gunjat goor gajaan ke sundar hintsat hee hay raaj hajaare |","meaning_en":"beautiful elephants trumpeting deeply, and thousands of royal horses neighing;","page":102,"meaning_status":"draft"},{"gurmukhi":"ਭੂਤ ਭਵਿਖ ਭਵਾਨ ਕੇ ਭੂਪਤਿ ਕਉਨ ਗਨੈ ਨਹੀ ਜਾਤ ਬਿਚਾਰੇ।","roman":"Bhoot bhavikh bhavaan ke bhoopti kaun ganai nahee jaat bichaare |","meaning_en":"who can count such kings of the past, the future and the present? They cannot even be thought of;","page":102,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਰੀਪਤਿ ਸ੍ਰੀ ਭਗਵਾਨ ਭਜੇ ਬਿਨੁ ਅੰਤ ਕੋ ਅੰਤ ਕੇ ਧਾਮ ਸਿਧਾਰੇ। ੩। ੨੩।","roman":"Sreepti sree bhagvaan bhaje binu ant ko ant ke dhaam sidhaare | 3 | 23 |","meaning_en":"without remembering the Lord of wealth, the revered Lord, in the end they all went to the final abode.","page":102,"meaning_status":"draft","note":"ਸ੍ਰੀਪਤਿ: Lord of Lakshmi / of all wealth, i.e. God. ਅੰਤ ਕੇ ਧਾਮ: the abode of the end (death)."}]},{"type":"verse","number":[4,24],"number_text":"੪। ੨੪।","page":102,"lines":[{"gurmukhi":"ਤੀਰਥ ਨ੍ਹਾਨ ਦਇਆ ਦਮ ਦਾਨ ਸੁ ਸੰਜਮ ਨੇਮ ਅਨੇਕ ਬਿਸੇਖੇ।","roman":"Teerath nhaan daiaa dam daan su sanjam nem anek bisekhe |","meaning_en":"Bathing at pilgrim places, compassion, self-control, charity, discipline, and many special rites;","page":102,"meaning_status":"draft","note":"ਦਮ: control of the senses. ਸੰਜਮ ਨੇਮ: discipline and religious vows."},{"gurmukhi":"ਬੇਦ ਪੁਰਾਨ ਕਤੇਬ ਕੁਰਾਨ ਜਿਮੀਨ ਜਮਾਨ ਸਬਾਨ ਕੇ ਪੇਖੇ।","roman":"Bed puraan kateb kuraan jimeen jamaan sabaan ke pekhe |","meaning_en":"the Vedas, Puranas, the Semitic books and the Quran, and the people of every land and age, I have seen;","page":102,"meaning_status":"draft","note":"ਜਿਮੀਨ ਜਮਾਨ ਸਬਾਨ: read as 'of all lands and times'; some read 'the earth, the heavens and all'."},{"gurmukhi":"ਪਉਨ ਅਹਾਰ ਜਤੀ ਜਤ ਧਾਰਿ ਸਬੈ ਸੁ ਬਿਚਾਰ ਹਜਾਰਕ ਦੇਖੇ।","roman":"Paun ahaar jatee jat dhaari sabai su bichaar hajaarak dekhe |","meaning_en":"those who live on air, celibates who keep their vows, all these and thousands of thinkers I have seen;","page":102,"meaning_status":"draft","note":"ਪਉਨ ਅਹਾਰ: who live on air (extreme fasters)."},{"gurmukhi":"ਸ੍ਰੀ ਭਗਵਾਨ ਭਜੇ ਬਿਨੁ ਭੂਪਤਿ ਏਕ ਰਤੀ ਬਿਨੁ ਏਕ ਨ ਲੇਖੈ। ੪। ੨੪।","roman":"Sree bhagvaan bhaje binu bhoopti ek ratee binu ek na lekhai | 4 | 24 |","meaning_en":"but without remembering the revered Lord, O king, none of them counts for even a tiny bit.","page":102,"meaning_status":"draft","note":"ਭੂਪਤਿ: 'O king', or 'the Lord (sovereign)'. Read either way."}]},{"type":"verse","number":[5,25],"number_text":"੫। ੨੫।","page":102,"lines":[{"gurmukhi":"ਸੁਧ ਸਿਪਾਹੀ ਦੁਰੰਤ ਦੁਬਾਹ ਸੁ ਸਾਜਿ ਸਨਾਹ ਦੁਰਜਾਨ ਦਲੈਂਗੇ।","roman":"Sudh sipaahee durant dubaah su saaji sanaah durjaan dalainge |","meaning_en":"Pure soldiers, invincible and strong-armed, who don their armour and crush their foes;","page":102,"meaning_status":"draft","note":"ਦੁਰੰਤ ਦੁਬਾਹ: read as 'invincible, two-armed (mighty)'. ਸਨਾਹ: armour."},{"gurmukhi":"ਭਾਰੀ ਗੁਮਾਨ ਭਰੇ ਮਨ ਮੈ ਕਰਿ ਪਰਬਤ ਪੰਖ ਹਲੈ ਨ ਹਲੈਂਗੇ।","roman":"Bhaaree gumaan bhare man mai kari parbat pankh halai na halainge |","meaning_en":"with great pride in their minds, thinking 'even if mountains grew wings and moved, we would not move';","page":102,"meaning_status":"draft"},{"gurmukhi":"ਤੋਰਿ ਅਰੀਨ ਮਰੋਰਿ ਮਵਾਸਨ ਮਾਤੇ ਮਤੰਗਨ ਮਾਨ ਮਲੈਂਗੇ।","roman":"Tori areen marori mavaasan maate matangan maan malainge |","meaning_en":"who would break enemies, twist the rebels and crush the pride of intoxicated elephants;","page":102,"meaning_status":"draft","note":"ਮਵਾਸਨ: rebels / those in strongholds."},{"gurmukhi":"ਸ੍ਰੀ ਪਤਿ ਸ੍ਰੀ ਭਗਵਾਨ ਕ੍ਰਿਪਾ ਬਿਨੁ ਤਿਆਗਿ ਜਹਾਨੁ ਨਿਦਾਨ ਚਲੈਂਗੇ। ੫। ੨੫।","roman":"Sree pati sree bhagvaan kripaa binu tiaagi jahaanu nidaan chalainge | 5 | 25 |","meaning_en":"without the grace of the Lord of wealth, the revered Lord, in the end they will leave the world and depart.","page":102,"meaning_status":"draft"}]},{"type":"verse","number":[6,26],"number_text":"੬। ੨੬।","page":102,"lines":[{"gurmukhi":"ਬੀਰ ਅਪਾਰ ਬਡੇ ਬਰਿਆਰ ਅਬਿਚਾਰਹਿ ਸਾਰ ਕੀ ਧਾਰ ਭਛਯਾ।","roman":"Beer apaar bade bariaar abichaarhi saar kee dhaar bhachhyaa |","meaning_en":"Countless heroes, very mighty, who fearlessly face (eat) the edge of the sword;","page":102,"meaning_status":"draft","note":"ਅਬਿਚਾਰਹਿ: without hesitation. ਸਾਰ ਕੀ ਧਾਰ ਭਛਯਾ: 'eaters of the steel's edge', i.e. who face swords in battle."},{"gurmukhi":"ਤੋਰਤ ਦੇਸ ਮਲਿੰਦ ਮਵਾਸਨ ਮਾਤੇ ਗਜਾਨ ਕੇ ਮਾਨ ਮਲਯਾ।","roman":"Torat des malind mavaasan maate gajaan ke maan malyaa |","meaning_en":"who break countries, crush rebel chiefs and humble the pride of intoxicated elephants;","page":102,"meaning_status":"draft","note":"ਮਲਿੰਦ: read as 'chieftains / strongmen'; uncertain."},{"gurmukhi":"ਗਾੜੇ ਗੜਾਨ ਕੇ ਤੋੜਨਹਾਰ ਸੁ ਬਾਤਨ ਹੀ ਚਕ ਚਾਰ ਲਵਯਾ।","roman":"Gaare garaan ke toranhaar su baatan hee chak chaar lavyaa |","meaning_en":"breakers of the strongest forts, who could win the four directions with mere words;","page":102,"meaning_status":"draft","note":"ਬਾਤਨ ਹੀ ਚਕ ਚਾਰ ਲਵਯਾ: 'who take the four quarters by talk alone'."},{"gurmukhi":"ਸਾਹਿਬੁ ਸ੍ਰੀ ਸਭ ਕੋ ਸਿਰਨਾਇਕ ਜਾਚਕ ਅਨੇਕ ਸੁ ਏਕ ਦਿਵਯਾ। ੬। ੨੬।","roman":"Saahibu sree sabh ko sirnaaik jaachak anek su ek divyaa | 6 | 26 |","meaning_en":"the revered Lord is the Master and Head of all; the beggars are many, but the Giver is One.","page":102,"meaning_status":"draft","note":"ਸਿਰਨਾਇਕ: chief, supreme head. ਜਾਚਕ: beggars, i.e. all those beings."}]},{"type":"verse","number":[7,27],"number_text":"੭। ੨੭।","page":102,"lines":[{"gurmukhi":"ਦਾਨਵ ਦੇਵ ਫਨਿੰਦ ਨਿਸਾਚਰ ਭੂਤ ਭਵਿਖ ਭਵਾਨ ਜਪੈਂਗੇ।","roman":"Daanav dev phanind nisaachar bhoot bhavikh bhavaan japainge |","meaning_en":"Demons, gods, great serpents, night-wanderers, in the past, present and future, will recite His name;","page":102,"meaning_status":"draft","note":"ਫਨਿੰਦ: lords of serpents (Sheshnag). ਨਿਸਾਚਰ: night-wanderers (demons). Some read the verb as 'have recited and will recite'."},{"gurmukhi":"ਜੀਵ ਜਿਤੇ ਜਲ ਮੈ ਥਲ ਮੈ ਪਲ ਹੀ ਪਲ ਮੈ ਸਭ ਥਾਪ ਥਪੈਂਗੇ।","roman":"Jeev jite jal mai thal mai pal hee pal mai sabh thaap thapainge |","meaning_en":"all creatures in water and on land, He establishes in a moment;","page":102,"meaning_status":"draft","note":"ਥਾਪ ਥਪੈਂਗੇ: read as 'He establishes (and disestablishes)'; the subject is debated."},{"gurmukhi":"ਪੁੰਨ ਪ੍ਰਤਾਪਨ ਬਾਢਿ ਜੈਤ ਧੁਨਿ ਪਾਪਨ ਕੈ ਬਹੁ ਪੁੰਜ ਖਪੈਂਗੇ।","roman":"Punn prataapan baadhi jait dhuni paapan kai bahu punj khapainge |","meaning_en":"the glory of merit grows and the sound of victory rises, and the many heaps of sin are destroyed;","page":102,"meaning_status":"draft","note":"The subject is read as 'by remembering Him' (implied from the previous lines)."},{"gurmukhi":"ਸਾਧ ਸਮੂਹ ਪ੍ਰਸੰਨ ਫਿਰੈ ਜਗਿ ਸਤ੍ਰ ਸਭੈ ਅਵਿਲੋਕਿ ਚਪੈਂਗੇ। ੭। ੨੭।","roman":"Saadh samooh prasann phirai jagi satr sabhai aviloki chapainge | 7 | 27 |","meaning_en":"hosts of holy people go about the world in joy, and enemies are crushed at the sight (of them).","page":102,"meaning_status":"draft","note":"ਅਵਿਲੋਕਿ ਚਪੈਂਗੇ: read as 'seeing (them), are suppressed' or 'are ashamed'."}]},{"type":"verse","number":[8,28],"number_text":"੮। ੨੮।","page":102,"lines":[{"gurmukhi":"ਮਾਨਵ ਇੰਦ੍ਰ ਗਜਿੰਦ੍ਰ ਨਰਾਧਿਪ ਜੌਨ ਤ੍ਰਿਲੋਕ ਕੋ ਰਾਜੁ ਕਰੈਂਗੇ।","roman":"Maanav indr gajindr naraadhip jaun trilok ko raaju karainge |","meaning_en":"Kings of men, kings of elephants, rulers who will rule the three worlds;","page":102,"meaning_status":"draft","note":"ਮਾਨਵ ਇੰਦ੍ਰ: kings of men. ਗਜਿੰਦ੍ਰ: lords of elephants (great rulers)."},{"gurmukhi":"ਕੋਟਿ ਇਸਨਾਨ ਗਜਾਦਿਕ ਦਾਨਿ ਅਨੇਕ ਸੁਅੰਬਰ ਸਾਜਿ ਬਰੈਂਗੇ।","roman":"Koti isnaan gajaadik daani anek suanbar saaji barainge |","meaning_en":"who bathe at millions of holy places, give elephants and the like in charity, and win many brides at swayamvars;","page":102,"meaning_status":"draft","note":"ਸੁਅੰਬਰ: swayamvar, a ceremony where a princess chooses her husband."},{"gurmukhi":"ਬ੍ਰਹਮ ਮਹੇਸੁਰ ਬਿਸਨੁ ਸਚੀਪਤਿ ਅੰਤਿ ਫਸੇ ਜਮ ਫਾਸਿ ਪਰੈਂਗੇ।","roman":"Braham mahesur bisnu sacheepti anti phase jam phaasi parainge |","meaning_en":"Brahma, Shiva, Vishnu and the husband of Sachi (Indra), in the end all are caught in the noose of death;","page":102,"meaning_status":"draft","note":"ਸਚੀਪਤਿ: husband of Sachi, i.e. Indra."},{"gurmukhi":"ਜੇ ਨਰ ਸ੍ਰੀ ਪਤਿ ਕੇ ਪ੍ਰਸ ਹੈਂ ਪਗ ਤੇ ਨਰ ਫੇਰਿ ਨ ਦੇਹ ਧਰੈਂਗੇ। ੮। ੨੮।","roman":"Je nar sree pati ke pras hain pag te nar pheri na deh dharainge | 8 | 28 |","meaning_en":"but those who touch the feet of the Lord of wealth will not take a body again.","page":102,"meaning_status":"draft","note":"ਪ੍ਰਸ ਹੈਂ ਪਗ: touch (embrace) the feet; i.e. those devoted to God are freed from rebirth."}]},{"type":"verse","number":[9,29],"number_text":"੯। ੨੯।","page":103,"lines":[{"gurmukhi":"ਕਹਾ ਭਯੋ ਦੋਊ ਲੋਚਨ ਮੂੰਦ ਕੈ ਬੈਠਿ ਰਹਿਓ ਬਕ ਧ੍ਯਾਨ ਲਗਾਇਓ।","roman":"Kahaa bhayo do'oo lochan moond kai baithi rahio bak dhyaan lagaaio |","meaning_en":"What use is it to sit with both eyes closed, meditating like a crane?","page":103,"meaning_status":"draft","note":"ਬਕ ਧ੍ਯਾਨ: the 'meditation' of a crane, who stands still only to catch fish, i.e. hypocritical meditation."},{"gurmukhi":"ਨ੍ਹਾਤ ਫਿਰਿਓ ਲੀਏ ਸਾਤ ਸਮੁੰਦ੍ਰਨ ਲੋਕ ਗਇਓ ਪਰਲੋਕ ਗਵਾਇਓ।","roman":"Nhaat phirio lee'e saat samundran lok gaio parlok gavaaio |","meaning_en":"He went about bathing in the seven seas; he lost this world and lost the next as well.","page":103,"meaning_status":"draft","note":"ਲੋਕ ਗਇਓ ਪਰਲੋਕ ਗਵਾਇਓ: lost this life (in vain ritual) and lost the hereafter."},{"gurmukhi":"ਬਾਸੁ ਕੀਓ ਬਿਖਿਆਨ ਸੋ ਬੈਠ ਕੇ ਐਸੇ ਹੀ ਐਸ ਸੋ ਬੈਸ ਬਿਤਾਇਓ।","roman":"Baasu keeo bikhiaan so baith ke aise hee ais so bais bitaaio |","meaning_en":"He made his home amid sinful pursuits, and in this way he spent his life.","page":103,"meaning_status":"draft","note":"ਬਿਖਿਆਨ: poisonous things, i.e. worldly vices. ਬੈਸ: age, lifetime."},{"gurmukhi":"ਸਾਚੁ ਕਹੌ ਸੁਨ ਲੇਹੁ ਸਭੈ ਜਿਨ ਪ੍ਰੇਮ ਕੀਓ ਤਿਨ ਹੀ ਪ੍ਰਭੁ ਪਾਇਓ। ੯। ੨੯।","roman":"Saachu kahau sun lehu sabhai jin prem keeo tin hee prabhu paaio | 9 | 29 |","meaning_en":"I speak the truth, let all hear it: only those who loved have found the Lord.","page":103,"meaning_status":"draft"}]},{"type":"verse","number":[10,30],"number_text":"੧੦।੩੦।","page":103,"lines":[{"gurmukhi":"ਕਾਹੂੰ ਲੈ ਪਾਹਨ ਪੂਜ ਧਰਿਓ ਸਿਰਿ ਕਾਹੂੰ ਲੈ ਲਿੰਗੁ ਗਰੇ ਲਟਕਾਇਓ।","roman":"Kaahoon lai paahan pooj dhario siri kaahoon lai lingu gare latkaaio |","meaning_en":"Someone takes a stone, worships it and places it on his head; someone hangs a lingam around his neck;","page":103,"meaning_status":"draft","note":"ਲਿੰਗੁ: the stone emblem of Shiva."},{"gurmukhi":"ਕਾਹੂੰ ਲਖਿਓ ਹਰਿ ਅਵਾਚੀ ਦਿਸਾ ਮਹਿ ਕਾਹੂੰ ਪਛਾਹ ਕੋ ਸੀਸ ਨਿਵਾਇਓ।","roman":"Kaahoon lakhio hari avaachee disaa mahi kaahoon pachhaah ko sees nivaaio |","meaning_en":"someone sees God in the south; someone bows his head towards the west;","page":103,"meaning_status":"draft","note":"ਅਵਾਚੀ ਦਿਸਾ: the southern direction (some read 'the lower region'). ਪਛਾਹ: the west (towards Mecca, from India)."},{"gurmukhi":"ਕੋਊ ਬੁਤਾਨ ਕੌ ਪੂਜਤ ਹੈ ਪਸੁ ਕੋਊ ਮ੍ਰਿਤਾਨ ਕੌ ਪੂਜਨ ਧਾਇਓ।","roman":"Ko'oo butaan kau poojat hai pasu ko'oo mritaan kau poojan dhaaio |","meaning_en":"some fool worships idols; someone rushes to worship the dead (at graves);","page":103,"meaning_status":"draft","note":"ਪਸੁ: 'beast', i.e. a foolish person. ਮ੍ਰਿਤਾਨ: the dead (graves, tombs)."},{"gurmukhi":"ਕੂਰ ਕ੍ਰਿਆ ਉਰਝਿਓ ਸਭ ਹੀ ਜਗੁ ਸ੍ਰੀ ਭਗਵਾਨ ਕੌ ਭੇਦੁ ਨ ਪਾਇਓ। ੧੦।੩੦।","roman":"Koor kriaa urjhio sabh hee jagu sree bhagvaan kau bhedu na paaio | 10 | 30 |","meaning_en":"the whole world is entangled in false rites and has not found the secret of the revered Lord.","page":103,"meaning_status":"draft","note":"ਕੂਰ ਕ੍ਰਿਆ: false practices / rituals."}]},{"type":"heading","kind":"chhand","name":"ਤੋਮਰ ਛੰਦ","gurmukhi":"ਤ੍ਵਪ੍ਰਸਾਦਿ। ਤੋਮਰ ਛੰਦ","roman":"Tvaprasaadi | tomar chhand","meaning_en":"","page":103,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[1,31],"number_text":"੧। ੩੧।","page":103,"lines":[{"gurmukhi":"ਹਰਿ ਜਨਮ ਮਰਨ ਬਿਹੀਨ। ਦਸ ਚਾਰ ਚਾਰ ਪ੍ਰਬੀਨ।","roman":"Hari janam maran biheen | das chaar chaar prabeen |","meaning_en":"","page":103},{"gurmukhi":"ਅਕਲੰਕ ਰੂਪ ਅਪਾਰ। ਅਨਛਿਜ ਤੇਜ ਉਦਾਰ। ੧। ੩੧।","roman":"Aklank roop apaar | anchhij tej udaar | 1 | 31 |","meaning_en":"","page":103}]},{"type":"verse","number":[2,32],"number_text":"੨। ੩੨।","page":103,"lines":[{"gurmukhi":"ਅਨਭਿਜ ਰੂਪ ਦੁਰੰਤ। ਸਭ ਜਗਤ ਭਗਤ ਮਹੰਤ।","roman":"Anbhij roop durant | sabh jagat bhagat mahant |","meaning_en":"","page":103},{"gurmukhi":"ਜਸ ਤਿਲਕ ਭੂ ਭ੍ਰਿਤ ਭਾਨੁ। ਦਸ ਚਾਰ ਚਾਰ ਨਿਧਾਨ। ੨। ੩੨।","roman":"Jas tilak bhoo bhrit bhaanu | das chaar chaar nidhaan | 2 | 32 |","meaning_en":"","page":103}]},{"type":"verse","number":[3,33],"number_text":"੩। ੩੩।","page":103,"lines":[{"gurmukhi":"ਅਕਲੰਕ ਰੂਪ ਅਪਾਰ। ਸਭ ਲੋਕ ਸੋਕ ਬਿਦਾਰ।","roman":"Aklank roop apaar | sabh lok sok bidaar |","meaning_en":"","page":103},{"gurmukhi":"ਕਲ ਕਾਲ ਕਰਮ ਬਿਹੀਨ। ਸਭ ਕਰਮ ਧਰਮ ਪ੍ਰਬੀਨ। ੩। ੩੩।","roman":"Kal kaal karam biheen | sabh karam dharam prabeen | 3 | 33 |","meaning_en":"","page":103}]},{"type":"verse","number":[4,34],"number_text":"੪। ੩੪।","page":103,"lines":[{"gurmukhi":"ਅਨਖੰਡ ਅਤੁਲ ਪ੍ਰਤਾਪ। ਸਭ ਥਾਪਿਓ ਜਿਹ ਥਾਪ।","roman":"Ankhand atul prataap | sabh thaapio jih thaap |","meaning_en":"","page":103},{"gurmukhi":"ਅਨਖੇਦ ਭੇਦ ਅਛੇਦ। ਮੁਖਚਾਰ ਗਾਵਤ ਬੇਦ। ੪। ੩੪।","roman":"Ankhed bhed achhed | mukhchaar gaavat bed | 4 | 34 |","meaning_en":"","page":103}]},{"type":"verse","number":[5,35],"number_text":"੫। ੩੫।","page":103,"lines":[{"gurmukhi":"ਜਿਹ ਨੇਤਿ ਨਿਗਮ ਕਹੰਤ। ਮੁਖਚਾਰ ਬਕਤ ਬਿਅੰਤ।","roman":"Jih neti nigam kahant | mukhchaar bakat biant |","meaning_en":"","page":103},{"gurmukhi":"ਅਨਭਿਜ ਅਤੁਲ ਪ੍ਰਤਾਪ। ਅਨਖੰਡ ਅਮਿਤ ਅਥਾਪ। ੫। ੩੫।","roman":"Anbhij atul prataap | ankhand amit athaap | 5 | 35 |","meaning_en":"","page":103}]},{"type":"verse","number":[6,36],"number_text":"੬। ੩੬।","page":103,"lines":[{"gurmukhi":"ਜਿਹ ਕੀਨ ਜਗਤ ਪਸਾਰ। ਰਚਿਓ ਬਿਚਾਰਿ ਬਿਚਾਰਿ।","roman":"Jih keen jagat pasaar | rachio bichaari bichaari |","meaning_en":"","page":103},{"gurmukhi":"ਅਨੰਤ ਰੂਪ ਅਖੰਡ। ਅਤੁਲ ਪ੍ਰਤਾਪ ਪ੍ਰਚੰਡ। ੬। ੩੬।","roman":"Anant roop akhand | atul prataap prachand | 6 | 36 |","meaning_en":"","page":103}]},{"type":"verse","number":[7,37],"number_text":"੭। ੩੭।","page":103,"lines":[{"gurmukhi":"ਜਿਹ ਅੰਡ ਤੇ ਬ੍ਰਹਮੰਡ। ਕੀਨੇ ਸੁ ਚੌਦਹ ਖੰਡ।","roman":"Jih and te brahmand | keene su chaudah khand |","meaning_en":"","page":103},{"gurmukhi":"ਸਭ ਕੀਨ ਜਗਤ ਪਸਾਰ। ਅਬਿਯਕਤ ਰੂਪ ਉਦਾਰ। ੭। ੩੭।","roman":"Sabh keen jagat pasaar | abiykat roop udaar | 7 | 37 |","meaning_en":"","page":103}]},{"type":"verse","number":[8,38],"number_text":"੮। ੩੮।","page":103,"lines":[{"gurmukhi":"ਜਿਹ ਕੋਟਿ ਇੰਦ੍ਰ ਨ੍ਰਿਪਾਰ। ਕਈ ਬ੍ਰਹਮ ਬਿਸਨ ਬਿਚਾਰ।","roman":"Jih koti indr nripaar | kaee braham bisan bichaar |","meaning_en":"","page":103},{"gurmukhi":"ਕਈ ਰਾਮ ਕ੍ਰਿਸਨ ਰਸੂਲ। ਬਿਨ ਭਗਤਿ ਕੋ ਨ ਕਬੂਲ। ੮। ੩੮।","roman":"Kaee raam krisan rasool | bin bhagti ko na kabool | 8 | 38 |","meaning_en":"","page":103}]},{"type":"verse","number":[9,39],"number_text":"੯।੩੯।","page":104,"lines":[{"gurmukhi":"ਕਈ ਸਿੰਧ ਬਿੰਧ ਨਗਿੰਦ੍ਰ। ਕਈ ਮਛ ਕਛ ਫਨਿੰਦ੍ਰ।","roman":"Kaee sindh bindh nagindr | kaee machh kachh phanindr |","meaning_en":"","page":104},{"gurmukhi":"ਕਈ ਦੇਵਿ ਆਦਿ ਕੁਮਾਰਿ। ਕਈ ਕ੍ਰਿਸਨ ਬਿਸਨ ਅਵਤਾਰ। ੯।੩੯।","roman":"Kaee devi aadi kumaari | kaee krisan bisan avtaar | 9 | 39 |","meaning_en":"","page":104}]},{"type":"verse","number":[10,40],"number_text":"੧੦। ੪੦।","page":104,"lines":[{"gurmukhi":"ਕਈ ਇੰਦ੍ਰ ਬਾਰ ਬੁਹਾਰ। ਕਈ ਬੇਦ ਅਉ ਮੁਖਚਾਰ।","roman":"Kaee indr baar buhaar | kaee bed au mukhchaar |","meaning_en":"","page":104},{"gurmukhi":"ਕਈ ਰੁਦ੍ਰ ਛੁਦ੍ਰ ਸਰੂਪ। ਕਈ ਰਾਮ ਕ੍ਰਿਸਨ ਅਨੂਪ। ੧੦। ੪੦।","roman":"Kaee rudr chhudr saroop | kaee raam krisan anoop | 10 | 40 |","meaning_en":"","page":104}]},{"type":"verse","number":[11,41],"number_text":"੧੧। ੪੧।","page":104,"lines":[{"gurmukhi":"ਕਈ ਕੋਕ ਕਾਬਿ ਭਣੰਤ। ਕਈ ਬੇਦ ਭੇਦ ਕਹੰਤ।","roman":"Kaee kok kaabi bhanant | kaee bed bhed kahant |","meaning_en":"","page":104},{"gurmukhi":"ਕਈ ਸਾਸਤ੍ਰ ਸਿੰਮ੍ਰਿਤਿ ਬਖਾਨ। ਕਹੂੰ ਕਥਤ ਹੀ ਸੁ ਪੁਰਾਨ। ੧੧। ੪੧।","roman":"Kaee saasatr sinmriti bakhaan | kahoon kathat hee su puraan | 11 | 41 |","meaning_en":"","page":104}]},{"type":"verse","number":[12,42],"number_text":"੧੨। ੪੨।","page":104,"lines":[{"gurmukhi":"ਕਈ ਅਗਨਹੋਤ੍ਰ ਕਰੰਤ। ਕਈ ਉਰਧ ਤਾਪ ਦੁਰੰਤ।","roman":"Kaee aganhotr karant | kaee uradh taap durant |","meaning_en":"","page":104},{"gurmukhi":"ਕਈ ਉਰਧ ਬਾਹੁ ਸੰਨਿਆਸ। ਕਹੂੰ ਜੋਗ ਭੇਸ ਉਦਾਸ। ੧੨। ੪੨।","roman":"Kaee uradh baahu sanniaas | kahoon jog bhes udaas | 12 | 42 |","meaning_en":"","page":104}]},{"type":"verse","number":[13,43],"number_text":"੧੩। ੪੩।","page":104,"lines":[{"gurmukhi":"ਕਹੂੰ ਨਿਵਲੀ ਕਰਮ ਕਰੰਤ। ਕਹੂੰ ਪਉਨ ਅਹਾਰ ਦੁਰੰਤ।","roman":"Kahoon nivlee karam karant | kahoon paun ahaar durant |","meaning_en":"","page":104},{"gurmukhi":"ਕਹੂੰ ਤੀਰਥ ਦਾਨ ਅਪਾਰ। ਕਹੂੰ ਜਗ ਕਰਮ ਉਦਾਰ। ੧੩। ੪੩।","roman":"Kahoon teerath daan apaar | kahoon jag karam udaar | 13 | 43 |","meaning_en":"","page":104}]},{"type":"verse","number":[14,44],"number_text":"੧੪। ੪੪।","page":104,"lines":[{"gurmukhi":"ਕਹੂੰ ਅਗਨਹੋਤ੍ਰ ਅਨੂਪ। ਕਹੂੰ ਨਿਆਇ ਰਾਜ ਬਿਭੂਤ।","roman":"Kahoon aganhotr anoop | kahoon niaai raaj bibhoot |","meaning_en":"","page":104},{"gurmukhi":"ਕਹੂੰ ਸਾਸਤ੍ਰ ਸਿੰਮ੍ਰਿਤ ਰੀਤਿ। ਕਹੂੰ ਬੇਦ ਸਿਉ ਬਿਪ੍ਰੀਤਿ। ੧੪। ੪੪।","roman":"Kahoon saasatr sinmrit reeti | kahoon bed siu bipreeti | 14 | 44 |","meaning_en":"","page":104}]},{"type":"verse","number":[15,45],"number_text":"੧੫। ੪੫।","page":104,"lines":[{"gurmukhi":"ਕਈ ਦੇਸਿ ਦੇਸਿ ਫਿਰੰਤ। ਕਈ ਏਕ ਠੌਰ ਇਸਥੰਤ।","roman":"Kaee desi desi phirant | kaee ek thaur isthant |","meaning_en":"","page":104},{"gurmukhi":"ਕਹੂੰ ਕਰਤ ਜਲ ਮਹਿ ਜਾਪ। ਕਹੂੰ ਸਹਤ ਤਨ ਪਰ ਤਾਪ। ੧੫। ੪੫।","roman":"Kahoon karat jal mahi jaap | kahoon sahat tan par taap | 15 | 45 |","meaning_en":"","page":104}]},{"type":"verse","number":[16,46],"number_text":"੧੬। ੪੬।","page":104,"lines":[{"gurmukhi":"ਕਹੂੰ ਬਾਸ ਬਨਹਿ ਕਰੰਤ। ਕਹੂੰ ਤਾਪ ਤਨਹਿ ਸਹੰਤ।","roman":"Kahoon baas banhi karant | kahoon taap tanhi sahant |","meaning_en":"","page":104},{"gurmukhi":"ਕਹੂੰ ਗ੍ਰਿਹਸਤ ਧਰਮ ਅਪਾਰ। ਕਹੂੰ ਰਾਜ ਨੀਤਿ ਉਦਾਰ। ੧੬। ੪੬।","roman":"Kahoon grihsat dharam apaar | kahoon raaj neeti udaar | 16 | 46 |","meaning_en":"","page":104}]},{"type":"verse","number":[17,47],"number_text":"੧੭। ੪੭।","page":104,"lines":[{"gurmukhi":"ਕਹੂੰ ਰੋਗ ਰਹਤ ਅਭਰਮ। ਕਹੂੰ ਕਰਮ ਕਰਤ ਅਕਰਮ।","roman":"Kahoon rog rahat abhram | kahoon karam karat akram |","meaning_en":"","page":104},{"gurmukhi":"ਕਹੂੰ ਸੇਖ ਬ੍ਰਹਮ ਸਰੂਪ। ਕਹੂੰ ਨੀਤਿ ਰਾਜ ਅਨੂਪ। ੧੭। ੪੭।","roman":"Kahoon sekh braham saroop | kahoon neeti raaj anoop | 17 | 47 |","meaning_en":"","page":104}]},{"type":"verse","number":[18,48],"number_text":"੧੮। ੪੮।","page":104,"lines":[{"gurmukhi":"ਕਹੂੰ ਰੋਗ ਸੋਗ ਬਿਹੀਨ। ਕਹੂੰ ਏਕ ਭਗਤਿ ਅਧੀਨ।","roman":"Kahoon rog sog biheen | kahoon ek bhagti adheen |","meaning_en":"","page":104},{"gurmukhi":"ਕਹੂੰ ਰੰਕ ਰਾਜਕੁਮਾਰ। ਕਹੂੰ ਬੇਦ ਬਿਆਸ ਅਵਤਾਰ। ੧੮। ੪੮।","roman":"Kahoon rank raajkumaar | kahoon bed biaas avtaar | 18 | 48 |","meaning_en":"","page":104}]},{"type":"verse","number":[19,49],"number_text":"੧੯। ੪੯।","page":104,"lines":[{"gurmukhi":"ਕਈ ਬ੍ਰਹਮ ਬੇਦ ਰਟੰਤ। ਕਈ ਸੇਖ ਨਾਮ ਉਚਰੰਤ।","roman":"Kaee braham bed ratant | kaee sekh naam uchrant |","meaning_en":"","page":104},{"gurmukhi":"ਬੈਰਾਗਿ ਕਹੂੰ ਸਨਿਆਸਿ। ਕਹੂੰ ਫਿਰਤਿ ਰੂਪ ਉਦਾਸਿ। ੧੯। ੪੯।","roman":"Bairaagi kahoon saniaasi | kahoon phirti roop udaasi | 19 | 49 |","meaning_en":"","page":104}]},{"type":"verse","number":[20,50],"number_text":"੨੦। ੫੦।","page":104,"lines":[{"gurmukhi":"ਸਭ ਕਰਮ ਫੋਕਟ ਜਾਨ। ਸਭ ਧਰਮ ਨਿਹਫਲ ਮਾਨ।","roman":"Sabh karam phokat jaan | sabh dharam nihphal maan |","meaning_en":"","page":104},{"gurmukhi":"ਬਿਨੁ ਏਕ ਨਾਮ ਅਧਾਰ। ਸਭ ਕਰਮ ਭਰਮ ਬਿਚਾਰ। ੨੦। ੫੦।","roman":"Binu ek naam adhaar | sabh karam bharam bichaar | 20 | 50 |","meaning_en":"","page":104}]},{"type":"heading","kind":"chhand","name":"ਲਘੁਨਰਾਜ ਛੰਦ","gurmukhi":"ਤ੍ਵਪ੍ਰਸਾਦਿ। ਲਘੁਨਰਾਜ ਛੰਦ","roman":"Tvaprasaadi | laghunraaj chhand","meaning_en":"","page":104,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[1,51],"number_text":"੧। ੫੧।","page":104,"lines":[{"gurmukhi":"ਜਲੇ ਹਰੀ। ਥਲੇ ਹਰੀ। ਉਰੇ ਹਰੀ। ਬਨੇ ਹਰੀ। ੧। ੫੧।","roman":"Jale haree | thale haree | ure haree | bane haree | 1 | 51 |","meaning_en":"","page":104}]},{"type":"verse","number":[2,52],"number_text":"੨। ੫੨।","page":104,"lines":[{"gurmukhi":"ਗਿਰੇ ਹਰੀ। ਗੁਫੇ ਹਰੀ। ਛਿਤੇ ਹਰੀ। ਨਭੇ ਹਰੀ। ੨। ੫੨।","roman":"Gire haree | guphe haree | chhite haree | nabhe haree | 2 | 52 |","meaning_en":"","page":104}]},{"type":"verse","number":[3,53],"number_text":"੩। ੫੩।","page":104,"lines":[{"gurmukhi":"ਈਹਾ ਹਰੀ। ਊਹਾ ਹਰੀ। ਜਿਮੀ ਹਰੀ। ਜਮਾ ਹਰੀ। ੩। ੫੩।","roman":"Eehaa haree | oohaa haree | jimee haree | jamaa haree | 3 | 53 |","meaning_en":"","page":104}]},{"type":"verse","number":[4,54],"number_text":"੪। ੫੪।","page":104,"lines":[{"gurmukhi":"ਅਲੇਖ ਹਰੀ। ਅਭੇਖ ਹਰੀ। ਅਦੋਖ ਹਰੀ। ਅਦ੍ਵੈਖ ਹਰੀ। ੪। ੫੪।","roman":"Alekh haree | abhekh haree | adokh haree | advaikh haree | 4 | 54 |","meaning_en":"","page":104}]},{"type":"verse","number":[5,55],"number_text":"੫। ੫੫।","page":105,"lines":[{"gurmukhi":"ਅਕਾਲ ਹਰੀ। ਅਪਾਲ ਹਰੀ। ਅਛੇਦ ਹਰੀ। ਅਭੇਦ ਹਰੀ। ੫। ੫੫।","roman":"Akaal haree | apaal haree | achhed haree | abhed haree | 5 | 55 |","meaning_en":"","page":105}]},{"type":"verse","number":[6,56],"number_text":"੬। ੫੬।","page":105,"lines":[{"gurmukhi":"ਅਜੰਤ੍ਰ ਹਰੀ। ਅਮੰਤ੍ਰ ਹਰੀ। ਸੁਤੇਜ ਹਰੀ। ਅਤੰਤ੍ਰ ਹਰੀ। ੬। ੫੬।","roman":"Ajantr haree | amantr haree | sutej haree | atantr haree | 6 | 56 |","meaning_en":"","page":105}]},{"type":"verse","number":[7,57],"number_text":"੭। ੫੭।","page":105,"lines":[{"gurmukhi":"ਅਜਾਤਿ ਹਰੀ। ਅਪਾਤਿ ਹਰੀ। ਅਮਿਤ ਹਰੀ। ਅਮਾਤ ਹਰੀ। ੭। ੫੭।","roman":"Ajaati haree | apaati haree | amit haree | amaat haree | 7 | 57 |","meaning_en":"","page":105}]},{"type":"verse","number":[8,58],"number_text":"੮। ੫੮।","page":105,"lines":[{"gurmukhi":"ਅਰੋਗ ਹਰੀ। ਅਸੋਗ ਹਰੀ। ਅਭਰਮ ਹਰੀ। ਅਕਰਮ ਹਰੀ। ੮। ੫੮।","roman":"Arog haree | asog haree | abhram haree | akram haree | 8 | 58 |","meaning_en":"","page":105}]},{"type":"verse","number":[9,59],"number_text":"੯। ੫੯।","page":105,"lines":[{"gurmukhi":"ਅਜੈ ਹਰੀ। ਅਭੈ ਹਰੀ। ਅਭੇਦ ਹਰੀ। ਅਛੇਦ ਹਰੀ। ੯। ੫੯।","roman":"Ajai haree | abhai haree | abhed haree | achhed haree | 9 | 59 |","meaning_en":"","page":105}]},{"type":"verse","number":[10,60],"number_text":"੧੦। ੬੦।","page":105,"lines":[{"gurmukhi":"ਅਖੰਡ ਹਰੀ। ਅਭੰਡ ਹਰੀ। ਅਡੰਡ ਹਰੀ। ਪ੍ਰਚੰਡ ਹਰੀ। ੧੦। ੬੦।","roman":"Akhand haree | abhand haree | adand haree | prachand haree | 10 | 60 |","meaning_en":"","page":105}]},{"type":"verse","number":[11,61],"number_text":"੧੧। ੬੧।","page":105,"lines":[{"gurmukhi":"ਅਤੇਵ ਹਰੀ। ਅਭੇਵ ਹਰੀ। ਅਜੇਵ ਹਰੀ। ਅਛੇਵ ਹਰੀ। ੧੧। ੬੧।","roman":"Atev haree | abhev haree | ajev haree | achhev haree | 11 | 61 |","meaning_en":"","page":105}]},{"type":"verse","number":[12,62],"number_text":"੧੨। ੬੨।","page":105,"lines":[{"gurmukhi":"ਭਜੋ ਹਰੀ। ਥਪੋ ਹਰੀ। ਤਪੋ ਹਰੀ। ਜਪੋ ਹਰੀ। ੧੨। ੬੨।","roman":"Bhajo haree | thapo haree | tapo haree | japo haree | 12 | 62 |","meaning_en":"","page":105}]},{"type":"verse","number":[13,63],"number_text":"੧੩। ੬੩।","page":105,"lines":[{"gurmukhi":"ਜਲਸ ਤੁਹੀ। ਥਲਸ ਤੁਹੀ। ਨਦਿਸ ਤੁਹੀ। ਨਦਸ ਤੁਹੀ। ੧੩। ੬੩।","roman":"Jalas tuhee | thalas tuhee | nadis tuhee | nadas tuhee | 13 | 63 |","meaning_en":"","page":105}]},{"type":"verse","number":[14,64],"number_text":"੧੪। ੬੪।","page":105,"lines":[{"gurmukhi":"ਬ੍ਰਿਛਸ ਤੁਹੀ। ਪਤਸ ਤੁਹੀ। ਛਿਤਸ ਤੁਹੀ। ਉਰਧਸ ਤੁਹੀ। ੧੪। ੬੪।","roman":"Brichhas tuhee | patas tuhee | chhitas tuhee | urdhas tuhee | 14 | 64 |","meaning_en":"","page":105}]},{"type":"verse","number":[15,65],"number_text":"੧੫। ੬੫।","page":105,"lines":[{"gurmukhi":"ਭਜਸ ਤੁਅੰ। ਭਜਸ ਤੁਅੰ। ਰਟਸ ਤੁਅੰ। ਠਟਸ ਤੁਅੰ। ੧੫। ੬੫।","roman":"Bhajas tuan | bhajas tuan | ratas tuan | thatas tuan | 15 | 65 |","meaning_en":"","page":105}]},{"type":"verse","number":[16,66],"number_text":"੧੬। ੬੬।","page":105,"lines":[{"gurmukhi":"ਜਿਮੀ ਤੁਹੀ। ਜਮਾ ਤੁਹੀ। ਮਕੀ ਤੁਹੀ। ਮਕਾ ਤੁਹੀ। ੧੬। ੬੬।","roman":"Jimee tuhee | jamaa tuhee | makee tuhee | makaa tuhee | 16 | 66 |","meaning_en":"","page":105}]},{"type":"verse","number":[17,67],"number_text":"੧੭। ੬੭।","page":105,"lines":[{"gurmukhi":"ਅਭੂ ਤੁਹੀ। ਅਭੈ ਤੁਹੀ। ਅਛੂ ਤੁਹੀ। ਅਛੈ ਤੁਹੀ। ੧੭। ੬੭।","roman":"Abhoo tuhee | abhai tuhee | achhoo tuhee | achhai tuhee | 17 | 67 |","meaning_en":"","page":105}]},{"type":"verse","number":[18,68],"number_text":"੧੮। ੬੮।","page":105,"lines":[{"gurmukhi":"ਜਤਸ ਤੁਹੀ। ਬ੍ਰਤਸ ਤੁਹੀ। ਗਤਸ ਤੁਹੀ। ਮਤਸ ਤੁਹੀ। ੧੮। ੬੮।","roman":"Jatas tuhee | bratas tuhee | gatas tuhee | matas tuhee | 18 | 68 |","meaning_en":"","page":105}]},{"type":"verse","number":[19,69],"number_text":"੧੯। ੬੯।","page":105,"lines":[{"gurmukhi":"ਤੁਹੀ ਤੁਹੀ। ਤੁਹੀ ਤੁਹੀ। ਤੁਹੀ ਤੁਹੀ। ਤੁਹੀ ਤੁਹੀ। ੧੯। ੬੯।","roman":"Tuhee tuhee | tuhee tuhee | tuhee tuhee | tuhee tuhee | 19 | 69 |","meaning_en":"","page":105}]},{"type":"verse","number":[20,70],"number_text":"੨੦। ੭੦।","page":105,"lines":[{"gurmukhi":"ਤੁਹੀ ਤੁਹੀ। ਤੁਹੀ ਤੁਹੀ। ਤੁਹੀ ਤੁਹੀ। ਤੁਹੀ ਤੁਹੀ। ੨੦। ੭੦।","roman":"Tuhee tuhee | tuhee tuhee | tuhee tuhee | tuhee tuhee | 20 | 70 |","meaning_en":"","page":105}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਤ੍ਵਪ੍ਰਸਾਦਿ। ਕਬਿਤੁ","roman":"Tvaprasaadi | kabitu","meaning_en":"","page":105,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[1,71],"number_text":"੧।੭੧।","page":105,"lines":[{"gurmukhi":"ਖੂਕ ਮਲਹਾਰੀ ਗਜ ਗਦਾਹਾ ਬਿਭੂਤ ਧਾਰੀ","roman":"Khook malhaaree gaj gadaahaa bibhoot dhaaree","meaning_en":"","page":105},{"gurmukhi":"ਗਿਦੂਆ ਮਸਾਨ ਬਾਸ ਕਰਿਓਈ ਕਰਤ ਹੈ।","roman":"Gidooaa masaan baas karioee karat hai |","meaning_en":"","page":105},{"gurmukhi":"ਘੁਘੂ ਮਟਬਾਸੀ ਲਗੇ ਡੋਲਤ ਉਦਾਸੀ ਮ੍ਰਿਗ","roman":"Ghughoo matbaasee lage dolat udaasee mrig","meaning_en":"","page":105},{"gurmukhi":"ਤਰਵਰ ਸਦੀਵ ਮੋਨ ਸਾਧੇ ਈ ਮਰਤ ਹੈ।","roman":"Tarvar sadeev mon saadhe ee marat hai |","meaning_en":"","page":105},{"gurmukhi":"ਬਿੰਦ ਕੇ ਸਧਯਾ ਤਾਹਿ ਹੀਜ ਕੀ ਬਡਯਾ ਦੇਤ","roman":"Bind ke sadhyaa taahi heej kee badyaa det","meaning_en":"","page":105},{"gurmukhi":"ਬੰਦਰਾ ਸਦੀਵ ਪਾਇ ਨਾਗੇ ਈ ਫਿਰਤ ਹੈ।","roman":"Bandraa sadeev paai naage ee phirat hai |","meaning_en":"","page":105},{"gurmukhi":"ਅੰਗਨਾ ਅਧੀਨ ਕਾਮ ਕ੍ਰੋਧ ਮੈ ਪ੍ਰਬੀਨ","roman":"Angnaa adheen kaam krodh mai prabeen","meaning_en":"","page":105},{"gurmukhi":"ਏਕ ਗਿਆਨ ਕੇ ਬਿਹੀਨ ਛੀਨ ਕੈਸੇ ਕੈ ਤਰਤ ਹੈ।੧।੭੧।","roman":"Ek giaan ke biheen chheen kaise kai tarat hai | 1 | 71 |","meaning_en":"","page":105}]},{"type":"verse","number":[2,72],"number_text":"੨। ੭੨।","page":106,"lines":[{"gurmukhi":"ਭੂਤ ਬਨਚਾਰੀ ਛਿਤ ਛਉਨਾ ਸਭੈ ਦੁਧਾਧਾਰੀ","roman":"Bhoot banchaaree chhit chhaunaa sabhai dudhaadhaaree","meaning_en":"","page":106},{"gurmukhi":"ਪਉਨ ਕੇ ਅਹਾਰੀ ਸੁ ਭੁਜੰਗ ਜਾਨੀਅਤੁ ਹੈ।","roman":"Paun ke ahaaree su bhujang jaaneeatu hai |","meaning_en":"","page":106},{"gurmukhi":"ਤ੍ਰਿਣ ਕੇ ਭਛਯਾ ਧਨ ਲੋਭ ਕੇ ਤਜਯਾ","roman":"Trin ke bhachhyaa dhan lobh ke tajyaa","meaning_en":"","page":106},{"gurmukhi":"ਤੇ ਤੋ ਗਊਅਨ ਕੇ ਜਯਾ ਬ੍ਰਿਖਭਯਾ ਮਾਨੀਅਤੁ ਹੈ।","roman":"Te to gaooan ke jayaa brikhabhyaa maaneeatu hai |","meaning_en":"","page":106},{"gurmukhi":"ਨਭ ਕੇ ਉਡਯਾ ਤਾਹਿ ਪੰਛੀ ਕੀ ਬਡਯਾ ਦੇਤ","roman":"Nabh ke udyaa taahi panchhee kee badyaa det","meaning_en":"","page":106},{"gurmukhi":"ਬਗੁਲਾ ਬਿੜਾਲ ਬ੍ਰਿਕ ਧਿਆਨੀ ਠਾਨੀਅਤੁ ਹੈ।","roman":"Bagulaa biraal brik dhiaanee thaaneeatu hai |","meaning_en":"","page":106},{"gurmukhi":"ਜੇਤੋ ਬਡੇ ਗਿਆਨੀ ਤਿਨੋ ਜਾਨੀ ਪੈ ਬਖਾਨੀ ਨਾਹਿ","roman":"Jeto bade giaanee tino jaanee pai bakhaanee naahi","meaning_en":"","page":106},{"gurmukhi":"ਐਸੇ ਨ ਪ੍ਰਪੰਚ ਮਨਿ ਭੂਲਿ ਆਨੀਅਤੁ ਹੈ। ੨। ੭੨।","roman":"Aise na prapanch mani bhooli aaneeatu hai | 2 | 72 |","meaning_en":"","page":106}]},{"type":"verse","number":[3,73],"number_text":"੩। ੭੩।","page":106,"lines":[{"gurmukhi":"ਭੂਮਿ ਕੇ ਬਸਯਾ ਤਾਹਿ ਭੂਚਰੀ ਕੈ ਜਯਾ ਕਹੈ","roman":"Bhoomi ke basyaa taahi bhoochree kai jayaa kahai","meaning_en":"","page":106},{"gurmukhi":"ਨਭ ਕੇ ਉਡਯਾ ਸੋ ਚਿਰਯਾ ਕੈ ਬਖਾਨੀਐ।","roman":"Nabh ke udyaa so chiryaa kai bakhaaneeai |","meaning_en":"","page":106},{"gurmukhi":"ਫਲ ਕੇ ਭਛਯਾ ਤਾਹਿ ਬਾਂਦਰੀ ਕੇ ਜਯਾ ਕਹੈ","roman":"Phal ke bhachhyaa taahi baandree ke jayaa kahai","meaning_en":"","page":106},{"gurmukhi":"ਆਦਿਸ ਫਿਰਯਾ ਤੇਤੋ ਭੂਤ ਕੇ ਪਛਾਨੀਐ।","roman":"Aadis phiryaa teto bhoot ke pachhaaneeai |","meaning_en":"","page":106},{"gurmukhi":"ਜਲ ਕੇ ਤਰਯਾ ਕੌ ਗੰਗੇਰੀ ਸੀ ਕਹਤ ਜਗ","roman":"Jal ke taryaa kau gangeree see kahat jag","meaning_en":"","page":106},{"gurmukhi":"ਆਗ ਕੇ ਭਛਯਾ ਸੋ ਚਕੋਰ ਸਮ ਮਾਨੀਐ।","roman":"Aag ke bhachhyaa so chakor sam maaneeai |","meaning_en":"","page":106},{"gurmukhi":"ਸੂਰਜ ਸਿਵਯਾ ਤਾਹਿ ਕਉਲ ਕੀ ਬਡਯਾ ਦੇਤ","roman":"Sooraj sivyaa taahi kaul kee badyaa det","meaning_en":"","page":106},{"gurmukhi":"ਚੰਦ੍ਰਮਾ ਸਿਵਯਾ ਕੌ ਕਵੀ ਕੈ ਪਹਿਚਾਨੀਐ। ੩। ੭੩।","roman":"Chandramaa sivyaa kau kavee kai pahichaaneeai | 3 | 73 |","meaning_en":"","page":106}]},{"type":"verse","number":[4,74],"number_text":"੪। ੭੪।","page":106,"lines":[{"gurmukhi":"ਨਾਰਾਇਣ ਕਛ ਮਛ ਤੇਂਦੂਆ ਕਹਤ ਸਭ","roman":"Naaraain kachh machh tendooaa kahat sabh","meaning_en":"","page":106},{"gurmukhi":"ਕਉਲਨਾਭਿ ਕਉਲ ਜਿਹ ਤਾਲ ਮੈ ਰਹਤੁ ਹੈ।","roman":"Kaulnaabhi kaul jih taal mai rahtu hai |","meaning_en":"","page":106},{"gurmukhi":"ਗੋਪੀਨਾਥ ਗੂਜਰ ਗੋਪਾਲ ਸਬੈ ਧੇਨਚਾਰੀ","roman":"Gopeenaath goojar gopaal sabai dhenchaaree","meaning_en":"","page":106},{"gurmukhi":"ਰਿਖੀਕੇਸ ਨਾਮ ਕੈ ਮਹੰਤ ਲਹੀਅਤ ਹੈ।","roman":"Rikheekes naam kai mahant laheeat hai |","meaning_en":"","page":106},{"gurmukhi":"ਮਾਧਵ ਭਵਰ ਔ ਅਟੇਰੂ ਕੌ ਕਨਯਾ ਨਾਮ","roman":"Maadhav bhavar au ateroo kau kanyaa naam","meaning_en":"","page":106},{"gurmukhi":"ਕੰਸ ਕੇ ਬਧਯਾ ਜਮਦੂਤ ਕਹੀਅਤੁ ਹੈ।","roman":"Kans ke badhyaa jamdoot kaheeatu hai |","meaning_en":"","page":106},{"gurmukhi":"ਮੂੜ ਰੂੜਿ ਪੀਟਤ ਨ ਗੂੜਤਾ ਕੌ ਭੇਦ ਪਾਵੈ","roman":"Moor roori peetat na goortaa kau bhed paavai","meaning_en":"","page":106},{"gurmukhi":"ਪੂਜਤ ਨ ਤਾਹਿ ਜਾ ਕੇ ਰਾਖੇ ਰਹੀਅਤੁ ਹੈ। ੪। ੭੪।","roman":"Poojat na taahi jaa ke raakhe raheeatu hai | 4 | 74 |","meaning_en":"","page":106}]},{"type":"verse","number":[5,75],"number_text":"੫। ੭੫।","page":106,"lines":[{"gurmukhi":"ਬਿਸ੍ਵਪਾਲ ਜਗਤ ਕਾਲ ਦੀਨ ਦਿਆਲ ਬੈਰੀ ਸਾਲ","roman":"Bisvapaal jagat kaal deen diaal bairee saal","meaning_en":"","page":106},{"gurmukhi":"ਸਦਾ ਪ੍ਰਤਿਪਾਲ ਜਮ ਜਾਲ ਤੇ ਰਹਤੁ ਹੈ।","roman":"Sadaa pratipaal jam jaal te rahtu hai |","meaning_en":"","page":106},{"gurmukhi":"ਜੋਗੀ ਜਟਾਧਾਰੀ ਸਤੀ ਸਾਚੇ ਬੜੇ ਬ੍ਰਹਮਚਾਰੀ","roman":"Jogee jataadhaaree satee saache bare brahamchaaree","meaning_en":"","page":106},{"gurmukhi":"ਧਿਆਨ ਕਾਜ ਭੂਖ ਪਿਆਸ ਦੇਹ ਪੈ ਸਹਤ ਹੈ।","roman":"Dhiaan kaaj bhookh piaas deh pai sahat hai |","meaning_en":"","page":106},{"gurmukhi":"ਨਿਉਲੀ ਕਰਮ ਜਲ ਹੋਮ ਪਾਵਕ ਪਵਨ ਹੋਮ","roman":"Niulee karam jal hom paavak pavan hom","meaning_en":"","page":107},{"gurmukhi":"ਅਧੋ ਮੁਖ ਏਕ ਪਾਇ ਠਾਢੇ ਨਿਬਹਤ ਹੈ।","roman":"Adho mukh ek paai thaadhe nibhat hai |","meaning_en":"","page":107},{"gurmukhi":"ਮਾਨਵ ਫਨਿੰਦ ਦੇਵ ਦਾਨਵ ਨ ਪਾਵੈ ਭੇਦ","roman":"Maanav phanind dev daanav na paavai bhed","meaning_en":"","page":107},{"gurmukhi":"ਬੇਦ ਔ ਕਤੇਬ ਨੇਤਿ ਨੇਤਿ ਕੈ ਕਹਤ ਹੈ। ੫। ੭੫।","roman":"Bed au kateb neti neti kai kahat hai | 5 | 75 |","meaning_en":"","page":107}]},{"type":"verse","number":[6,76],"number_text":"੬। ੭੬।","page":107,"lines":[{"gurmukhi":"ਨਾਚਤ ਫਿਰਤ ਮੋਰ ਬਾਦਰ ਕਰਤ ਘੋਰ","roman":"Naachat phirat mor baadar karat ghor","meaning_en":"","page":107},{"gurmukhi":"ਦਾਮਿਨੀ ਅਨੇਕ ਭਾਉ ਕਰਿਓ ਈ ਕਰਤ ਹੈ।","roman":"Daaminee anek bhaau kario ee karat hai |","meaning_en":"","page":107},{"gurmukhi":"ਚੰਦ੍ਰਮਾ ਤੇ ਸੀਤਲ ਨ ਸੂਰਜ ਕੇ ਤਪਤ ਤੇਜ","roman":"Chandramaa te seetal na sooraj ke tapat tej","meaning_en":"","page":107},{"gurmukhi":"ਇੰਦ੍ਰ ਸੌ ਨ ਰਾਜਾ ਭਵ ਭੂਮਿ ਕੌ ਭਰਤ ਹੈ।","roman":"Indr sau na raajaa bhav bhoomi kau bharat hai |","meaning_en":"","page":107},{"gurmukhi":"ਸਿਵ ਸੇ ਤਪਸੀ ਆਦਿ ਬ੍ਰਹਮਾ ਸੇ ਨ ਬੇਦਚਾਰੀ","roman":"Siv se tapsee aadi brahmaa se na bedchaaree","meaning_en":"","page":107},{"gurmukhi":"ਸਨਤ ਕੁਮਾਰ ਸੀ ਤਪਸਿਆ ਨ ਅਨਤ ਹੈ।","roman":"Sanat kumaar see tapsiaa na anat hai |","meaning_en":"","page":107},{"gurmukhi":"ਗਿਆਨ ਕੇ ਬਿਹੀਨ ਕਾਲ ਫਾਸ ਕੇ ਅਧੀਨ ਸਦਾ","roman":"Giaan ke biheen kaal phaas ke adheen sadaa","meaning_en":"","page":107},{"gurmukhi":"ਜੁਗਨ ਕੀ ਚਉਕਰੀ ਫਿਰਾਏ ਈ ਫਿਰਤ ਹੈ। ੬। ੭੬।","roman":"Jugan kee chaukree phiraae ee phirat hai | 6 | 76 |","meaning_en":"","page":107}]},{"type":"verse","number":[7,77],"number_text":"੭।੭੭।","page":107,"lines":[{"gurmukhi":"ਏਕ ਸਿਵ ਭਏ ਏਕ ਗਏ ਏਕ ਫੇਰ ਭਏ","roman":"Ek siv bhae ek gae ek pher bhae","meaning_en":"","page":107},{"gurmukhi":"ਰਾਮਚੰਦ੍ਰ ਕ੍ਰਿਸਨ ਕੇ ਅਵਤਾਰ ਭੀ ਅਨੇਕ ਹੈ।","roman":"Raamchandr krisan ke avtaar bhee anek hai |","meaning_en":"","page":107},{"gurmukhi":"ਬ੍ਰਹਮਾ ਅਰੁ ਬਿਸਨੁ ਕੇਤੇ ਬੇਦ ਔ ਪੁਰਾਨ ਕੇਤੇ","roman":"Brahmaa aru bisnu kete bed au puraan kete","meaning_en":"","page":107},{"gurmukhi":"ਸਿੰਮ੍ਰਿਤ ਸਮੂਹਨ ਕੇ ਹੁਇ ਹੁਇ ਬਿਤਏ ਹੈ।","roman":"Sinmrit samoohan ke hui hui bitae hai |","meaning_en":"","page":107},{"gurmukhi":"ਮੋਨਦੀ ਮਦਾਰ ਕੇਤੇ ਅਸੁਨੀ ਕੁਮਾਰ ਕੇਤੇ","roman":"Mondee madaar kete asunee kumaar kete","meaning_en":"","page":107},{"gurmukhi":"ਅੰਸਾ ਅਵਤਾਰ ਕੇਤੇ ਕਾਲ ਬਸਿ ਭਏ ਹੈ।","roman":"Ansaa avtaar kete kaal basi bhae hai |","meaning_en":"","page":107},{"gurmukhi":"ਪੀਰ ਔ ਪਿਕਾਬਰ ਕੇਤੇ ਗਨੇ ਨ ਪਰਤ ਏਤੇ","roman":"Peer au pikaabar kete gane na parat ete","meaning_en":"","page":107},{"gurmukhi":"ਭੂਮਿ ਹੀ ਤੇ ਹੁਇ ਕੈ ਫੇਰਿ ਭੂਮਿ ਹੀ ਮਿਲਏ ਹੈ।੭।੭੭।","roman":"Bhoomi hee te hui kai pheri bhoomi hee milae hai | 7 | 77 |","meaning_en":"","page":107}]},{"type":"verse","number":[8,78],"number_text":"੮। ੭੮।","page":107,"lines":[{"gurmukhi":"ਜੋਗੀ ਜਤੀ ਬ੍ਰਹਮਚਾਰੀ ਬਡੇ ਬਡੇ ਛਤ੍ਰਧਾਰੀ","roman":"Jogee jatee brahamchaaree bade bade chhatradhaaree","meaning_en":"","page":107},{"gurmukhi":"ਛਤ੍ਰ ਹੀ ਕੀ ਛਾਇਆ ਕਈ ਕੋਸ ਲੌ ਚਲਤ ਹੈ।","roman":"Chhatr hee kee chhaaiaa kaee kos lau chalat hai |","meaning_en":"","page":107},{"gurmukhi":"ਬਡੇ ਬਡੇ ਰਾਜਨ ਕੇ ਦਾਬਤਿ ਫਿਰਤਿ ਦੇਸ","roman":"Bade bade raajan ke daabti phirti des","meaning_en":"","page":107},{"gurmukhi":"ਬਡੇ ਬਡੇ ਰਾਜਨ ਕੇ ਦ੍ਰਪ ਕੋ ਦਲਤੁ ਹੈ।","roman":"Bade bade raajan ke drap ko daltu hai |","meaning_en":"","page":107},{"gurmukhi":"ਮਾਨ ਸੇ ਮਹੀਪ ਅਉ ਦਿਲੀਪ ਕੈਸੇ ਛਤ੍ਰਧਾਰੀ","roman":"Maan se maheep au dileep kaise chhatradhaaree","meaning_en":"","page":107},{"gurmukhi":"ਬਡੋ ਅਭਿਮਾਨ ਭੁਜ ਦੰਡ ਕੋ ਕਰਤ ਹੈ।","roman":"Bado abhimaan bhuj dand ko karat hai |","meaning_en":"","page":107},{"gurmukhi":"ਦਾਰਾ ਸੇ ਦਲੀਸਰ ਦੁਰਜੋਧਨ ਸੇ ਮਾਨਧਾਰੀ","roman":"Daaraa se daleesar durjodhan se maandhaaree","meaning_en":"","page":107},{"gurmukhi":"ਭੋਗਿ ਭੋਗਿ ਭੂਮਿ ਅੰਤਿ ਭੂਮਿ ਮੈ ਮਿਲਤ ਹੈ। ੮। ੭੮।","roman":"Bhogi bhogi bhoomi anti bhoomi mai milat hai | 8 | 78 |","meaning_en":"","page":107}]},{"type":"verse","number":[9,79],"number_text":"੯। ੭੯।","page":107,"lines":[{"gurmukhi":"ਸਿਜਦੇ ਕਰੇ ਅਨੇਕ ਤੋਪਚੀ ਕਪਟ ਭੇਸ","roman":"Sijde kare anek topchee kapat bhes","meaning_en":"","page":107},{"gurmukhi":"ਪੋਸਤੀ ਅਨੇਕਦਾ ਨਿਵਾਵਤ ਹੈ ਸੀਸ ਕੌ।","roman":"Postee anekdaa nivaavat hai sees kau |","meaning_en":"","page":107},{"gurmukhi":"ਕਹਾ ਭਇਓ ਮਲ ਜੌ ਪੈ ਕਾਢਤ ਅਨੇਕ ਡੰਡ","roman":"Kahaa bhaio mal jau pai kaadhat anek dand","meaning_en":"","page":108},{"gurmukhi":"ਸੋ ਤੌ ਨ ਡੰਡੌਤ ਅਸਟਾਂਗ ਅਥਿਤੀਸ ਕੌ।","roman":"So tau na dandaut astaang athitees kau |","meaning_en":"","page":108},{"gurmukhi":"ਕਹਾ ਭਇਓ ਰੋਗੀ ਜੋ ਪੈ ਡਾਰ੍ਯੋ ਰਹ੍ਯੋ ਉਰਧੁ ਮੁਖਿ","roman":"Kahaa bhaio rogee jo pai daaryo rahyo urdhu mukhi","meaning_en":"","page":108},{"gurmukhi":"ਮਨ ਤੇ ਨ ਮੂੰਡ ਨਿਹੁਰਾਯੋ ਆਦਿ ਈਸ ਕੌ।","roman":"Man te na moond nihuraayo aadi ees kau |","meaning_en":"","page":108},{"gurmukhi":"ਕਾਮਨਾ ਅਧੀਨ ਸਦਾ ਦਾਮਨਾ ਪ੍ਰਬੀਨ","roman":"Kaamnaa adheen sadaa daamnaa prabeen","meaning_en":"","page":108},{"gurmukhi":"ਏਕ ਭਾਵਨਾ ਬਿਹੀਨ ਕੈਸੇ ਪਾਵੈ ਜਗਦੀਸ ਕੌ। ੯। ੭੯।","roman":"Ek bhaavnaa biheen kaise paavai jagdees kau | 9 | 79 |","meaning_en":"","page":108}]},{"type":"verse","number":[10,80],"number_text":"੧੦। ੮੦।","page":108,"lines":[{"gurmukhi":"ਸੀਸ ਪਟਕਤ ਜਾ ਕੇ ਕਾਨ ਮੈ ਖਜੂਰਾ ਧਸੈ","roman":"Sees patkat jaa ke kaan mai khajooraa dhasai","meaning_en":"","page":108},{"gurmukhi":"ਮੂੰਡ ਛਟਕਤ ਮਿਤ੍ਰ ਪੁਤ੍ਰ ਹੂੰ ਕੇ ਸੋਕ ਸੌ।","roman":"Moond chhatkat mitr putr hoon ke sok sau |","meaning_en":"","page":108},{"gurmukhi":"ਆਕ ਕੋ ਚਰਯਾ ਫਲ ਫੂਲ ਕੋ ਭਛਯਾ","roman":"Aak ko charyaa phal phool ko bhachhyaa","meaning_en":"","page":108},{"gurmukhi":"ਸਦਾ ਬਨ ਕੋ ਭ੍ਰਮਯਾ ਅਉਰ ਦੂਸਰੋ ਨ ਬੋਕ ਸੌ।","roman":"Sadaa ban ko bhramyaa aur doosro na bok sau |","meaning_en":"","page":108},{"gurmukhi":"ਕਹਾ ਭਯੋ ਭੇਡ ਜਉ ਘਸਤ ਸੀਸ ਬ੍ਰਿਛਨ ਸੌ","roman":"Kahaa bhayo bhed jau ghasat sees brichhan sau","meaning_en":"","page":108},{"gurmukhi":"ਮਾਟੀ ਕੋ ਭਛਯਾ ਬੋਲ ਪੂਛ ਲੀਜੈ ਜੋਕ ਸੌ।","roman":"Maatee ko bhachhyaa bol poochh leejai jok sau |","meaning_en":"","page":108},{"gurmukhi":"ਕਾਮਨਾ ਅਧੀਨ ਕਾਮ ਕ੍ਰੋਧ ਮੈ ਪ੍ਰਬੀਨ","roman":"Kaamnaa adheen kaam krodh mai prabeen","meaning_en":"","page":108},{"gurmukhi":"ਏਕ ਭਾਵਨਾ ਬਿਹੀਨ ਕੈਸੇ ਭੇਟੈ ਪਰਲੋਕ ਸੌ। ੧੦। ੮੦।","roman":"Ek bhaavnaa biheen kaise bhetai parlok sau | 10 | 80 |","meaning_en":"","page":108}]},{"type":"verse","number":[11,81],"number_text":"੧੧। ੮੧।","page":108,"lines":[{"gurmukhi":"ਨਾਚਿਓ ਈ ਕਰਤ ਮੋਰ ਦਾਦਰ ਕਰਤ ਸੋਰ","roman":"Naachio ee karat mor daadar karat sor","meaning_en":"","page":108},{"gurmukhi":"ਸਦਾ ਘਨਘੋਰ ਘਨ ਕਰਿਓ ਈ ਕਰਤ ਹੈ।","roman":"Sadaa ghanghor ghan kario ee karat hai |","meaning_en":"","page":108},{"gurmukhi":"ਏਕ ਪਾਇ ਠਾਢੇ ਸਦਾ ਬਨ ਮੈ ਰਹਤ ਬ੍ਰਿਛ","roman":"Ek paai thaadhe sadaa ban mai rahat brichh","meaning_en":"","page":108},{"gurmukhi":"ਫੂਕਿ ਫੂਕਿ ਪਾਵ ਭੂਮਿ ਸ੍ਰਾਵਗ ਧਰਤ ਹੈ।","roman":"Phooki phooki paav bhoomi sraavag dharat hai |","meaning_en":"","page":108},{"gurmukhi":"ਪਾਹਨ ਅਨੇਕ ਜੁਗ ਏਕ ਠਉਰ ਬਾਸੁ ਕਰੈ","roman":"Paahan anek jug ek thaur baasu karai","meaning_en":"","page":108},{"gurmukhi":"ਕਾਗ ਅਉਰ ਚੀਲ ਦੇਸਿ ਦੇਸਿ ਬਿਚਰਤ ਹੈ।","roman":"Kaag aur cheel desi desi bichrat hai |","meaning_en":"","page":108},{"gurmukhi":"ਗਿਆਨ ਕੇ ਬਿਹੀਨ ਮਹਾ ਦਾਨ ਮੈ ਨ ਹੂਜੈ ਲੀਨ","roman":"Giaan ke biheen mahaa daan mai na hoojai leen","meaning_en":"","page":108},{"gurmukhi":"ਭਾਵਨਾ ਬਿਹੀਨ ਦੀਨ ਕੈਸੇ ਕੈ ਤਰਤ ਹੈ। ੧੧। ੮੧।","roman":"Bhaavnaa biheen deen kaise kai tarat hai | 11 | 81 |","meaning_en":"","page":108}]},{"type":"verse","number":[12,82],"number_text":"੧੨। ੮੨।","page":108,"lines":[{"gurmukhi":"ਜੈਸੇ ਏਕ ਸ੍ਵਾਂਗੀ ਕਹੂੰ ਜੋਗੀਆ ਬੈਰਾਗੀ ਬਨੈ","roman":"Jaise ek svaangee kahoon jogeeaa bairaagee banai","meaning_en":"","page":108},{"gurmukhi":"ਕਹੂੰ ਸਨਿਆਸਿ ਭੇਸ ਬਨ ਕੈ ਦਿਖਾਵਈ।","roman":"Kahoon saniaasi bhes ban kai dikhaavaee |","meaning_en":"","page":108},{"gurmukhi":"ਕਹੂੰ ਪਉਨਹਾਰੀ ਕਹੂੰ ਬੈਠੇ ਲਾਇ ਤਾਰੀ","roman":"Kahoon paunhaaree kahoon baithe laai taaree","meaning_en":"","page":108},{"gurmukhi":"ਕਹੂੰ ਲੋਭ ਕੀ ਖੁਮਾਰੀ ਸੌ ਅਨੇਕ ਗੁਨ ਗਾਵਈ।","roman":"Kahoon lobh kee khumaaree sau anek gun gaavaee |","meaning_en":"","page":108},{"gurmukhi":"ਕਹੂੰ ਬ੍ਰਹਮਚਾਰੀ ਕਹੂੰ ਹਾਥ ਪੈ ਲਗਾਵੇ ਬਾਰੀ","roman":"Kahoon brahamchaaree kahoon haath pai lagaave baaree","meaning_en":"","page":108},{"gurmukhi":"ਕਹੂੰ ਡੰਡਧਾਰੀ ਹੁਇ ਕੈ ਲੋਗਨ ਭ੍ਰਮਾਵਈ।","roman":"Kahoon danddhaaree hui kai logan bhramaavaee |","meaning_en":"","page":108},{"gurmukhi":"ਕਾਮਨਾ ਅਧੀਨ ਪਰਿਓ ਨਾਚਤ ਹੈ ਨਾਚਨ ਸੋ","roman":"Kaamnaa adheen pario naachat hai naachan so","meaning_en":"","page":108},{"gurmukhi":"ਗਿਆਨ ਕੇ ਬਿਹੀਨ ਕੈਸੇ ਬ੍ਰਹਮ ਲੋਕ ਪਾਵਈ। ੧੨। ੮੨।","roman":"Giaan ke biheen kaise braham lok paavaee | 12 | 82 |","meaning_en":"","page":108}]},{"type":"verse","number":[13,83],"number_text":"੧੩। ੮੩।","page":109,"lines":[{"gurmukhi":"ਪੰਚ ਬਾਰ ਗੀਦਰ ਪੁਕਾਰੇ ਪਰੇ ਸੀਤ ਕਾਲ","roman":"Panch baar geedar pukaare pare seet kaal","meaning_en":"","page":109},{"gurmukhi":"ਕੁੰਚਰ ਅਉ ਗਦਹਾ ਅਨੇਕਦਾ ਪ੍ਰਕਾਰ ਹੀ।","roman":"Kunchar au gadhaa anekdaa prakaar hee |","meaning_en":"","page":109},{"gurmukhi":"ਕਹਾ ਭਯੋ ਜੋ ਪੈ ਕਲਵਤ੍ਰ ਲੀਓ ਕਾਸੀ ਬੀਚ","roman":"Kahaa bhayo jo pai kalvatr leeo kaasee beech","meaning_en":"","page":109},{"gurmukhi":"ਚੀਰਿ ਚੀਰਿ ਚੋਰਟਾ ਕੁਠਾਰਨ ਸੋ ਮਾਰਹੀ।","roman":"Cheeri cheeri chortaa kuthaaran so maarhee |","meaning_en":"","page":109},{"gurmukhi":"ਕਹਾ ਭਇਓ ਫਾਸੀ ਡਾਰਿ ਬੂਡਿਓ ਜੜ ਗੰਗਧਾਰਿ","roman":"Kahaa bhaio phaasee daari boodio jar gangdhaari","meaning_en":"","page":109},{"gurmukhi":"ਡਾਰਿ ਡਾਰਿ ਫਾਸਿ ਠਗ ਮਾਰਿ ਮਾਰਿ ਡਾਰਹੀ।","roman":"Daari daari phaasi thag maari maari daarhee |","meaning_en":"","page":109},{"gurmukhi":"ਡੂਬੇ ਨਰਕ ਧਾਰਿ ਮੂੜ ਗਿਆਨ ਕੇ ਬਿਨਾ ਬਿਚਾਰ","roman":"Doobe narak dhaari moor giaan ke binaa bichaar","meaning_en":"","page":109},{"gurmukhi":"ਭਾਵਨਾ ਬਿਹੀਨ ਕੈਸੇ ਗਿਆਨ ਕੋ ਬਿਚਾਰਹੀ। ੧੩। ੮੩।","roman":"Bhaavnaa biheen kaise giaan ko bichaarhee | 13 | 83 |","meaning_en":"","page":109}]},{"type":"verse","number":[14,84],"number_text":"੧੪। ੮੪।","page":109,"lines":[{"gurmukhi":"ਤਾਪ ਕੇ ਸਹੇ ਤੇ ਜੋ ਪੈ ਪਾਈਐ ਅਤਾਪ ਨਾਥ","roman":"Taap ke sahe te jo pai paaeeai ataap naath","meaning_en":"","page":109},{"gurmukhi":"ਤਾਪਨਾ ਅਨੇਕ ਤਨ ਘਾਇਲ ਸਹਤ ਹੈ।","roman":"Taapnaa anek tan ghaail sahat hai |","meaning_en":"","page":109},{"gurmukhi":"ਜਾਪ ਕੇ ਕੀਏ ਤੇ ਜੋ ਪੈ ਪਾਯਤ ਅਜਾਪ ਦੇਵ","roman":"Jaap ke kee'e te jo pai paayat ajaap dev","meaning_en":"","page":109},{"gurmukhi":"ਪੂਦਨਾ ਸਦੀਵ ਤੁਹੀ ਤੁਹੀ ਉਚਰਤ ਹੈ।","roman":"Poodnaa sadeev tuhee tuhee uchrat hai |","meaning_en":"","page":109},{"gurmukhi":"ਨਭ ਕੇ ਉਡੇ ਤੇ ਜੋ ਪੈ ਨਾਰਾਇਣ ਪਾਈਯਤ","roman":"Nabh ke ude te jo pai naaraain paaeeyat","meaning_en":"","page":109},{"gurmukhi":"ਅਨਲ ਅਕਾਸ ਪੰਛੀ ਡੋਲਬੋ ਕਰਤ ਹੈ।","roman":"Anal akaas panchhee dolbo karat hai |","meaning_en":"","page":109},{"gurmukhi":"ਆਗ ਮੈ ਜਰੇ ਤੇ ਗਤਿ ਰਾਂਡ ਕੀ ਪਰਤ ਕਰਿ","roman":"Aag mai jare te gati raand kee parat kari","meaning_en":"","page":109},{"gurmukhi":"ਪਤਾਲ ਕੇ ਬਾਸੀ ਕਿਉ ਭੁਜੰਗ ਨ ਤਰਤ ਹੈ। ੧੪। ੮੪।","roman":"Pataal ke baasee kiu bhujang na tarat hai | 14 | 84 |","meaning_en":"","page":109}]},{"type":"verse","number":[15,85],"number_text":"੧੫। ੮੫।","page":109,"lines":[{"gurmukhi":"ਕੋਊ ਭਇਓ ਮੁੰਡੀਆ ਸੰਨਿਆਸੀ ਕੋਊ ਜੋਗੀ ਭਇਓ","roman":"Ko'oo bhaio mundeeaa sanniaasee ko'oo jogee bhaio","meaning_en":"","page":109},{"gurmukhi":"ਕੋਊ ਬ੍ਰਹਮਚਾਰੀ ਕੋਊ ਜਤੀ ਅਨੁਮਾਨਬੋ।","roman":"Ko'oo brahamchaaree ko'oo jatee anumaanbo |","meaning_en":"","page":109},{"gurmukhi":"ਹਿੰਦੂ ਤੁਰਕ ਕੋਊ ਰਾਫਿਜੀ ਇਮਾਮ ਸਾਫੀ","roman":"Hindoo turak ko'oo raaphijee imaam saaphee","meaning_en":"","page":109},{"gurmukhi":"ਮਾਨਸ ਕੀ ਜਾਤਿ ਸਬੈ ਏਕੈ ਪਹਚਾਨਬੋ।","roman":"Maanas kee jaati sabai ekai pahchaanbo |","meaning_en":"","page":109},{"gurmukhi":"ਕਰਤਾ ਕਰੀਮ ਸੋਈ ਰਾਜਿਕ ਰਹੀਮ ਓਈ","roman":"Kartaa kareem soee raajik raheem oee","meaning_en":"","page":109},{"gurmukhi":"ਦੂਸਰੋ ਨ ਭੇਦ ਕੋਈ ਭੂਲਿ ਭ੍ਰਮ ਮਾਨਬੋ।","roman":"Doosro na bhed koee bhooli bhram maanbo |","meaning_en":"","page":109},{"gurmukhi":"ਏਕ ਹੀ ਕੀ ਸੇਵ ਸਭ ਹੀ ਕੋ ਗੁਰਦੇਵ ਏਕ","roman":"Ek hee kee sev sabh hee ko gurdev ek","meaning_en":"","page":109},{"gurmukhi":"ਏਕ ਹੀ ਸਰੂਪ ਸਬੈ ਏਕੈ ਜੋਤਿ ਜਾਨਬੋ। ੧੫। ੮੫।","roman":"Ek hee saroop sabai ekai joti jaanbo | 15 | 85 |","meaning_en":"","page":109}]},{"type":"verse","number":[16,86],"number_text":"੧੬। ੮੬।","page":109,"lines":[{"gurmukhi":"ਦੇਹੁਰਾ ਮਸੀਤ ਸੋਈ ਪੂਜਾ ਔ ਨਿਵਾਜ ਓਈ","roman":"Dehuraa maseet soee poojaa au nivaaj oee","meaning_en":"","page":109},{"gurmukhi":"ਮਾਨਸ ਸਬੈ ਏਕ ਪੈ ਅਨੇਕ ਕੋ ਭ੍ਰਮਾਉ ਹੈ।","roman":"Maanas sabai ek pai anek ko bhramaau hai |","meaning_en":"","page":109},{"gurmukhi":"ਦੇਵਤਾ ਅਦੇਵ ਜਛ ਗੰਧ੍ਰਬ ਤੁਰਕ ਹਿੰਦੂ","roman":"Devtaa adev jachh gandhrab turak hindoo","meaning_en":"","page":109},{"gurmukhi":"ਨਿਆਰੇ ਨਿਆਰੇ ਦੇਸਨ ਕੇ ਭੇਸ ਕੋ ਪ੍ਰਭਾਉ ਹੈ।","roman":"Niaare niaare desan ke bhes ko prabhaau hai |","meaning_en":"","page":109},{"gurmukhi":"ਏਕੈ ਨੈਨ ਏਕੈ ਕਾਨ ਏਕੈ ਦੇਹ ਏਕੈ ਬਾਨ","roman":"Ekai nain ekai kaan ekai deh ekai baan","meaning_en":"","page":109},{"gurmukhi":"ਖਾਕ ਬਾਦ ਆਤਿਸ ਔ ਆਬ ਕੋ ਰਲਾਉ ਹੈ।","roman":"Khaak baad aatis au aab ko ralaau hai |","meaning_en":"","page":109},{"gurmukhi":"ਅਲਹ ਅਭੇਖ ਸੋਈ ਪੁਰਾਨ ਅਉ ਕੁਰਾਨ ਓਈ","roman":"Alah abhekh soee puraan au kuraan oee","meaning_en":"","page":109},{"gurmukhi":"ਏਕ ਹੀ ਸਰੂਪ ਸਬੈ ਏਕ ਹੀ ਬਨਾਉ ਹੈ। ੧੬। ੮੬।","roman":"Ek hee saroop sabai ek hee banaau hai | 16 | 86 |","meaning_en":"","page":109}]},{"type":"verse","number":[17,87],"number_text":"੧੭। ੮੭।","page":110,"lines":[{"gurmukhi":"ਜੈਸੇ ਏਕ ਆਗ ਤੇ ਕਨੂਕਾ ਕੋਟਿ ਆਗਿ ਉਠੈ","roman":"Jaise ek aag te kanookaa koti aagi uthai","meaning_en":"","page":110},{"gurmukhi":"ਨਿਆਰੇ ਨਿਆਰੇ ਹੁਇ ਕੈ ਫੇਰਿ ਆਗ ਮੈ ਮਿਲਾਹਿਂਗੇ।","roman":"Niaare niaare hui kai pheri aag mai milaahinge |","meaning_en":"","page":110},{"gurmukhi":"ਜੈਸੇ ਏਕ ਧੂਰਿ ਤੇ ਅਨੇਕ ਧੂਰਿ ਪੂਰਤ ਹੈ","roman":"Jaise ek dhoori te anek dhoori poorat hai","meaning_en":"","page":110},{"gurmukhi":"ਧੂਰਿ ਕੇ ਕਨੂਕਾ ਫੇਰ ਧੂਰਿ ਹੀ ਸਮਾਹਿਂਗੇ।","roman":"Dhoori ke kanookaa pher dhoori hee samaahinge |","meaning_en":"","page":110},{"gurmukhi":"ਜੈਸੇ ਏਕ ਨਦ ਤੇ ਤਰੰਗ ਕੋਟਿ ਉਪਜਤ ਹੈ","roman":"Jaise ek nad te tarang koti upjat hai","meaning_en":"","page":110},{"gurmukhi":"ਪਾਨਿ ਕੇ ਤਰੰਗ ਸਬੈ ਪਾਨਿ ਹੀ ਕਹਾਹਿਂਗੇ।","roman":"Paani ke tarang sabai paani hee kahaahinge |","meaning_en":"","page":110},{"gurmukhi":"ਤੈਸੇ ਬਿਸ੍ਵ ਰੂਪ ਤੇ ਅਭੂਤ ਭੂਤ ਪ੍ਰਗਟ ਹੋਇ","roman":"Taise bisv roop te abhoot bhoot pragat hoi","meaning_en":"","page":110},{"gurmukhi":"ਤਾਹੀ ਤੇ ਉਪਜਿ ਸਬੈ ਤਾਹੀ ਮੈ ਸਮਾਹਿਂਗੇ। ੧੭। ੮੭।","roman":"Taahee te upji sabai taahee mai samaahinge | 17 | 87 |","meaning_en":"","page":110}]},{"type":"verse","number":[18,88],"number_text":"੧੮। ੮੮।","page":110,"lines":[{"gurmukhi":"ਕੇਤੇ ਕਛ ਮਛ ਕੇਤੇ ਉਨ ਕਉ ਕਰਤ ਭਛ","roman":"Kete kachh machh kete un kau karat bhachh","meaning_en":"","page":110},{"gurmukhi":"ਕੇਤੇ ਅਛ ਬਛ ਹੁਇ ਸਪਛ ਉਡ ਜਾਹਿਂਗੇ।","roman":"Kete achh bachh hui sapachh ud jaahinge |","meaning_en":"","page":110},{"gurmukhi":"ਕੇਤੇ ਨਭ ਬੀਚ ਅਛ ਪਛ ਕਉ ਕਰੈਂਗੇ ਭਛ","roman":"Kete nabh beech achh pachh kau karainge bhachh","meaning_en":"","page":110},{"gurmukhi":"ਕੇਤਕ ਪ੍ਰਤਛ ਹੁਇ ਪਚਾਇ ਖਾਇ ਜਾਹਿਂਗੇ।","roman":"Ketak pratachh hui pachaai khaai jaahinge |","meaning_en":"","page":110},{"gurmukhi":"ਜਲ ਕਹਾ ਥਲ ਕਹਾ ਗਗਨ ਕੇ ਗਉਨ ਕਹਾ","roman":"Jal kahaa thal kahaa gagan ke gaun kahaa","meaning_en":"","page":110},{"gurmukhi":"ਕਾਲ ਕੇ ਬਨਾਏ ਸਬੈ ਕਾਲ ਹੀ ਚਬਾਹਿਂਗੇ।","roman":"Kaal ke banaae sabai kaal hee chabaahinge |","meaning_en":"","page":110},{"gurmukhi":"ਤੇਜ ਜਿਉ ਅਤੇਜ ਮੈ ਅਤੇਜ ਜੈਸੇ ਤੇਜ ਲੀਨ","roman":"Tej jiu atej mai atej jaise tej leen","meaning_en":"","page":110},{"gurmukhi":"ਤਾਹੀ ਤੇ ਉਪਜਿ ਸਬੈ ਤਾਹੀ ਮੈ ਸਮਾਹਿਂਗੇ। ੧੮। ੮੮।","roman":"Taahee te upji sabai taahee mai samaahinge | 18 | 88 |","meaning_en":"","page":110}]},{"type":"verse","number":[19,89],"number_text":"੧੯। ੮੯।","page":110,"lines":[{"gurmukhi":"ਕੂਕਤ ਫਿਰਤ ਕੇਤੇ ਰੋਵਤ ਮਰਤ ਕੇਤੇ","roman":"Kookat phirat kete rovat marat kete","meaning_en":"","page":110},{"gurmukhi":"ਜਲ ਮੈ ਡੁਬਤ ਕੇਤੇ ਆਗ ਮੈ ਜਰਤ ਹੈ।","roman":"Jal mai dubat kete aag mai jarat hai |","meaning_en":"","page":110},{"gurmukhi":"ਕੇਤੇ ਗੰਗਬਾਸੀ ਕੇਤੇ ਮਦੀਨਾ ਮਕਾ ਨਿਵਾਸੀ","roman":"Kete gangbaasee kete madeenaa makaa nivaasee","meaning_en":"","page":110},{"gurmukhi":"ਕੇਤਕ ਉਦਾਸੀ ਕੇ ਭ੍ਰਮਾਏ ਈ ਫਿਰਤ ਹੈ।","roman":"Ketak udaasee ke bhramaae ee phirat hai |","meaning_en":"","page":110},{"gurmukhi":"ਕਰਵਤ ਸਹਤ ਕੇਤੇ ਭੂਮਿ ਮੈ ਗਡਤ ਕੇਤੇ","roman":"Karvat sahat kete bhoomi mai gadat kete","meaning_en":"","page":110},{"gurmukhi":"ਸੂਆ ਪੈ ਚੜਤ ਕੇਤੇ ਦੁਖ ਕਉ ਭਰਤ ਹੈ।","roman":"Sooaa pai charat kete dukh kau bharat hai |","meaning_en":"","page":110},{"gurmukhi":"ਗੈਨ ਮੈ ਉਡਤ ਕੇਤੇ ਜਲ ਮੈ ਰਹਤ ਕੇਤੇ","roman":"Gain mai udat kete jal mai rahat kete","meaning_en":"","page":110},{"gurmukhi":"ਗਿਆਨ ਕੇ ਬਿਹੀਨ ਜਕਿ ਜਾਰੇ ਈ ਮਰਤ ਹੈ। ੧੯। ੮੯।","roman":"Giaan ke biheen jaki jaare ee marat hai | 19 | 89 |","meaning_en":"","page":110}]},{"type":"verse","number":[20,90],"number_text":"੨੦। ੯੦।","page":110,"lines":[{"gurmukhi":"ਸੋਧਿ ਹਾਰੇ ਦੇਵਤਾ ਬਿਰੋਧ ਹਾਰੇ ਦਾਨੋ ਬਡੇ","roman":"Sodhi haare devtaa birodh haare daano bade","meaning_en":"","page":110},{"gurmukhi":"ਬੋਧਿ ਹਾਰੇ ਬੋਧਕ ਪ੍ਰਬੋਧਿ ਹਾਰੇ ਜਾਪਸੀ।","roman":"Bodhi haare bodhak prabodhi haare jaapsee |","meaning_en":"","page":110},{"gurmukhi":"ਘਸਿ ਹਾਰੇ ਚੰਦਨ ਲਗਾਇ ਹਾਰੇ ਚੋਆ ਚਾਰ","roman":"Ghasi haare chandan lagaai haare choaa chaar","meaning_en":"","page":110},{"gurmukhi":"ਪੂਜ ਹਾਰੇ ਪਾਹਨ ਚਢਾਇ ਹਾਰੇ ਲਾਪਸੀ।","roman":"Pooj haare paahan chadhaai haare laapsee |","meaning_en":"","page":110},{"gurmukhi":"ਗਾਹਿ ਹਾਰੇ ਗੋਰਨ ਮਨਾਇ ਹਾਰੇ ਮੜੀ ਮਟ","roman":"Gaahi haare goran manaai haare maree mat","meaning_en":"","page":110},{"gurmukhi":"ਲੀਪ ਹਾਰੇ ਭੀਤਨ ਲਗਾਇ ਹਾਰੇ ਛਾਪਸੀ।","roman":"Leep haare bheetan lagaai haare chhaapsee |","meaning_en":"","page":110},{"gurmukhi":"ਗਾਇ ਹਾਰੇ ਗੰਧ੍ਰਬ ਬਜਾਏ ਹਾਰੇ ਕਿੰਨਰ ਸਭ","roman":"Gaai haare gandhrab bajaae haare kinnar sabh","meaning_en":"","page":110},{"gurmukhi":"ਪਚਿ ਹਾਰੇ ਪੰਡਿਤ ਤਪੰਤਿ ਹਾਰੇ ਤਾਪਸੀ। ੨੦। ੯੦।","roman":"Pachi haare pandit tapanti haare taapsee | 20 | 90 |","meaning_en":"","page":110}]},{"type":"heading","kind":"chhand","name":"ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","gurmukhi":"ਤ੍ਵਪ੍ਰਸਾਦਿ। ਭੁਜੰਗ ਪ੍ਰਯਾਤ ਛੰਦ","roman":"Tvaprasaadi | bhujang prayaat chhand","meaning_en":"","page":110,"flags":[{"code":"space","reason":"word space printed as a gap (7.2pt), space inserted"}],"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[1,91],"number_text":"੧। ੯੧।","page":110,"lines":[{"gurmukhi":"ਨ ਰਾਗੰ ਨ ਰੰਗੰ ਨ ਰੂਪੰ ਨ ਰੇਖੰ। ਨ ਮੋਹੰ ਨ ਕ੍ਰੋਹੰ ਨ ਦ੍ਰੋਹੰ ਨ ਦ੍ਵੈਖੰ।","roman":"Na raagan na rangan na roopan na rekhan | na mohan na krohan na drohan na dvaikhan |","meaning_en":"","page":110},{"gurmukhi":"ਨ ਕਰਮੰ ਨ ਭਰਮੰ ਨ ਜਨਮੰ ਨ ਜਾਤੰ। ਨ ਮਿਤ੍ਰੰ ਨ ਸਤ੍ਰੰ ਨ ਪਿਤ੍ਰ ਨ ਮਾਤੰ। ੧। ੯੧।","roman":"Na karman na bharman na janman na jaatan | na mitran na satran na pitr na maatan | 1 | 91 |","meaning_en":"","page":110,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}]}]},{"type":"verse","number":[2,92],"number_text":"੨। ੯੨।","page":111,"lines":[{"gurmukhi":"ਨ ਨੇਹੰ ਨ ਗੇਹੰ ਨ ਕਾਮੰ ਨ ਧਾਮੰ। ਨ ਪੁਤ੍ਰੰ ਨ ਮਿਤ੍ਰੰ ਨ ਸਤ੍ਰੰ ਨ ਭਾਮੰ।","roman":"Na nehan na gehan na kaaman na dhaaman | na putran na mitran na satran na bhaaman |","meaning_en":"","page":111,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}]},{"gurmukhi":"ਅਲੇਖੰ ਅਭੇਖੰ ਅਜੋਨੀ ਸਰੂਪੰ। ਸਦਾ ਸਿਧਿਦਾ ਬੁਧਿਦਾ ਬ੍ਰਿਧਿ ਰੂਪੰ। ੨। ੯੨।","roman":"Alekhan abhekhan ajonee saroopan | sadaa sidhidaa budhidaa bridhi roopan | 2 | 92 |","meaning_en":"","page":111}]},{"type":"verse","number":[3,93],"number_text":"੩। ੯੩।","page":111,"lines":[{"gurmukhi":"ਨਹੀ ਜਾਨ ਜਾਈ ਕਛੂ ਰੂਪ ਰੇਖੰ। ਕਹਾ ਬਾਸ ਤਾਕੋ ਫਿਰੈ ਕਉਨ ਭੇਖੰ।","roman":"Nahee jaan jaaee kachhoo roop rekhan | kahaa baas taako phirai kaun bhekhan |","meaning_en":"","page":111},{"gurmukhi":"ਕਹਾ ਨਾਮ ਤਾ ਕੋ ਕਹਾ ਕੈ ਕਹਾਵੈ। ਕਹਾ ਕੈ ਬਖਾਨੋ ਕਹੈ ਮੋ ਨ ਆਵੈ। ੩। ੯੩।","roman":"Kahaa naam taa ko kahaa kai kahaavai | kahaa kai bakhaano kahai mo na aavai | 3 | 93 |","meaning_en":"","page":111}]},{"type":"verse","number":[4,94],"number_text":"੪। ੯੪।","page":111,"lines":[{"gurmukhi":"ਨ ਰੋਗੰ ਨ ਸੋਗੰ ਨ ਮੋਹੰ ਨ ਮਾਤੰ। ਨ ਕਰਮੰ ਨ ਭਰਮੰ ਨ ਜਨਮੰ ਨ ਜਾਤੰ।","roman":"Na rogan na sogan na mohan na maatan | na karman na bharman na janman na jaatan |","meaning_en":"","page":111},{"gurmukhi":"ਅਦ੍ਵੈਖੰ ਅਭੇਖੰ ਅਜੋਨੀ ਸਰੂਪੇ। ਨਮੋ ਏਕ ਰੂਪੇ ਨਮੋ ਏਕ ਰੂਪੇ। ੪। ੯੪।","roman":"Advaikhan abhekhan ajonee saroope | namo ek roope namo ek roope | 4 | 94 |","meaning_en":"","page":111}]},{"type":"verse","number":[5,95],"number_text":"੫। ੯੫।","page":111,"lines":[{"gurmukhi":"ਪਰੇਅੰ ਪਰਾ ਪਰਮ ਪ੍ਰਗਿਆ ਪ੍ਰਕਾਸੀ। ਅਛੇਦੰ ਅਛੈ ਆਦਿ ਅਦ੍ਵੈ ਅਬਿਨਾਸੀ।","roman":"Parean paraa param pragiaa prakaasee | achhedan achhai aadi advai abinaasee |","meaning_en":"","page":111},{"gurmukhi":"ਨ ਜਾਤੰ ਨ ਪਾਤੰ ਨ ਰੂਪੰ ਨ ਰੰਗੇ। ਨਮੋ ਆਦਿ ਅਭੰਗੇ ਨਮੋ ਆਦਿ ਅਭੰਗੇ। ੫। ੯੫।","roman":"Na jaatan na paatan na roopan na range | namo aadi abhange namo aadi abhange | 5 | 95 |","meaning_en":"","page":111}]},{"type":"verse","number":[6,96],"number_text":"੬। ੯੬।","page":111,"lines":[{"gurmukhi":"ਕਿਤੇ ਕ੍ਰਿਸਨ ਸੇ ਕੀਟ ਕੋਟੈ ਉਪਾਏ। ਉਸਾਰੇ ਗੜੇ ਫੇਰਿ ਮੇਟੇ ਬਨਾਏ।","roman":"Kite krisan se keet kotai upaae | usaare gare pheri mete banaae |","meaning_en":"","page":111},{"gurmukhi":"ਅਗਾਧੇ ਅਭੈ ਆਦਿ ਅਦ੍ਵੈ ਅਬਿਨਾਸੀ। ਪਰੇਅੰ ਪਰਾ ਪਰਮ ਪੂਰਨ ਪ੍ਰਕਾਸੀ। ੬। ੯੬।","roman":"Agaadhe abhai aadi advai abinaasee | parean paraa param pooran prakaasee | 6 | 96 |","meaning_en":"","page":111}]},{"type":"verse","number":[7,97],"number_text":"੭। ੯੭।","page":111,"lines":[{"gurmukhi":"ਨ ਆਧੰ ਨ ਬਿਆਧੰ ਅਗਾਧੰ ਸਰੂਪੇ। ਅਖੰਡਿਤ ਪ੍ਰਤਾਪ ਆਦਿ ਅਛੇ ਬਿਭੂਤੇ।","roman":"Na aadhan na biaadhan agaadhan saroope | akhandit prataap aadi achhe bibhoote |","meaning_en":"","page":111},{"gurmukhi":"ਨ ਜਨਮੰ ਨ ਮਰਨੰ ਨ ਬਰਨੰ ਨ ਬਿਆਧੇ। ਅਖੰਡੇ ਪ੍ਰਚੰਡੇ ਅਦੰਡੇ ਅਸਾਧੇ। ੭। ੯੭।","roman":"Na janman na marnan na barnan na biaadhe | akhande prachande adande asaadhe | 7 | 97 |","meaning_en":"","page":111}]},{"type":"verse","number":[8,98],"number_text":"੮। ੯੮।","page":111,"lines":[{"gurmukhi":"ਨ ਨੇਹੰ ਨ ਗੇਹੰ ਸਨੇਹੰ ਨ ਸਾਥੇ। ਉਦੰਡੇ ਅਮੰਡੇ ਪ੍ਰਚੰਡੇ ਪ੍ਰਮਾਥੇ।","roman":"Na nehan na gehan sanehan na saathe | udande amande prachande pramaathe |","meaning_en":"","page":111},{"gurmukhi":"ਨ ਜਾਤੇ ਨ ਪਾਤੇ ਨ ਸਤ੍ਰੇ ਨ ਮਿਤ੍ਰੇ। ਸੁ ਭੂਤੇ ਭਵਿਖੇ ਭਵਾਨੇ ਅਚਿਤ੍ਰੇ। ੮। ੯੮।","roman":"Na jaate na paate na satre na mitre | su bhoote bhavikhe bhavaane achitre | 8 | 98 |","meaning_en":"","page":111}]},{"type":"verse","number":[9,99],"number_text":"੯। ੯੯।","page":111,"lines":[{"gurmukhi":"ਨ ਰਾਯੰ ਨ ਰੰਕੰ ਨ ਰੂਪੰ ਨ ਰੇਖੰ। ਨ ਲੋਭੰ ਨ ਅਛੋਭੰ ਅਭੂਤੰ ਅਭੇਖੰ।","roman":"Na raayan na rankan na roopan na rekhan | na lobhan na achhobhan abhootan abhekhan |","meaning_en":"","page":111},{"gurmukhi":"ਨ ਸਤ੍ਰੰ ਨ ਮਿਤ੍ਰੰ ਨ ਨੇਹੰ ਨ ਗੇਹੰ। ਸਦੈਵੰ ਸਦਾ ਸਰਬ ਸਰਬਤ੍ਰ ਸਨੇਹੰ। ੯। ੯੯।","roman":"Na satran na mitran na nehan na gehan | sadaivan sadaa sarab sarbatr sanehan | 9 | 99 |","meaning_en":"","page":111,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}]}]},{"type":"verse","number":[10,100],"number_text":"੧੦।੧੦੦।","page":111,"lines":[{"gurmukhi":"ਨ ਕਾਮੰ ਨ ਕ੍ਰੋਧੰ ਨ ਲੋਭੰ ਨ ਮੋਹੰ। ਅਜੋਨੀ ਅਛੈ ਆਦਿ ਅਦ੍ਵੈ ਅਜੋਹੰ।","roman":"Na kaaman na krodhan na lobhan na mohan | ajonee achhai aadi advai ajohan |","meaning_en":"","page":111,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}]},{"gurmukhi":"ਨ ਜਨਮੰ ਨ ਮਰਨੰ ਨ ਬਰਨੰ ਨ ਬਿਆਧੰ। ਨ ਰੋਗੰ ਨ ਸੋਗੰ ਅਭੈ ਨਿਰਬਿਖਾਧੰ। ੧੦।੧੦੦।","roman":"Na janman na marnan na barnan na biaadhan | na rogan na sogan abhai nirbikhaadhan | 10 | 100 |","meaning_en":"","page":111}]},{"type":"verse","number":[11,101],"number_text":"੧੧। ੧੦੧।","page":112,"lines":[{"gurmukhi":"ਅਛੇਦੰ ਅਭੇਦੰ ਅਕਰਮੰ ਅਕਾਲੰ।","roman":"Achhedan abhedan akarman akaalan |","meaning_en":"","page":112},{"gurmukhi":"ਅਖੰਡੰ ਅਭੰਡੰ ਪ੍ਰਚੰਡੰ ਅਪਾਲੰ।","roman":"Akhandan abhandan prachandan apaalan |","meaning_en":"","page":112},{"gurmukhi":"ਨ ਤਾਤੰ ਨ ਮਾਤੰ ਨ ਜਾਤੰ ਨ ਕਾਯੰ।","roman":"Na taatan na maatan na jaatan na kaayan |","meaning_en":"","page":112},{"gurmukhi":"ਨ ਨੇਹੰ ਨ ਗੇਹੰ ਨ ਭਰਮੰ ਨ ਭਾਯੰ। ੧੧। ੧੦੧।","roman":"Na nehan na gehan na bharman na bhaayan | 11 | 101 |","meaning_en":"","page":112}]},{"type":"verse","number":[12,102],"number_text":"੧੨। ੧੦੨।","page":112,"lines":[{"gurmukhi":"ਨ ਰੂਪੰ ਨ ਭੂਪੰ ਨ ਕਾਯੰ ਨ ਕਰਮੰ।","roman":"Na roopan na bhoopan na kaayan na karman |","meaning_en":"","page":112},{"gurmukhi":"ਨ ਤ੍ਰਾਸੰ ਨ ਪ੍ਰਾਸੰ ਨ ਭੇਦੰ ਨ ਭਰਮੰ।","roman":"Na traasan na praasan na bhedan na bharman |","meaning_en":"","page":112},{"gurmukhi":"ਸਦੈਵੰ ਸਦਾ ਸਿਧਿ ਬ੍ਰਿਧੰ ਸਰੂਪੇ।","roman":"Sadaivan sadaa sidhi bridhan saroope |","meaning_en":"","page":112},{"gurmukhi":"ਨਮੋ ਏਕ ਰੂਪੇ ਨਮੋ ਏਕ ਰੂਪੇ। ੧੨। ੧੦੨।","roman":"Namo ek roope namo ek roope | 12 | 102 |","meaning_en":"","page":112}]},{"type":"verse","number":[13,103],"number_text":"੧੩। ੧੦੩।","page":112,"lines":[{"gurmukhi":"ਨ੍ਰਿਉਕਤੰ ਪ੍ਰਭਾ ਆਦਿ ਅਨੁਕਤੰ ਪ੍ਰਤਾਪੇ।","roman":"Nriuktan prabhaa aadi anuktan prataape |","meaning_en":"","page":112},{"gurmukhi":"ਅਜੁਗਤੰ ਅਛੈ ਆਦਿ ਅਵਿਕਤੰ ਅਥਾਪੇ।","roman":"Ajugtan achhai aadi aviktan athaape |","meaning_en":"","page":112},{"gurmukhi":"ਬਿਭੁਗਤੰ ਅਛੈ ਆਦਿ ਅਛੈ ਸਰੂਪੇ।","roman":"Bibhugtan achhai aadi achhai saroope |","meaning_en":"","page":112},{"gurmukhi":"ਨਮੋ ਏਕ ਰੂਪੇ ਨਮੋ ਏਕ ਰੂਪੇ। ੧੩। ੧੦੩।","roman":"Namo ek roope namo ek roope | 13 | 103 |","meaning_en":"","page":112}]},{"type":"verse","number":[14,104],"number_text":"੧੪। ੧੦੪।","page":112,"lines":[{"gurmukhi":"ਨ ਨੇਹੰ ਨ ਗੇਹੰ ਨ ਸੋਕੰ ਨ ਸਾਕੰ।","roman":"Na nehan na gehan na sokan na saakan |","meaning_en":"","page":112},{"gurmukhi":"ਪਰੇਅੰ ਪਵਿਤ੍ਰੰ ਪੁਨੀਤੰ ਅਤਾਕੰ।","roman":"Parean pavitran puneetan ataakan |","meaning_en":"","page":112},{"gurmukhi":"ਨ ਜਾਤੰ ਨ ਪਾਤੰ ਨ ਮਿਤ੍ਰੰ ਨ ਮੰਤ੍ਰੇ।","roman":"Na jaatan na paatan na mitran na mantre |","meaning_en":"","page":112},{"gurmukhi":"ਨਮੋ ਏਕ ਤੰਤ੍ਰੇ ਨਮੋ ਏਕ ਤੰਤ੍ਰੇ। ੧੪। ੧੦੪।","roman":"Namo ek tantre namo ek tantre | 14 | 104 |","meaning_en":"","page":112}]},{"type":"verse","number":[15,105],"number_text":"੧੫। ੧੦੫।","page":112,"lines":[{"gurmukhi":"ਨ ਧਰਮੰ ਨ ਭਰਮੰ ਨ ਸਰਮੰ ਨ ਸਾਕੇ।","roman":"Na dharman na bharman na sarman na saake |","meaning_en":"","page":112},{"gurmukhi":"ਨ ਬਰਮੰ ਨ ਚਰਮੰ ਨ ਕਰਮੰ ਨ ਬਾਕੇ।","roman":"Na barman na charman na karman na baake |","meaning_en":"","page":112},{"gurmukhi":"ਨ ਸਤ੍ਰੰ ਨ ਮਿਤ੍ਰੰ ਨ ਪੁਤ੍ਰੰ ਸਰੂਪੇ।","roman":"Na satran na mitran na putran saroope |","meaning_en":"","page":112},{"gurmukhi":"ਨਮੋ ਆਦਿ ਰੂਪੇ ਨਮੋ ਆਦਿ ਰੂਪੇ। ੧੫। ੧੦੫।","roman":"Namo aadi roope namo aadi roope | 15 | 105 |","meaning_en":"","page":112}]},{"type":"verse","number":[16,106],"number_text":"੧੬। ੧੦੬।","page":112,"lines":[{"gurmukhi":"ਕਹੂੰ ਕੰਜ ਕੇ ਮੰਜ ਕੇ ਭਰਮਿ ਭੂਲੇ।","roman":"Kahoon kanj ke manj ke bharmi bhoole |","meaning_en":"","page":112},{"gurmukhi":"ਕਹੂੰ ਰੰਕ ਕੇ ਰਾਜ ਕੇ ਧਰਮ ਅਲੂਲੇ।","roman":"Kahoon rank ke raaj ke dharam aloole |","meaning_en":"","page":112},{"gurmukhi":"ਕਹੂੰ ਦੇਸ ਕੇ ਭੇਸ ਕੇ ਧਰਮ ਧਾਮੇ।","roman":"Kahoon des ke bhes ke dharam dhaame |","meaning_en":"","page":112},{"gurmukhi":"ਕਹੂੰ ਰਾਜ ਕੇ ਸਾਜ ਕੇ ਬਾਜ ਤਾਮੇ। ੧੬। ੧੦੬।","roman":"Kahoon raaj ke saaj ke baaj taame | 16 | 106 |","meaning_en":"","page":112}]},{"type":"verse","number":[17,107],"number_text":"੧੭। ੧੦੭।","page":112,"lines":[{"gurmukhi":"ਕਹੂੰ ਅਛ੍ਰ ਕੇ ਪਛ੍ਰ ਕੇ ਸਿਧ ਸਾਧੇ।","roman":"Kahoon achhr ke pachhr ke sidh saadhe |","meaning_en":"","page":112},{"gurmukhi":"ਕਹੂੰ ਸਿਧ ਕੇ ਬੁਧਿ ਕੇ ਬ੍ਰਿਧ ਲਾਧੇ।","roman":"Kahoon sidh ke budhi ke bridh laadhe |","meaning_en":"","page":112},{"gurmukhi":"ਕਹੂੰ ਅੰਗ ਕੇ ਰੰਗ ਕੇ ਸੰਗਿ ਦੇਖੇ।","roman":"Kahoon ang ke rang ke sangi dekhe |","meaning_en":"","page":112},{"gurmukhi":"ਕਹੂੰ ਜੰਗ ਕੇ ਰੰਗ ਕੇ ਰੰਗ ਪੇਖੇ। ੧੭। ੧੦੭।","roman":"Kahoon jang ke rang ke rang pekhe | 17 | 107 |","meaning_en":"","page":112}]},{"type":"verse","number":[18,108],"number_text":"੧੮। ੧੦੮।","page":112,"lines":[{"gurmukhi":"ਕਹੂੰ ਧਰਮ ਕੇ ਕਰਮ ਕੇ ਹਰਮ ਜਾਨੇ।","roman":"Kahoon dharam ke karam ke haram jaane |","meaning_en":"","page":112},{"gurmukhi":"ਕਹੂੰ ਧਰਮ ਕੇ ਕਰਮ ਕੇ ਭਰਮ ਮਾਨੇ।","roman":"Kahoon dharam ke karam ke bharam maane |","meaning_en":"","page":112},{"gurmukhi":"ਕਹੂੰ ਚਾਰੁ ਚੇਸਟਾ ਕਹੂੰ ਚਿਤ੍ਰ ਰੂਪੰ।","roman":"Kahoon chaaru chestaa kahoon chitr roopan |","meaning_en":"","page":112},{"gurmukhi":"ਕਹੂੰ ਪਰਮ ਪ੍ਰਗ੍ਯਾ ਕਹੂੰ ਸਰਬ ਭੂਪੰ। ੧੮। ੧੦੮।","roman":"Kahoon param pragyaa kahoon sarab bhoopan | 18 | 108 |","meaning_en":"","page":112}]},{"type":"verse","number":[19,109],"number_text":"੧੯। ੧੦੯।","page":113,"lines":[{"gurmukhi":"ਕਹੂੰ ਨੇਹ ਗ੍ਰੇਹੰ ਕਹੂੰ ਦੇਹ ਦੋਖੰ। ਕਹੂੰ ਅਉਖਦੀ ਰੋਗ ਕੇ ਸੋਕ ਸੋਖੰ।","roman":"Kahoon neh grehan kahoon deh dokhan | kahoon aukhdee rog ke sok sokhan |","meaning_en":"","page":113},{"gurmukhi":"ਕਹੂੰ ਦੇਵ ਬਿਦ੍ਯਾ ਕਹੂੰ ਦੈਤ ਬਾਨੀ। ਕਹੂੰ ਜਛ ਗੰਧ੍ਰਬ ਕਿੰਨਰ ਕਹਾਨੀ। ੧੯। ੧੦੯।","roman":"Kahoon dev bidyaa kahoon dait baanee | kahoon jachh gandhrab kinnar kahaanee | 19 | 109 |","meaning_en":"","page":113}]},{"type":"verse","number":[20,110],"number_text":"੨੦। ੧੧੦।","page":113,"lines":[{"gurmukhi":"ਕਹੂੰ ਰਾਜਸੀ ਸਾਤਕੀ ਤਾਮਸੀ ਹੋ। ਕਹੂੰ ਜੋਗ ਬਿਦ੍ਯਾ ਧਰੇ ਤਾਪਸੀ ਹੋ।","roman":"Kahoon raajsee saatkee taamsee ho | kahoon jog bidyaa dhare taapsee ho |","meaning_en":"","page":113},{"gurmukhi":"ਕਹੂੰ ਰੋਗ ਹਰਤਾ ਕਹੂੰ ਜੋਗ ਜੁਗਤੰ। ਕਹੂੰ ਭੂਮਿ ਕੀ ਭੁਗਤ ਮੈ ਭਰਮ ਭੁਗਤੰ। ੨੦। ੧੧੦।","roman":"Kahoon rog hartaa kahoon jog jugtan | kahoon bhoomi kee bhugat mai bharam bhugtan | 20 | 110 |","meaning_en":"","page":113}]},{"type":"verse","number":[21,111],"number_text":"੨੧। ੧੧੧।","page":113,"lines":[{"gurmukhi":"ਕਹੂੰ ਦੇਵ ਕੰਨਿਆ ਕਹੂੰ ਦਾਨਵੀ ਹੋ। ਕਹੂੰ ਜਛ ਬਿਦਿਆ ਧਰੇ ਮਾਨਵੀ ਹੋ।","roman":"Kahoon dev kanniaa kahoon daanvee ho | kahoon jachh bidiaa dhare maanvee ho |","meaning_en":"","page":113},{"gurmukhi":"ਕਹੂੰ ਰਾਜਸੀ ਹੋ ਕਹੂੰ ਰਾਜ ਕੰਨਿਆ। ਕਹੂੰ ਸ੍ਰਿਸਿਟ ਕੀ ਪ੍ਰਿਸਟ ਕੀ ਰਿਸਟ ਪੰਨਿਆ। ੨੧। ੧੧੧।","roman":"Kahoon raajsee ho kahoon raaj kanniaa | kahoon srisit kee prisat kee risat panniaa | 21 | 111 |","meaning_en":"","page":113}]},{"type":"verse","number":[22,112],"number_text":"੨੨। ੧੧੨।","page":113,"lines":[{"gurmukhi":"ਕਹੂੰ ਬੇਦ ਬਿਦ੍ਯਾ ਕਹੂੰ ਬਿਓਮ ਬਾਨੀ। ਕਹੂੰ ਕੋਕ ਕੀ ਕਾਬਿ ਕਥੈ ਕਹਾਨੀ।","roman":"Kahoon bed bidyaa kahoon biom baanee | kahoon kok kee kaabi kathai kahaanee |","meaning_en":"","page":113},{"gurmukhi":"ਕਹੂੰ ਅਦ੍ਰ ਸਾਰੰ ਕਹੂੰ ਭਦ੍ਰ ਰੂਪੰ। ਕਹੂੰ ਮਦ੍ਰ ਬਾਨੀ ਕਹੂੰ ਛੁਦ੍ਰ ਸਰੂਪੰ। ੨੨। ੧੧੨।","roman":"Kahoon adr saaran kahoon bhadr roopan | kahoon madr baanee kahoon chhudr saroopan | 22 | 112 |","meaning_en":"","page":113}]},{"type":"verse","number":[23,113],"number_text":"੨੩। ੧੧੩।","page":113,"lines":[{"gurmukhi":"ਕਹੂੰ ਬੇਦ ਬਿਦਿਆ ਕਹੂੰ ਕਾਬਿ ਰੂਪੰ। ਕਹੂੰ ਚੇਸਟਾ ਚਾਰ ਚਿਤ੍ਰੰ ਸਰੂਪੰ।","roman":"Kahoon bed bidiaa kahoon kaabi roopan | kahoon chestaa chaar chitran saroopan |","meaning_en":"","page":113},{"gurmukhi":"ਕਹੂੰ ਪਰਮ ਪੁਰਾਨ ਕੋ ਪਾਰ ਪਾਵੈ। ਕਹੂੰ ਬੈਠਿ ਕੁਰਾਨ ਕੇ ਗੀਤ ਗਾਵੈ। ੨੩। ੧੧੩।","roman":"Kahoon param puraan ko paar paavai | kahoon baithi kuraan ke geet gaavai | 23 | 113 |","meaning_en":"","page":113}]},{"type":"verse","number":[24,114],"number_text":"੨੪। ੧੧੪।","page":113,"lines":[{"gurmukhi":"ਕਹੂੰ ਸੁਧ ਸੇਖੰ ਕਹੂੰ ਬ੍ਰਹਮ ਧਰਮੰ। ਕਹੂੰ ਬ੍ਰਿਧ ਅਵਸਥਾ ਕਹੂੰ ਬਾਲ ਕਰਮੰ।","roman":"Kahoon sudh sekhan kahoon braham dharman | kahoon bridh avasthaa kahoon baal karman |","meaning_en":"","page":113},{"gurmukhi":"ਕਹੂੰ ਜੁਆ ਸਰੂਪੰ ਜਰਾ ਰਹਤ ਦੇਹੰ। ਕਹੂੰ ਨੇਹ ਦੇਹੰ ਕਹੂੰ ਤਿਆਗ ਗ੍ਰੇਹੰ। ੨੪। ੧੧੪।","roman":"Kahoon juaa saroopan jaraa rahat dehan | kahoon neh dehan kahoon tiaag grehan | 24 | 114 |","meaning_en":"","page":113}]},{"type":"verse","number":[25,115],"number_text":"੨੫। ੧੧੫।","page":113,"lines":[{"gurmukhi":"ਕਹੂੰ ਜੋਗ ਭੋਗੰ ਕਹੂੰ ਰੋਗ ਰਾਗੰ। ਕਹੂੰ ਰੋਗ ਹਰਤਾ ਕਹੂੰ ਭੋਗ ਤਿਆਗੰ।","roman":"Kahoon jog bhogan kahoon rog raagan | kahoon rog hartaa kahoon bhog tiaagan |","meaning_en":"","page":113},{"gurmukhi":"ਕਹੂੰ ਰਾਜ ਸਾਜੰ ਕਹੂੰ ਰਾਜ ਰੀਤੰ। ਕਹੂੰ ਪੂਰਣ ਪ੍ਰਗਿਆ ਕਹੂੰ ਪਰਮ ਪ੍ਰੀਤੰ। ੨੫। ੧੧੫।","roman":"Kahoon raaj saajan kahoon raaj reetan | kahoon pooran pragiaa kahoon param preetan | 25 | 115 |","meaning_en":"","page":113}]},{"type":"verse","number":[26,116],"number_text":"੨੬। ੧੧੬।","page":113,"lines":[{"gurmukhi":"ਕਹੂੰ ਆਰਬੀ ਤੋਰਕੀ ਪਾਰਸੀ ਹੋ। ਕਹੂੰ ਪਹਲਵੀ ਪਸਤਵੀ ਸੰਸਕ੍ਰਿਤੀ ਹੋ।","roman":"Kahoon aarbee torkee paarsee ho | kahoon pahalvee pasatvee sanskritee ho |","meaning_en":"","page":113},{"gurmukhi":"ਕਹੂੰ ਦੇਸ ਭਾਖਿਆ ਕਹੂੰ ਦੇਵ ਬਾਨੀ। ਕਹੂੰ ਰਾਜ ਬਿਦਿਆ ਕਹੂੰ ਰਾਜਧਾਨੀ। ੨੬। ੧੧੬।","roman":"Kahoon des bhaakhiaa kahoon dev baanee | kahoon raaj bidiaa kahoon raajdhaanee | 26 | 116 |","meaning_en":"","page":113}]},{"type":"verse","number":[27,117],"number_text":"੨੭। ੧੧੭।","page":113,"lines":[{"gurmukhi":"ਕਹੂੰ ਮੰਤ੍ਰ ਬਿਦਿਆ ਕਹੂੰ ਤੰਤ੍ਰ ਸਾਰੰ। ਕਹੂੰ ਜੰਤ੍ਰ ਰੀਤੰ ਕਹੂੰ ਸਸਤ੍ਰ ਧਾਰੰ।","roman":"Kahoon mantr bidiaa kahoon tantr saaran | kahoon jantr reetan kahoon sasatr dhaaran |","meaning_en":"","page":113},{"gurmukhi":"ਕਹੂੰ ਹੋਮ ਪੂਜਾ ਕਹੂੰ ਦੇਵ ਅਰਚਾ। ਕਹੂੰ ਪਿੰਗੁਲਾ ਚਾਰਣੀ ਗੀਤ ਚਰਚਾ। ੨੭। ੧੧੭।","roman":"Kahoon hom poojaa kahoon dev archaa | kahoon pingulaa chaarnee geet charchaa | 27 | 117 |","meaning_en":"","page":113}]},{"type":"verse","number":[28,118],"number_text":"੨੮। ੧੧੮।","page":113,"lines":[{"gurmukhi":"ਕਹੂੰ ਬੀਨ ਬਿਦਿਆ ਕਹੂੰ ਗਾਨ ਗੀਤੰ। ਕਹੂੰ ਮਲੇਛ ਭਾਖਿਆ ਕਹੂੰ ਬੇਦ ਰੀਤੰ।","roman":"Kahoon been bidiaa kahoon gaan geetan | kahoon malechh bhaakhiaa kahoon bed reetan |","meaning_en":"","page":113},{"gurmukhi":"ਕਹੂੰ ਨ੍ਰਿਤ ਬਿਦਿਆ ਕਹੂੰ ਨਾਗ ਬਾਨੀ। ਕਹੂੰ ਗਾਰੜੂ ਗੂੜ ਕਥੇ ਕਹਾਨੀ। ੨੮। ੧੧੮।","roman":"Kahoon nrit bidiaa kahoon naag baanee | kahoon gaarroo goor kathe kahaanee | 28 | 118 |","meaning_en":"","page":113}]},{"type":"verse","number":[29,119],"number_text":"੨੯। ੧੧੯।","page":114,"lines":[{"gurmukhi":"ਕਹੂੰ ਅਛਰਾ ਪਛਰਾ ਮਛਰਾ ਹੋ।","roman":"Kahoon achhraa pachhraa machhraa ho |","meaning_en":"","page":114},{"gurmukhi":"ਕਹੂੰ ਬੀਰ ਬਿਦਿਆ ਅਭੂਤੰ ਪ੍ਰਭਾ ਹੋ।","roman":"Kahoon beer bidiaa abhootan prabhaa ho |","meaning_en":"","page":114},{"gurmukhi":"ਕਹੂੰ ਛੈਲ ਛਾਲਾ ਧਰੇ ਛਤ੍ਰਧਾਰੀ।","roman":"Kahoon chhail chhaalaa dhare chhatradhaaree |","meaning_en":"","page":114},{"gurmukhi":"ਕਹੂੰ ਰਾਜ ਸਾਜੰ ਧਿਰਾਜਾਧਿਕਾਰੀ। ੨੯। ੧੧੯।","roman":"Kahoon raaj saajan dhiraajaadhikaaree | 29 | 119 |","meaning_en":"","page":114}]},{"type":"verse","number":[30,120],"number_text":"੩੦। ੧੨੦।","page":114,"lines":[{"gurmukhi":"ਨਮੋ ਨਾਥ ਪੂਰੇ ਸਦਾ ਸਿਧ ਦਾਤਾ।","roman":"Namo naath poore sadaa sidh daataa |","meaning_en":"","page":114},{"gurmukhi":"ਅਛੇਦੀ ਅਛੈ ਆਦਿ ਅਦ੍ਵੈ ਬਿਧਾਤਾ।","roman":"Achhedee achhai aadi advai bidhaataa |","meaning_en":"","page":114},{"gurmukhi":"ਨ ਤ੍ਰਸਤੰ ਨ ਗ੍ਰਸਤੰ ਸਮਸਤੰ ਸਰੂਪੇ।","roman":"Na trastan na grastan samastan saroope |","meaning_en":"","page":114},{"gurmukhi":"ਨਮਸਤੰ ਨਮਸਤੰ ਤੁਅਸਤੰ ਅਭੂਤੇ। ੩੦। ੧੨੦।","roman":"Namastan namastan tuastan abhoote | 30 | 120 |","meaning_en":"","page":114}]},{"type":"heading","kind":"chhand","name":"ਪਾਧੜੀ ਛੰਦ","gurmukhi":"ਤ੍ਵਪ੍ਰਸਾਦਿ। ਪਾਧੜੀ ਛੰਦ","roman":"Tvaprasaadi | paadhree chhand","meaning_en":"","page":114,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[1,121],"number_text":"੧। ੧੨੧।","page":114,"lines":[{"gurmukhi":"ਅਬ੍ਯਕਤ ਤੇਜ ਅਨਭਉ ਪ੍ਰਕਾਸ। ਅਛੈ ਸਰੂਪ ਅਦ੍ਵੈ ਅਨਾਸ।","roman":"Abyakat tej anbhau prakaas | achhai saroop advai anaas |","meaning_en":"","page":114},{"gurmukhi":"ਅਨਤੁਟ ਤੇਜ ਅਨਖੁਟ ਭੰਡਾਰ। ਦਾਤਾ ਦੁਰੰਤ ਸਰਬੰ ਪ੍ਰਕਾਰ। ੧। ੧੨੧।","roman":"Antut tej ankhut bhandaar | daataa durant sarban prakaar | 1 | 121 |","meaning_en":"","page":114}]},{"type":"verse","number":[2,122],"number_text":"੨। ੧੨੨।","page":114,"lines":[{"gurmukhi":"ਅਨਭੂਤ ਤੇਜ ਅਨਛਿਜ ਗਾਤ। ਕਰਤਾ ਸਦੀਵ ਹਰਤਾ ਸਨਾਤ।","roman":"Anbhoot tej anchhij gaat | kartaa sadeev hartaa sanaat |","meaning_en":"","page":114},{"gurmukhi":"ਆਸਨ ਅਡੋਲ ਅਨਭੂਤ ਕਰਮ। ਦਾਤਾ ਦਇਆਲ ਅਨਭੂਤ ਧਰਮ। ੨। ੧੨੨।","roman":"Aasan adol anbhoot karam | daataa daiaal anbhoot dharam | 2 | 122 |","meaning_en":"","page":114}]},{"type":"verse","number":[3,123],"number_text":"੩। ੧੨੩।","page":114,"lines":[{"gurmukhi":"ਜਿਹ ਸਤ੍ਰ ਮਿਤ੍ਰ ਨਹੀ ਜਨਮ ਜਾਤਿ। ਜਿਹ ਪੁਤ੍ਰ ਭ੍ਰਾਤ ਨਹੀ ਮਿਤ੍ਰ ਮਾਤ।","roman":"Jih satr mitr nahee janam jaati | jih putr bhraat nahee mitr maat |","meaning_en":"","page":114},{"gurmukhi":"ਜਿਹ ਕਰਮ ਭਰਮ ਨਹੀ ਧਰਮ ਧਿਆਨ। ਜਿਹ ਨੇਹ ਗੇਹ ਨਹੀ ਬਿਓਤਬਾਨ। ੩। ੧੨੩।","roman":"Jih karam bharam nahee dharam dhiaan | jih neh geh nahee biotbaan | 3 | 123 |","meaning_en":"","page":114}]},{"type":"verse","number":[4,124],"number_text":"੪। ੧੨੪।","page":114,"lines":[{"gurmukhi":"ਜਿਹ ਜਾਤਿ ਪਾਤਿ ਨਹੀ ਸਤ੍ਰ ਮਿਤ੍ਰ। ਜਿਹ ਨੇਹ ਗੇਹ ਨਹੀ ਚਿਹਨ ਚਿਤ੍ਰ।","roman":"Jih jaati paati nahee satr mitr | jih neh geh nahee chihan chitr |","meaning_en":"","page":114},{"gurmukhi":"ਜਿਹ ਰੰਗ ਰੂਪ ਨਹੀ ਰਾਗ ਰੇਖ। ਜਿਹ ਜਨਮ ਜਾਤਿ ਨਹੀ ਭਰਮ ਭੇਖ। ੪। ੧੨੪।","roman":"Jih rang roop nahee raag rekh | jih janam jaati nahee bharam bhekh | 4 | 124 |","meaning_en":"","page":114}]},{"type":"verse","number":[5,125],"number_text":"੫। ੧੨੫।","page":114,"lines":[{"gurmukhi":"ਜਿਹ ਕਰਮ ਭਰਮ ਨਹੀ ਜਾਤਿ ਪਾਤਿ। ਨਹੀ ਨੇਹ ਗੇਹ ਨਹੀ ਪਿਤ੍ਰ ਮਾਤ।","roman":"Jih karam bharam nahee jaati paati | nahee neh geh nahee pitr maat |","meaning_en":"","page":114},{"gurmukhi":"ਜਿਹ ਨਾਮ ਥਾਮ ਨਹੀ ਬਰਗ ਬਿਆਧ। ਜਿਹ ਰੋਗ ਸੋਗ ਨਹੀ ਸਤ੍ਰ ਸਾਧ। ੫। ੧੨੫।","roman":"Jih naam thaam nahee barag biaadh | jih rog sog nahee satr saadh | 5 | 125 |","meaning_en":"","page":114}]},{"type":"verse","number":[6,126],"number_text":"੬। ੧੨੬।","page":114,"lines":[{"gurmukhi":"ਜਿਹ ਤ੍ਰਾਸ ਵਾਸ ਨਹੀ ਦੇਹ ਨਾਸ। ਜਿਹ ਆਦਿ ਅੰਤ ਨਹੀ ਰੂਪ ਰਾਸਿ।","roman":"Jih traas vaas nahee deh naas | jih aadi ant nahee roop raasi |","meaning_en":"","page":114},{"gurmukhi":"ਜਿਹ ਰੋਗ ਸੋਗ ਨਹੀ ਜੋਗ ਜੁਗਤਿ। ਜਿਹ ਤ੍ਰਾਸ ਆਸ ਨਹੀ ਭੂਮਿ ਭੁਗਤ। ੬। ੧੨੬।","roman":"Jih rog sog nahee jog jugti | jih traas aas nahee bhoomi bhugat | 6 | 126 |","meaning_en":"","page":114}]},{"type":"verse","number":[7,127],"number_text":"੭। ੧੨੭।","page":114,"lines":[{"gurmukhi":"ਜਿਹ ਕਾਲ ਬਿਆਲ ਕਟਿਓ ਨ ਅੰਗ। ਅਛੈ ਸਰੂਪ ਅਖੈ ਅਭੰਗ।","roman":"Jih kaal biaal katio na ang | achhai saroop akhai abhang |","meaning_en":"","page":114},{"gurmukhi":"ਜਿਹ ਨੇਤਿ ਨੇਤਿ ਉਚਰੰਤ ਬੇਦ। ਜਿਹ ਅਲਖ ਰੂਪ ਕਥਤ ਕਤੇਬ। ੭। ੧੨੭।","roman":"Jih neti neti uchrant bed | jih alakh roop kathat kateb | 7 | 127 |","meaning_en":"","page":114}]},{"type":"verse","number":[8,128],"number_text":"੮। ੧੨੮।","page":114,"lines":[{"gurmukhi":"ਜਿਹ ਅਲਖ ਰੂਪ ਆਸਨ ਅਡੋਲ। ਜਿਹ ਅਮਿਤ ਤੇਜ ਅਛੈ ਅਤੋਲ।","roman":"Jih alakh roop aasan adol | jih amit tej achhai atol |","meaning_en":"","page":114},{"gurmukhi":"ਜਿਹ ਧਿਆਨ ਕਾਜ ਮੁਨਿ ਜਨ ਅਨੰਤ। ਕਈ ਕਲਪ ਜੋਗ ਸਾਧਤ ਦੁਰੰਤ। ੮। ੧੨੮।","roman":"Jih dhiaan kaaj muni jan anant | kaee kalap jog saadhat durant | 8 | 128 |","meaning_en":"","page":114}]},{"type":"verse","number":[9,129],"number_text":"੯। ੧੨੯।","page":115,"lines":[{"gurmukhi":"ਤਨ ਸੀਤ ਘਾਮ ਬਰਖਾ ਸਹੰਤ। ਕਈ ਕਲਪ ਏਕ ਆਸਨ ਬਿਤੰਤ।","roman":"Tan seet ghaam barkhaa sahant | kaee kalap ek aasan bitant |","meaning_en":"","page":115},{"gurmukhi":"ਕਈ ਜਤਨ ਜੋਗ ਬਿਦਿਆ ਬਿਚਾਰਿ। ਸਾਧੰਤ ਤਦਪਿ ਪਾਵਤ ਨ ਪਾਰ। ੯। ੧੨੯।","roman":"Kaee jatan jog bidiaa bichaari | saadhant tadpi paavat na paar | 9 | 129 |","meaning_en":"","page":115}]},{"type":"verse","number":[10,130],"number_text":"੧੦। ੧੩੦।","page":115,"lines":[{"gurmukhi":"ਕਈ ਉਰਧ ਬਾਹ ਦੇਸਨ ਭ੍ਰਮੰਤ। ਕਈ ਉਰਧ ਮਧ ਪਾਕ ਝੁਲੰਤ।","roman":"Kaee uradh baah desan bhramant | kaee uradh madh paak jhulant |","meaning_en":"","page":115},{"gurmukhi":"ਕਈ ਸਿਮ੍ਰਿਤ ਸਾਸਤ੍ਰ ਉਚਰੰਤ ਬੇਦ। ਕਈ ਕੋਕ ਕਾਬਿ ਕਥਤ ਕਤੇਬ। ੧੦। ੧੩੦।","roman":"Kaee simrit saasatr uchrant bed | kaee kok kaabi kathat kateb | 10 | 130 |","meaning_en":"","page":115}]},{"type":"verse","number":[11,131],"number_text":"੧੧। ੧੩੧।","page":115,"lines":[{"gurmukhi":"ਕਈ ਅਗਨਿਹੋਤ੍ਰ ਕਈ ਪਉਨ ਅਹਾਰ। ਕਈ ਕਰਤ ਕੋਟ ਮ੍ਰਿਤ ਕੋ ਅਹਾਰ।","roman":"Kaee agnihotr kaee paun ahaar | kaee karat kot mrit ko ahaar |","meaning_en":"","page":115},{"gurmukhi":"ਕਈ ਕਰਤ ਸਾਕ ਪੈ ਪਤ੍ਰ ਭਛ। ਨਹੀ ਤਦਪਿ ਦੇਵ ਹੋਵਤ ਪ੍ਰਤਛ। ੧੧। ੧੩੧।","roman":"Kaee karat saak pai patr bhachh | nahee tadpi dev hovat pratachh | 11 | 131 |","meaning_en":"","page":115}]},{"type":"verse","number":[12,132],"number_text":"੧੨। ੧੩੨।","page":115,"lines":[{"gurmukhi":"ਕਈ ਗੀਤ ਗਾਨ ਗੰਧ੍ਰਬ ਰੀਤਿ। ਕਈ ਬੇਦ ਸਾਸਤ੍ਰ ਬਿਦਿਆ ਪ੍ਰਤੀਤਿ।","roman":"Kaee geet gaan gandhrab reeti | kaee bed saasatr bidiaa prateeti |","meaning_en":"","page":115},{"gurmukhi":"ਕਹੂੰ ਬੇਦ ਰੀਤਿ ਜਗ ਆਦਿ ਕਰਮ। ਕਹੂੰ ਅਗਨਿਹੋਤ੍ਰ ਕਹੂੰ ਤੀਰਥ ਧਰਮ। ੧੨। ੧੩੨।","roman":"Kahoon bed reeti jag aadi karam | kahoon agnihotr kahoon teerath dharam | 12 | 132 |","meaning_en":"","page":115}]},{"type":"verse","number":[13,133],"number_text":"੧੩। ੧੩੩।","page":115,"lines":[{"gurmukhi":"ਕਈ ਦੇਸਿ ਦੇਸਿ ਭਾਖਾ ਰਟੰਗ। ਕਈ ਦੇਸਿ ਦੇਸਿ ਬਿਦਿਆ ਪੜੰਤ।","roman":"Kaee desi desi bhaakhaa ratang | kaee desi desi bidiaa parant |","meaning_en":"","page":115},{"gurmukhi":"ਕਈ ਕਰਤ ਭਾਤਿ ਭਾਤਨ ਬਿਚਾਰ। ਨਹੀ ਨੇਕੁ ਤਾਸੁ ਪਾਯਤ ਨ ਪਾਰ। ੧੩। ੧੩੩।","roman":"Kaee karat bhaati bhaatan bichaar | nahee neku taasu paayat na paar | 13 | 133 |","meaning_en":"","page":115}]},{"type":"verse","number":[14,134],"number_text":"੧੪। ੧੩੪।","page":115,"lines":[{"gurmukhi":"ਕਈ ਤੀਰਥ ਤੀਰਥ ਭਰਮਤ ਸੁ ਭਰਮ। ਕਈ ਅਗਨਿਹੋਤ੍ਰ ਕਈ ਦੇਵ ਕਰਮ।","roman":"Kaee teerath teerath bharmat su bharam | kaee agnihotr kaee dev karam |","meaning_en":"","page":115},{"gurmukhi":"ਕਈ ਕਰਤ ਬੀਰ ਬਿਦਿਆ ਬਿਚਾਰ। ਨਹੀ ਤਦਪਿ ਤਾਸੁ ਪਾਯਤ ਨ ਪਾਰ। ੧੪। ੧੩੪।","roman":"Kaee karat beer bidiaa bichaar | nahee tadpi taasu paayat na paar | 14 | 134 |","meaning_en":"","page":115}]},{"type":"verse","number":[15,135],"number_text":"੧੫। ੧੩੫।","page":115,"lines":[{"gurmukhi":"ਕਹੂੰ ਰਾਜਰੀਤਿ ਕਹੂੰ ਜੋਗ ਧਰਮ। ਕਈ ਸਿੰਮ੍ਰਿਤ ਸਾਸਤ੍ਰ ਉਚਰਤ ਸੁਕਰਮ।","roman":"Kahoon raajreeti kahoon jog dharam | kaee sinmrit saasatr uchrat sukram |","meaning_en":"","page":115},{"gurmukhi":"ਨਿਉਲੀ ਆਦਿ ਕਰਮ ਕਹੂੰ ਹਸਤਿ ਦਾਨ। ਕਹੂੰ ਅਸ੍ਵਮੇਧ ਮਖ ਕੋ ਬਖਾਨ। ੧੫। ੧੩੫।","roman":"Niulee aadi karam kahoon hasti daan | kahoon asvamedh makh ko bakhaan | 15 | 135 |","meaning_en":"","page":115}]},{"type":"verse","number":[16,136],"number_text":"੧੬। ੧੩੬।","page":115,"lines":[{"gurmukhi":"ਕਹੂੰ ਕਰਤ ਬ੍ਰਹਮ ਬਿਦਿਆ ਬਿਚਾਰ। ਕਹੂੰ ਜੋਗ ਰੀਤਿ ਕਹੂੰ ਬਿਰਧਿ ਚਾਰਿ।","roman":"Kahoon karat braham bidiaa bichaar | kahoon jog reeti kahoon birdhi chaari |","meaning_en":"","page":115},{"gurmukhi":"ਕਹੂੰ ਕਰਤ ਜਛ ਗੰਧਰਬ ਗਾਨ। ਕਹੂੰ ਧੂਪ ਦੀਪ ਕਹੂੰ ਅਰਘ ਦਾਨ। ੧੬। ੧੩੬।","roman":"Kahoon karat jachh gandhrab gaan | kahoon dhoop deep kahoon aragh daan | 16 | 136 |","meaning_en":"","page":115}]},{"type":"verse","number":[17,137],"number_text":"੧੭। ੧੩੭।","page":115,"lines":[{"gurmukhi":"ਕਹੂੰ ਪਿਤ੍ਰ ਕਰਮ ਕਹੂੰ ਬੇਦ ਰੀਤਿ। ਕਹੂੰ ਨ੍ਰਿਤ ਨਾਚ ਕਹੂੰ ਗਾਨ ਗੀਤ।","roman":"Kahoon pitr karam kahoon bed reeti | kahoon nrit naach kahoon gaan geet |","meaning_en":"","page":115},{"gurmukhi":"ਕਹੂੰ ਕਰਤ ਸਾਸਤ੍ਰ ਸਿੰਮ੍ਰਿਤਿ ਉਚਾਰ। ਕਈ ਭਜਤ ਏਕ ਪਗ ਨਿਰਾਧਾਰ। ੧੭। ੧੩੭।","roman":"Kahoon karat saasatr sinmriti uchaar | kaee bhajat ek pag niraadhaar | 17 | 137 |","meaning_en":"","page":115}]},{"type":"verse","number":[18,138],"number_text":"੧੮। ੧੩੮।","page":115,"lines":[{"gurmukhi":"ਕਈ ਨੇਹ ਦੇਹ ਕਈ ਗੇਹ ਵਾਸ। ਕਈ ਭ੍ਰਮਤ ਦੇਸ ਦੇਸਨ ਉਦਾਸ।","roman":"Kaee neh deh kaee geh vaas | kaee bhramat des desan udaas |","meaning_en":"","page":115},{"gurmukhi":"ਕਈ ਜਲ ਨਿਵਾਸ ਕਈ ਅਗਨਿ ਤਾਪ। ਕਈ ਜਪਤ ਉਰਧ ਲਟਕੰਤ ਜਾਪ। ੧੮। ੧੩੮।","roman":"Kaee jal nivaas kaee agni taap | kaee japat uradh latkant jaap | 18 | 138 |","meaning_en":"","page":115}]},{"type":"verse","number":[19,139],"number_text":"੧੯। ੧੩੯।","page":115,"lines":[{"gurmukhi":"ਕਈ ਜਪਤ ਜੋਗ ਕਲਪੰ ਪ੍ਰਜੰਤ। ਨਹੀ ਤਦਪਿ ਤਾਸ ਪਾਯਤ ਨ ਅੰਤ।","roman":"Kaee japat jog kalpan prajant | nahee tadpi taas paayat na ant |","meaning_en":"","page":115},{"gurmukhi":"ਕਈ ਕਰਤ ਕੋਟ ਬਿਦਿਆ ਬਿਚਾਰ। ਨਹੀ ਤਦਪਿ ਦਿਸਟਿ ਦੇਖੇ ਮੁਰਾਰਿ। ੧੯। ੧੩੯।","roman":"Kaee karat kot bidiaa bichaar | nahee tadpi disti dekhe muraari | 19 | 139 |","meaning_en":"","page":115}]},{"type":"verse","number":[20,140],"number_text":"੨੦। ੧੪੦।","page":116,"lines":[{"gurmukhi":"ਬਿਨੁ ਭਗਤਿ ਸਕਤਿ ਨਹੀ ਪਰਤ ਪਾਨ। ਬਹੁ ਕਰਤ ਹੋਮ ਅਰੁ ਜਗ ਦਾਨ।","roman":"Binu bhagti sakti nahee parat paan | bahu karat hom aru jag daan |","meaning_en":"","page":116},{"gurmukhi":"ਬਿਨੁ ਏਕ ਨਾਮੁ ਇਕ ਚਿਤ ਲੀਨ। ਫੋਕਟੋ ਸਰਬ ਧਰਮਾ ਬਿਹੀਨ। ੨੦। ੧੪੦।","roman":"Binu ek naamu ik chit leen | phokto sarab dharmaa biheen | 20 | 140 |","meaning_en":"","page":116}]},{"type":"heading","kind":"chhand","name":"ਤੋਟਕ ਛੰਦ","gurmukhi":"ਤ੍ਵਪ੍ਰਸਾਦਿ। ਤੋਟਕ ਛੰਦ","roman":"Tvaprasaadi | totak chhand","meaning_en":"","page":116,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[1,141],"number_text":"੧। ੧੪੧।","page":116,"lines":[{"gurmukhi":"ਜੈ ਜੰਪਹਿ ਜੁਗਣ ਜੂਹ ਜੁਅੰ। ਭੈ ਕੰਪਹਿ ਮੇਰੁ ਪਯਾਲ ਭੁਅੰ।","roman":"Jai janphi jugan jooh juan | bhai kanphi meru payaal bhuan |","meaning_en":"","page":116},{"gurmukhi":"ਤਪ ਤਾਪਸ ਸਰਬ ਜਲੇਰੁ ਥਲੰ। ਧੰਨਿ ਉਚਰਤ ਇੰਦ੍ਰ ਕੁਮੇਰ ਬਲੰ। ੧। ੧੪੧।","roman":"Tap taapas sarab jaleru thalan | dhanni uchrat indr kumer balan | 1 | 141 |","meaning_en":"","page":116}]},{"type":"verse","number":[2,142],"number_text":"੨। ੧੪੨।","page":116,"lines":[{"gurmukhi":"ਅਨਖੇਦ ਸਰੂਪ ਅਭੇਦ ਅਭਿਅੰ। ਅਨਖੰਡ ਅਭੂਤ ਅਛੇਦ ਅਛਿਅੰ।","roman":"Ankhed saroop abhed abhian | ankhand abhoot achhed achhian |","meaning_en":"","page":116},{"gurmukhi":"ਅਨਕਾਲ ਅਪਾਲ ਦਿਆਲ ਅਸੁਅੰ। ਜਿਹ ਠਟੀਅੰ ਮੇਰ ਅਕਾਸ ਭੁਅੰ। ੨। ੧੪੨।","roman":"Ankaal apaal diaal asuan | jih thateean mer akaas bhuan | 2 | 142 |","meaning_en":"","page":116}]},{"type":"verse","number":[3,143],"number_text":"੩। ੧੪੩।","page":116,"lines":[{"gurmukhi":"ਅਨਖੰਡ ਅਮੰਡ ਪ੍ਰਚੰਡ ਨਰੰ। ਜਿਹ ਰਚੀਅੰ ਦੇਵ ਅਦੇਵ ਬਰੰ।","roman":"Ankhand amand prachand naran | jih racheean dev adev baran |","meaning_en":"","page":116},{"gurmukhi":"ਸਭ ਕੀਨੀ ਦੀਨ ਜਮੀਨੁ ਜਮਾਂ। ਜਿਹ ਰਚੀਅੰ ਸਰਬ ਮਕੀਨੁ ਮਕਾਂ। ੩। ੧੪੩।","roman":"Sabh keenee deen jameenu jamaan | jih racheean sarab makeenu makaan | 3 | 143 |","meaning_en":"","page":116}]},{"type":"verse","number":[4,144],"number_text":"੪। ੧੪੪।","page":116,"lines":[{"gurmukhi":"ਜਿਹ ਰਾਗ ਨ ਰੂਪ ਨ ਰੇਖ ਰੁਖੰ। ਜਿਹ ਤਾਪ ਨ ਸਾਪ ਨ ਸੋਕ ਸੁਖੰ।","roman":"Jih raag na roop na rekh rukhan | jih taap na saap na sok sukhan |","meaning_en":"","page":116},{"gurmukhi":"ਨ ਰੋਗ ਨ ਸੋਗ ਨ ਭੋਗ ਭੁਯੰ। ਜਿਹ ਖੇਦ ਨ ਭੇਦ ਨ ਛੇਦ ਛਯੰ। ੪। ੧੪੪।","roman":"Na rog na sog na bhog bhuyan | jih khed na bhed na chhed chhayan | 4 | 144 |","meaning_en":"","page":116}]},{"type":"verse","number":[5,145],"number_text":"੫।੧੪੫।","page":116,"lines":[{"gurmukhi":"ਜਿਹ ਜਾਤਿ ਨ ਪਾਤਿ ਨ ਮਾਤ ਪਿਤੰ। ਜਿਹ ਰਚੀਅੰ ਛਤ੍ਰੀ ਛਤ੍ਰ ਛਿਤੰ।","roman":"Jih jaati na paati na maat pitan | jih racheean chhatree chhatr chhitan |","meaning_en":"","page":116},{"gurmukhi":"ਜਿਹ ਰਾਗ ਨ ਰੇਖ ਨ ਰੋਗ ਭਣੰ। ਜਿਹ ਦ੍ਵੈਖ ਨ ਦਾਗ ਨ ਦੋਖ ਗਣੰ। ੫।੧੪੫।","roman":"Jih raag na rekh na rog bhanan | jih dvaikh na daag na dokh ganan | 5 | 145 |","meaning_en":"","page":116}]},{"type":"verse","number":[6,146],"number_text":"੬। ੧੪੬।","page":116,"lines":[{"gurmukhi":"ਜਿਹ ਅੰਡਹ ਤੇ ਬ੍ਰਹਮੰਡ ਰਚਿਓ। ਦਸ ਚਾਰ ਕਰੀ ਨਵ ਖੰਡ ਸਚਿਓ।","roman":"Jih andah te brahmand rachio | das chaar karee nav khand sachio |","meaning_en":"","page":116},{"gurmukhi":"ਰਜ ਤਾਮਸ ਤੇਜ ਅਤੇਜ ਕੀਓ। ਅਨਭਉ ਪਦ ਆਪ ਪ੍ਰਚੰਡ ਲੀਓ। ੬। ੧੪੬।","roman":"Raj taamas tej atej keeo | anbhau pad aap prachand leeo | 6 | 146 |","meaning_en":"","page":116}]},{"type":"verse","number":[7,147],"number_text":"੭।੧੪੭।","page":116,"lines":[{"gurmukhi":"ਸ੍ਰਿਅ ਸਿੰਧਰੁ ਬਿੰਧ ਨਗਿੰਧ ਨਗੰ। ਸ੍ਰਿਅ ਜਛ ਗੰਧ੍ਰਬ ਫਣਿੰਦ ਭੁਜੰ।","roman":"Sria sindhru bindh nagindh nagan | sria jachh gandhrab phanind bhujan |","meaning_en":"","page":116},{"gurmukhi":"ਰਚਿ ਦੇਵ ਅਦੇਵ ਅਭੇਵ ਨਗੰ। ਨਰਪਾਲ ਨ੍ਰਿਪਾਲ ਕਰਾਲ ਤ੍ਰਿਗੰ। ੭।੧੪੭।","roman":"Rachi dev adev abhev nagan | narpaal nripaal karaal trigan | 7 | 147 |","meaning_en":"","page":116}]},{"type":"verse","number":[8,148],"number_text":"੮। ੧੪੮।","page":116,"lines":[{"gurmukhi":"ਕਈ ਕੀਟ ਪਤੰਗ ਭੁਜੰਗ ਨਰੰ। ਰਚਿ ਅੰਡਜ ਸੇਤਜ ਉਤਭੁਜੰ।","roman":"Kaee keet patang bhujang naran | rachi andaj setaj utbhujan |","meaning_en":"","page":116},{"gurmukhi":"ਕੀਏ ਦੇਵ ਅਦੇਵ ਸਰਾਧ ਪਿਤੰ। ਅਨਖੰਡ ਪ੍ਰਤਾਪ ਪ੍ਰਚੰਡ ਗਤੰ। ੮। ੧੪੮।","roman":"Kee'e dev adev saraadh pitan | ankhand prataap prachand gatan | 8 | 148 |","meaning_en":"","page":116}]},{"type":"verse","number":[9,149],"number_text":"੯। ੧੪੯।","page":116,"lines":[{"gurmukhi":"ਪ੍ਰਭ ਜਾਤਿ ਨ ਪਾਤਿ ਨ ਜੋਤਿ ਜੁਤੰ। ਜਿਹ ਤਾਤ ਨ ਮਾਤ ਨ ਭ੍ਰਾਤ ਸੁਤੰ।","roman":"Prabh jaati na paati na joti jutan | jih taat na maat na bhraat sutan |","meaning_en":"","page":116},{"gurmukhi":"ਜਿਹ ਰੋਗ ਨ ਸੋਗ ਨ ਭੋਗ ਭੁਅੰ। ਜਿਹ ਜੰਪਹਿ ਕਿੰਨਰ ਜਛ ਜੁਅੰ। ੯। ੧੪੯।","roman":"Jih rog na sog na bhog bhuan | jih janphi kinnar jachh juan | 9 | 149 |","meaning_en":"","page":116}]},{"type":"verse","number":[10,150],"number_text":"੧੦। ੧੫੦।","page":117,"lines":[{"gurmukhi":"ਨਰ ਨਾਰਿ ਨਪੁੰਸਕ ਜਾਹਿ ਕੀਏ। ਗਣ ਕਿੰਨਰ ਜਛ ਭੁਜੰਗ ਦੀਏ।","roman":"Nar naari napunsak jaahi kee'e | gan kinnar jachh bhujang dee'e |","meaning_en":"","page":117},{"gurmukhi":"ਗਜ ਬਾਜ ਰਥਾਦਿਕ ਪਾਤਿ ਗਨੰ। ਭਵਿ ਭੂਤ ਭਵਿਖ ਭਵਾਨ ਤੁਅੰ। ੧੦। ੧੫੦।","roman":"Gaj baaj rathaadik paati ganan | bhavi bhoot bhavikh bhavaan tuan | 10 | 150 |","meaning_en":"","page":117}]},{"type":"verse","number":[11,151],"number_text":"੧੧।੧੫੧।","page":117,"lines":[{"gurmukhi":"ਜਿਹ ਅੰਡਜ ਸੇਤਜ ਜੇਰ ਰਜੰ। ਰਚਿ ਭੂਮਿ ਅਕਾਸ ਪਤਾਲ ਜਲੰ।","roman":"Jih andaj setaj jer rajan | rachi bhoomi akaas pataal jalan |","meaning_en":"","page":117},{"gurmukhi":"ਰਚਿ ਪਾਵਕ ਪਉਨ ਪ੍ਰਚੰਡ ਬਲੀ। ਬਨਿ ਜਾਸੁ ਕੀਓ ਫਲ ਫੂਲ ਕਲੀ।੧੧।੧੫੧।","roman":"Rachi paavak paun prachand balee | bani jaasu keeo phal phool kalee | 11 | 151 |","meaning_en":"","page":117}]},{"type":"verse","number":[12,152],"number_text":"੧੨।੧੫੨।","page":117,"lines":[{"gurmukhi":"ਭੂਅ ਮੇਰੁ ਅਕਾਸ ਨਿਵਾਸ ਛਿਤੰ। ਰਚਿ ਰੋਜ ਇਕਾਦਸ ਚੰਦ ਬ੍ਰਿਤੰ।","roman":"Bhooa meru akaas nivaas chhitan | rachi roj ikaadas chand britan |","meaning_en":"","page":117},{"gurmukhi":"ਦੁਤਿ ਚੰਦ ਦਿਨੀਸਰ ਦੀਪ ਦਈ। ਜਿਹ ਪਾਵਕ ਪਉਨ ਪ੍ਰਚੰਡ ਮਈ।੧੨।੧੫੨।","roman":"Duti chand dineesar deep daee | jih paavak paun prachand maee | 12 | 152 |","meaning_en":"","page":117}]},{"type":"verse","number":[13,153],"number_text":"੧੩। ੧੫੩।","page":117,"lines":[{"gurmukhi":"ਜਿਹ ਖੰਡ ਅਖੰਡ ਪ੍ਰਚੰਡ ਕੀਏ। ਜਿਹ ਛਤ੍ਰਿ ਉਪਾਇ ਛਿਪਾਇ ਦੀਏ।","roman":"Jih khand akhand prachand kee'e | jih chhatri upaai chhipaai dee'e |","meaning_en":"","page":117},{"gurmukhi":"ਜਿਹ ਲੋਕ ਚਤੁਰਦਾਸ ਚਾਰੁ ਰਚੇ। ਨਰ ਗੰਧ੍ਰਬ ਦੇਵ ਅਦੇਵ ਸਚੇ। ੧੩। ੧੫੩।","roman":"Jih lok chaturdaas chaaru rache | nar gandhrab dev adev sache | 13 | 153 |","meaning_en":"","page":117}]},{"type":"verse","number":[14,154],"number_text":"੧੪। ੧੫੪।","page":117,"lines":[{"gurmukhi":"ਅਨਧੂਤ ਅਭੂਤ ਅਛੂਤ ਮਤੰ। ਅਨਗਾਧਿ ਅਬ੍ਯਾਧਿ ਅਨਾਦਿ ਗਤੰ।","roman":"Andhoot abhoot achhoot matan | angaadhi abyaadhi anaadi gatan |","meaning_en":"","page":117},{"gurmukhi":"ਅਨਖੇਦ ਅਭੇਦ ਅਛੇਦ ਨਰੰ। ਜਿਹ ਚਾਰੁ ਚਤੁਰਦਿਸ ਚਕ੍ਰ ਫਿਰੰ। ੧੪। ੧੫੪।","roman":"Ankhed abhed achhed naran | jih chaaru chaturdis chakr phiran | 14 | 154 |","meaning_en":"","page":117}]},{"type":"verse","number":[15,155],"number_text":"੧੫। ੧੫੫।","page":117,"lines":[{"gurmukhi":"ਜਿਹ ਰਾਗ ਨ ਰੰਗ ਨ ਰੇਖ ਰੁਗੰ। ਜਿਹ ਸੋਗ ਨ ਭੋਗ ਨ ਜੋਗ ਜੁਗੰ।","roman":"Jih raag na rang na rekh rugan | jih sog na bhog na jog jugan |","meaning_en":"","page":117},{"gurmukhi":"ਭੂਅ ਭੰਜਨ ਗੰਜਨ ਆਦਿ ਸਿਰੰ। ਜਿਹ ਬੰਦਤ ਦੇਵ ਅਦੇਵ ਨਰੰ। ੧੫। ੧੫੫।","roman":"Bhooa bhanjan ganjan aadi siran | jih bandat dev adev naran | 15 | 155 |","meaning_en":"","page":117}]},{"type":"verse","number":[16,156],"number_text":"੧੬। ੧੫੬।","page":117,"lines":[{"gurmukhi":"ਗਣ ਕਿੰਨਰ ਜਛ ਭੁਜੰਗ ਰਚੇ। ਮਣਿ ਮਾਣਿਕ ਮੋਤੀ ਲਾਲ ਸਚੇ।","roman":"Gan kinnar jachh bhujang rache | mani maanik motee laal sache |","meaning_en":"","page":117},{"gurmukhi":"ਅਨਭੰਜ ਪ੍ਰਭਾ ਅਨਗੰਜ ਬ੍ਰਿਤੰ। ਜਿਹ ਪਾਰ ਨ ਪਾਵਤ ਪੂਰ ਮਤੰ। ੧੬। ੧੫੬।","roman":"Anbhanj prabhaa anganj britan | jih paar na paavat poor matan | 16 | 156 |","meaning_en":"","page":117}]},{"type":"verse","number":[17,157],"number_text":"੧੭। ੧੫੭।","page":117,"lines":[{"gurmukhi":"ਅਨਖੰਡ ਸਰੂਪ ਅਡੰਡ ਪ੍ਰਭਾ। ਜੈ ਜੰਪਤ ਬੇਦ ਪੁਰਾਨ ਸਭਾ।","roman":"Ankhand saroop adand prabhaa | jai janpat bed puraan sabhaa |","meaning_en":"","page":117},{"gurmukhi":"ਜਿਹ ਬੇਦ ਕਤੇਬ ਅਨੰਤ ਕਹੈ। ਜਿਹ ਭੂਤ ਅਭੂਤ ਨ ਭੇਦ ਲਹੈ। ੧੭। ੧੫੭।","roman":"Jih bed kateb anant kahai | jih bhoot abhoot na bhed lahai | 17 | 157 |","meaning_en":"","page":117}]},{"type":"verse","number":[18,158],"number_text":"੧੮। ੧੫੮।","page":117,"lines":[{"gurmukhi":"ਜਿਹ ਬੇਦ ਪੁਰਾਨ ਕਤੇਬ ਜਪੈ। ਸੁਤ ਸਿੰਧੁ ਅਧੋਮੁਖ ਤਾਪ ਤਪੈ।","roman":"Jih bed puraan kateb japai | sut sindhu adhomukh taap tapai |","meaning_en":"","page":117},{"gurmukhi":"ਕਈ ਕਲਪਨ ਲੌ ਤਪ ਤਾਪ ਕਰੈ। ਨਹੀ ਨੈਕੁ ਕ੍ਰਿਪਾਨਿਧਿ ਪਾਨਿ ਪਰੈ। ੧੮। ੧੫੮।","roman":"Kaee kalpan lau tap taap karai | nahee naiku kripaanidhi paani parai | 18 | 158 |","meaning_en":"","page":117}]},{"type":"verse","number":[19,159],"number_text":"੧੯। ੧੫੯।","page":117,"lines":[{"gurmukhi":"ਜਿਹ ਫੋਕਟ ਧਰਮ ਸਭੈ ਤਜ ਹੈ। ਇਕ ਚਿਤ ਕ੍ਰਿਪਾਨਿਧਿ ਕੋ ਭਜ ਹੈ।","roman":"Jih phokat dharam sabhai taj hai | ik chit kripaanidhi ko bhaj hai |","meaning_en":"","page":117},{"gurmukhi":"ਤੇਊ ਯਾ ਭਵ ਸਾਗਰ ਕੋ ਤਰ ਹੈ। ਭਵਿ ਭੂਲਿ ਨ ਦੇਹ ਪੁਨਰ ਧਰ ਹੈ। ੧੯। ੧੫੯।","roman":"Teoo yaa bhav saagar ko tar hai | bhavi bhooli na deh punar dhar hai | 19 | 159 |","meaning_en":"","page":117}]},{"type":"verse","number":[20,160],"number_text":"੨੦। ੧੬੦।","page":117,"lines":[{"gurmukhi":"ਇਕ ਨਾਮ ਬਿਨਾ ਨਹੀ ਕੋਟਿ ਬ੍ਰਿਤੀ। ਇਮ ਬੇਦ ਉਚਾਰਤ ਸਾਰਸੁਤੀ।","roman":"Ik naam binaa nahee koti britee | im bed uchaarat saarsutee |","meaning_en":"","page":117},{"gurmukhi":"ਜੋਊ ਵਾ ਰਸ ਕੇ ਚਸਕੇ ਰਸ ਹੈ। ਤੇਊ ਭੂਲਿ ਨ ਕਾਲ ਫੰਧਾ ਫਸ ਹੈ। ੨੦। ੧੬੦।","roman":"Jo'oo vaa ras ke chaske ras hai | teoo bhooli na kaal phandhaa phas hai | 20 | 160 |","meaning_en":"","page":117}]},{"type":"heading","kind":"chhand","name":"ਨਰਾਜ ਛੰਦ","gurmukhi":"ਤ੍ਵਪ੍ਰਸਾਦਿ। ਨਰਾਜ ਛੰਦ","roman":"Tvaprasaadi | naraaj chhand","meaning_en":"","page":118,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[1,161],"number_text":"੧। ੧੬੧।","page":118,"lines":[{"gurmukhi":"ਅਗੰਜ ਆਦਿ ਦੇਵ ਹੈ ਅਭੰਜ ਭੰਜ ਜਾਨੀਐ।","roman":"Aganj aadi dev hai abhanj bhanj jaaneeai |","meaning_en":"","page":118},{"gurmukhi":"ਅਭੂਤ ਭੂਤ ਹੈ ਸਦਾ ਅਗੰਜ ਗੰਜ ਮਾਨੀਐ।","roman":"Abhoot bhoot hai sadaa aganj ganj maaneeai |","meaning_en":"","page":118},{"gurmukhi":"ਅਦੇਵ ਦੇਵ ਹੈ ਸਦਾ ਅਭੇਵ ਭੇਵ ਨਾਥ ਹੈ।","roman":"Adev dev hai sadaa abhev bhev naath hai |","meaning_en":"","page":118},{"gurmukhi":"ਸਮਸਤ ਸਿਧਿ ਬ੍ਰਿਧਿਦਾ ਸਦੀਵ ਸਰਬ ਸਾਥ ਹੈ। ੧। ੧੬੧।","roman":"Samsat sidhi bridhidaa sadeev sarab saath hai | 1 | 161 |","meaning_en":"","page":118}]},{"type":"verse","number":[2,162],"number_text":"੨। ੧੬੨।","page":118,"lines":[{"gurmukhi":"ਅਨਾਥ ਨਾਥ ਨਾਥ ਹੈ ਅਭੰਜ ਭੰਜ ਹੈ ਸਦਾ।","roman":"Anaath naath naath hai abhanj bhanj hai sadaa |","meaning_en":"","page":118},{"gurmukhi":"ਅਗੰਜ ਗੰਜ ਗੰਜ ਹੈ ਸਦੀਵ ਸਿਧਿ ਬ੍ਰਿਧਿਦਾ।","roman":"Aganj ganj ganj hai sadeev sidhi bridhidaa |","meaning_en":"","page":118},{"gurmukhi":"ਅਨੂਪ ਰੂਪ ਸਰੂਪ ਹੈ ਅਛਿਜ ਤੇਜ ਮਾਨੀਐ।","roman":"Anoop roop saroop hai achhij tej maaneeai |","meaning_en":"","page":118},{"gurmukhi":"ਸਦੀਵ ਸਿਧਿ ਸੁਧਿ ਦਾ ਪ੍ਰਤਾਪ ਪਤ੍ਰ ਜਾਨੀਐ। ੨। ੧੬੨।","roman":"Sadeev sidhi sudhi daa prataap patr jaaneeai | 2 | 162 |","meaning_en":"","page":118}]},{"type":"verse","number":[3,163],"number_text":"੩। ੧੬੩।","page":118,"lines":[{"gurmukhi":"ਨ ਰਾਗ ਰੰਗ ਰੂਪ ਹੈ ਨ ਰੋਗ ਰਾਗ ਰੇਖ ਹੈ।","roman":"Na raag rang roop hai na rog raag rekh hai |","meaning_en":"","page":118},{"gurmukhi":"ਅਦੋਖ ਅਦਾਗ ਅਦਗ ਹੈ ਅਭੂਤ ਅਭ੍ਰਮ ਅਭੇਖ ਹੈ।","roman":"Adokh adaag adag hai abhoot abhram abhekh hai |","meaning_en":"","page":118},{"gurmukhi":"ਨ ਤਾਤ ਮਾਤ ਜਾਤਿ ਹੈ ਨ ਪਾਤਿ ਚਿਹਨ ਬਰਨ ਹੈ।","roman":"Na taat maat jaati hai na paati chihan baran hai |","meaning_en":"","page":118},{"gurmukhi":"ਅਦੇਖ ਅਸੇਖ ਅਭੇਖ ਹੈ ਸਦੀਵ ਬਿਸੁ ਭਰਨ ਹੈ। ੩। ੧੬੩।","roman":"Adekh asekh abhekh hai sadeev bisu bharan hai | 3 | 163 |","meaning_en":"","page":118}]},{"type":"verse","number":[4,164],"number_text":"੪।੧੬੪।","page":118,"lines":[{"gurmukhi":"ਬਿਸ੍ਵੰਭਰ ਬਿਸੁਨਾਥ ਹੈ ਬਿਸੇਖ ਬਿਸ੍ਵ ਭਰਨ ਹੈ।","roman":"Bisvanbhar bisunaath hai bisekh bisv bharan hai |","meaning_en":"","page":118},{"gurmukhi":"ਜਿਮੀ ਜਮਾਨ ਕੇ ਬਿਖੈ ਸਦੀਵ ਕਰਮ ਭਰਮ ਹੈ।","roman":"Jimee jamaan ke bikhai sadeev karam bharam hai |","meaning_en":"","page":118},{"gurmukhi":"ਅਦ੍ਵੈਖ ਹੈ ਅਭੇਖ ਹੈ ਅਲੇਖ ਨਾਥ ਜਾਨੀਐ।","roman":"Advaikh hai abhekh hai alekh naath jaaneeai |","meaning_en":"","page":118},{"gurmukhi":"ਸਦੀਵ ਸਰਬ ਠਉਰ ਮੈ ਬਿਸੇਖ ਆਨ ਮਾਨੀਐ। ੪।੧੬੪।","roman":"Sadeev sarab thaur mai bisekh aan maaneeai | 4 | 164 |","meaning_en":"","page":118}]},{"type":"verse","number":[5,165],"number_text":"੫। ੧੬੫।","page":118,"lines":[{"gurmukhi":"ਨ ਜੰਤ੍ਰ ਮੈ ਨ ਤੰਤ੍ਰ ਮੈ ਨ ਮੰਤ੍ਰ ਬਸਿ ਆਵਈ।","roman":"Na jantr mai na tantr mai na mantr basi aavaee |","meaning_en":"","page":118},{"gurmukhi":"ਪੁਰਾਨ ਔ ਕੁਰਾਨ ਨੇਤਿ ਨੇਤਿ ਕੈ ਬਤਾਵਈ।","roman":"Puraan au kuraan neti neti kai bataavaee |","meaning_en":"","page":118},{"gurmukhi":"ਨ ਕਰਮ ਮੈ ਨ ਧਰਮ ਮੈ ਨ ਭਰਮ ਮੈ ਬਤਾਈਐ।","roman":"Na karam mai na dharam mai na bharam mai bataaeeai |","meaning_en":"","page":118},{"gurmukhi":"ਅਗੰਜ ਆਦਿ ਦੇਵ ਹੈ ਕਹੋ ਸੁ ਕੈਸਿ ਪਾਈਐ। ੫। ੧੬੫।","roman":"Aganj aadi dev hai kaho su kaisi paaeeai | 5 | 165 |","meaning_en":"","page":118}]},{"type":"verse","number":[6,166],"number_text":"੬।੧੬੬।","page":118,"lines":[{"gurmukhi":"ਜਿੰਮੀ ਜਮਾਨ ਕੇ ਬਿਖੈ ਸਮਸਤ ਏਕ ਜੋਤਿ ਹੈ।","roman":"Jinmee jamaan ke bikhai samsat ek joti hai |","meaning_en":"","page":118},{"gurmukhi":"ਨ ਘਾਟ ਹੈ ਨ ਬਾਢ ਹੈ ਨ ਘਾਟ ਬਾਢ ਹੋਤ ਹੈ।","roman":"Na ghaat hai na baadh hai na ghaat baadh hot hai |","meaning_en":"","page":118},{"gurmukhi":"ਨ ਹਾਨ ਹੈ ਨ ਬਾਨ ਹੈ ਸਮਾਨ ਰੂਪ ਜਾਨੀਐ।","roman":"Na haan hai na baan hai samaan roop jaaneeai |","meaning_en":"","page":118},{"gurmukhi":"ਮਕੀਨ ਅਉ ਮਕਾਨਿ ਅਪ੍ਰਮਾਨ ਤੇਜ ਮਾਨੀਐ। ੬।੧੬੬।","roman":"Makeen au makaani apramaan tej maaneeai | 6 | 166 |","meaning_en":"","page":118}]},{"type":"verse","number":[7,167],"number_text":"੭। ੧੬੭।","page":118,"lines":[{"gurmukhi":"ਨ ਦੇਹ ਹੈ ਨ ਗੇਹ ਹੈ ਨ ਜਾਤਿ ਹੈ ਨ ਪਾਤਿ ਹੈ।","roman":"Na deh hai na geh hai na jaati hai na paati hai |","meaning_en":"","page":118},{"gurmukhi":"ਨ ਮੰਤ੍ਰਿ ਹੈ ਨ ਮਿਤ੍ਰ ਹੈ ਨ ਤਾਤ ਹੈ ਨ ਮਾਤ ਹੈ।","roman":"Na mantri hai na mitr hai na taat hai na maat hai |","meaning_en":"","page":118},{"gurmukhi":"ਨ ਅੰਗ ਹੈ ਨ ਰੰਗ ਹੈ ਨ ਸੰਗ ਹੈ ਨ ਸਾਥ ਹੈ।","roman":"Na ang hai na rang hai na sang hai na saath hai |","meaning_en":"","page":118},{"gurmukhi":"ਨ ਦੋਖ ਹੈ ਨ ਦਾਗ ਹੈ ਨ ਦ੍ਵੈਖ ਹੈ ਨ ਦੇਹ ਹੈ। ੭। ੧੬੭।","roman":"Na dokh hai na daag hai na dvaikh hai na deh hai | 7 | 167 |","meaning_en":"","page":118}]},{"type":"verse","number":[8,168],"number_text":"੮। ੧੬੮।","page":119,"lines":[{"gurmukhi":"ਨ ਸਿੰਘ ਹੈ ਨ ਸ੍ਯਾਰ ਹੈ ਨ ਰਾਉ ਹੈ ਨ ਰੰਕ ਹੈ।","roman":"Na singh hai na syaar hai na raau hai na rank hai |","meaning_en":"","page":119},{"gurmukhi":"ਨ ਮਾਨ ਹੈ ਨ ਮੌਤ ਹੈ ਨ ਸਾਕ ਹੈ ਨ ਸੰਕ ਹੈ।","roman":"Na maan hai na maut hai na saak hai na sank hai |","meaning_en":"","page":119},{"gurmukhi":"ਨ ਜਛ ਹੈ ਨ ਗੰਧ੍ਰਬ ਹੈ ਨ ਨਰੁ ਹੈ ਨ ਨਾਰਿ ਹੈ।","roman":"Na jachh hai na gandhrab hai na naru hai na naari hai |","meaning_en":"","page":119},{"gurmukhi":"ਨ ਚੋਰ ਹੈ ਨ ਸਾਹ ਹੈ ਨ ਸਾਹ ਕੋ ਕੁਮਾਰ ਹੈ। ੮। ੧੬੮।","roman":"Na chor hai na saah hai na saah ko kumaar hai | 8 | 168 |","meaning_en":"","page":119}]},{"type":"verse","number":[9,169],"number_text":"੯। ੧੬੯।","page":119,"lines":[{"gurmukhi":"ਨ ਨੇਹ ਹੈ ਨ ਗੇਹ ਹੈ ਨ ਦੇਹ ਕੋ ਬਨਾਉ ਹੈ।","roman":"Na neh hai na geh hai na deh ko banaau hai |","meaning_en":"","page":119},{"gurmukhi":"ਨ ਛਲ ਹੈ ਨ ਛਿਦ੍ਰ ਹੈ ਨ ਛਲ ਕੋ ਮਿਲਾਉ ਹੈ।","roman":"Na chhal hai na chhidr hai na chhal ko milaau hai |","meaning_en":"","page":119},{"gurmukhi":"ਨ ਤੰਤ੍ਰ ਹੈ ਨ ਮੰਤ੍ਰ ਹੈ ਨ ਜੰਤ੍ਰ ਕੋ ਸਰੂਪ ਹੈ।","roman":"Na tantr hai na mantr hai na jantr ko saroop hai |","meaning_en":"","page":119},{"gurmukhi":"ਨ ਰਾਗ ਹੈ ਨ ਰੰਗ ਹੈ ਨ ਰੇਖ ਹੈ ਨ ਰੂਪ ਹੈ। ੯। ੧੬੯।","roman":"Na raag hai na rang hai na rekh hai na roop hai | 9 | 169 |","meaning_en":"","page":119}]},{"type":"verse","number":[10,170],"number_text":"੧੦। ੧੭੦।","page":119,"lines":[{"gurmukhi":"ਨ ਜੰਤ੍ਰ ਹੈ ਨ ਮੰਤ੍ਰ ਹੈ ਨ ਤੰਤ੍ਰ ਕੋ ਬਨਾਉ ਹੈ।","roman":"Na jantr hai na mantr hai na tantr ko banaau hai |","meaning_en":"","page":119},{"gurmukhi":"ਨ ਛਲ ਹੈ ਨ ਛਿਦ੍ਰ ਹੈ ਨ ਛਾਇਆ ਕੋ ਮਿਲਾਉ ਹੈ।","roman":"Na chhal hai na chhidr hai na chhaaiaa ko milaau hai |","meaning_en":"","page":119},{"gurmukhi":"ਨ ਰਾਗ ਹੈ ਨ ਰੰਗ ਹੈ ਨ ਰੂਪ ਹੈ ਨ ਰੇਖ ਹੈ।","roman":"Na raag hai na rang hai na roop hai na rekh hai |","meaning_en":"","page":119},{"gurmukhi":"ਨ ਕਰਮ ਹੈ ਨ ਧਰਮ ਹੈ ਅਜਨਮ ਹੈ ਅਭੇਖ ਹੈ। ੧੦। ੧੭੦।","roman":"Na karam hai na dharam hai ajnam hai abhekh hai | 10 | 170 |","meaning_en":"","page":119}]},{"type":"verse","number":[11,171],"number_text":"੧੧। ੧੭੧।","page":119,"lines":[{"gurmukhi":"ਨ ਤਾਤ ਹੈ ਨ ਮਾਤ ਹੈ ਅਖ੍ਯਾਲ ਅਖੰਡ ਰੂਪ ਹੈ।","roman":"Na taat hai na maat hai akhyaal akhand roop hai |","meaning_en":"","page":119},{"gurmukhi":"ਅਛੇਦ ਹੈ ਅਭੇਦ ਹੈ ਨ ਰੰਕ ਹੈ ਨ ਭੂਪ ਹੈ।","roman":"Achhed hai abhed hai na rank hai na bhoop hai |","meaning_en":"","page":119},{"gurmukhi":"ਪਰੇ ਹੈ ਪਵਿਤ੍ਰ ਹੈ ਪੁਨੀਤ ਹੈ ਪੁਰਾਨ ਹੈ।","roman":"Pare hai pavitr hai puneet hai puraan hai |","meaning_en":"","page":119},{"gurmukhi":"ਅਗੰਜ ਹੈ ਅਭੰਜ ਹੈ ਕਰੀਮ ਹੈ ਕੁਰਾਨ ਹੈ। ੧੧। ੧੭੧।","roman":"Aganj hai abhanj hai kareem hai kuraan hai | 11 | 171 |","meaning_en":"","page":119}]},{"type":"verse","number":[12,172],"number_text":"੧੨। ੧੭੨।","page":119,"lines":[{"gurmukhi":"ਅਕਾਲ ਹੈ ਅਪਾਲ ਹੈ ਖਿਆਲ ਹੈ ਅਖੰਡ ਹੈ।","roman":"Akaal hai apaal hai khiaal hai akhand hai |","meaning_en":"","page":119},{"gurmukhi":"ਨ ਰੋਗ ਹੈ ਨ ਸੋਗ ਹੈ ਨ ਭੇਦ ਹੈ ਨ ਭੰਡ ਹੈ।","roman":"Na rog hai na sog hai na bhed hai na bhand hai |","meaning_en":"","page":119},{"gurmukhi":"ਨ ਅੰਗ ਹੈ ਨ ਰੰਗ ਹੈ ਨ ਸੰਗ ਹੈ ਨ ਸਾਥ ਹੈ।","roman":"Na ang hai na rang hai na sang hai na saath hai |","meaning_en":"","page":119},{"gurmukhi":"ਪ੍ਰਿਯਾ ਹੈ ਪਵਿਤ੍ਰ ਹੈ ਪੁਨੀਤ ਹੈ ਪ੍ਰਮਾਥ ਹੈ। ੧੨। ੧੭੨।","roman":"Priyaa hai pavitr hai puneet hai pramaath hai | 12 | 172 |","meaning_en":"","page":119}]},{"type":"verse","number":[13,173],"number_text":"੧੩। ੧੭੩।","page":119,"lines":[{"gurmukhi":"ਨ ਸੀਤ ਹੈ ਨ ਸੋਕ ਹੈ ਨ ਘ੍ਰਾਮ ਹੈ ਨ ਘਾਮ ਹੈ।","roman":"Na seet hai na sok hai na ghraam hai na ghaam hai |","meaning_en":"","page":119},{"gurmukhi":"ਨ ਲੋਭ ਹੈ ਨ ਮੋਹ ਹੈ ਨ ਕ੍ਰੋਧ ਹੈ ਨ ਕਾਮ ਹੈ।","roman":"Na lobh hai na moh hai na krodh hai na kaam hai |","meaning_en":"","page":119},{"gurmukhi":"ਨ ਦੇਵ ਹੈ ਨ ਦੈਤ ਹੈ ਨ ਨਰ ਕੋ ਸਰੂਪ ਹੈ।","roman":"Na dev hai na dait hai na nar ko saroop hai |","meaning_en":"","page":119},{"gurmukhi":"ਨ ਛਲ ਹੈ ਨ ਛਿਦ੍ਰ ਹੈ ਨ ਛਿਦ੍ਰ ਕੀ ਬਿਭੂਤ ਹੈ। ੧੩। ੧੭੩।","roman":"Na chhal hai na chhidr hai na chhidr kee bibhoot hai | 13 | 173 |","meaning_en":"","page":119}]},{"type":"verse","number":[14,174],"number_text":"੧੪। ੧੭੪।","page":119,"lines":[{"gurmukhi":"ਨ ਕਾਮ ਹੈ ਨ ਕ੍ਰੋਧ ਹੈ ਨ ਲੋਭ ਹੈ ਨ ਮੋਹ ਹੈ।","roman":"Na kaam hai na krodh hai na lobh hai na moh hai |","meaning_en":"","page":119},{"gurmukhi":"ਨ ਦ੍ਵੈਖ ਹੈ ਨ ਭੇਖ ਹੈ ਨ ਦੁਈ ਹੈ ਨ ਦ੍ਰੋਹ ਹੈ।","roman":"Na dvaikh hai na bhekh hai na duee hai na droh hai |","meaning_en":"","page":119},{"gurmukhi":"ਨ ਕਾਲ ਹੈ ਨ ਬਾਲ ਹੈ ਸਦੀਵ ਦਿਆਲ ਰੂਪ ਹੈ।","roman":"Na kaal hai na baal hai sadeev diaal roop hai |","meaning_en":"","page":119},{"gurmukhi":"ਅਗੰਜ ਹੈ ਅਭੰਜ ਹੈ ਅਭਰਮ ਹੈ ਅਭੂਤ ਹੈ। ੧੪। ੧੭੪।","roman":"Aganj hai abhanj hai abhram hai abhoot hai | 14 | 174 |","meaning_en":"","page":119}]},{"type":"verse","number":[15,175],"number_text":"੧੫। ੧੭੫।","page":119,"lines":[{"gurmukhi":"ਅਛੇਦ ਛੇਦ ਹੈ ਸਦਾ ਅਗੰਜ ਗੰਜ ਗੰਜ ਹੈ।","roman":"Achhed chhed hai sadaa aganj ganj ganj hai |","meaning_en":"","page":119},{"gurmukhi":"ਅਭੂਤ ਭੇਖ ਹੈ ਬਲੀ ਅਰੂਪ ਰਾਗ ਰੰਗ ਹੈ।","roman":"Abhoot bhekh hai balee aroop raag rang hai |","meaning_en":"","page":119},{"gurmukhi":"ਨ ਦ੍ਵੈਖ ਹੈ ਨ ਭੇਖ ਹੈ ਨ ਕਾਮ ਕ੍ਰੋਧ ਕਰਮ ਹੈ।","roman":"Na dvaikh hai na bhekh hai na kaam krodh karam hai |","meaning_en":"","page":119},{"gurmukhi":"ਨ ਜਾਤਿ ਹੈ ਨ ਪਾਤਿ ਹੈ ਨ ਚਿਤ੍ਰ ਚਿਹਨ ਬਰਨ ਹੈ। ੧੫। ੧੭੫।","roman":"Na jaati hai na paati hai na chitr chihan baran hai | 15 | 175 |","meaning_en":"","page":119}]},{"type":"verse","number":[16,176],"number_text":"੧੬। ੧੭੬।","page":120,"lines":[{"gurmukhi":"ਬਿਅੰਤ ਹੈ ਅਨੰਤ ਹੈ ਅਨੰਤ ਤੇਜ ਜਾਨੀਐ।","roman":"Biant hai anant hai anant tej jaaneeai |","meaning_en":"","page":120},{"gurmukhi":"ਅਭੂਮਿ ਅਭਿਜ ਹੈ ਸਦਾ ਅਛਿਜ ਤੇਜ ਮਾਨੀਐ।","roman":"Abhoomi abhij hai sadaa achhij tej maaneeai |","meaning_en":"","page":120},{"gurmukhi":"ਨ ਆਧਿ ਹੈ ਨ ਬਿਆਧਿ ਹੈ ਅਗਾਧ ਰੂਪ ਲੇਖੀਐ।","roman":"Na aadhi hai na biaadhi hai agaadh roop lekheeai |","meaning_en":"","page":120},{"gurmukhi":"ਅਦੋਖ ਹੈ ਅਦਾਗ ਹੈ ਅਛੈ ਪ੍ਰਤਾਪ ਪੇਖੀਐ। ੧੬। ੧੭੬।","roman":"Adokh hai adaag hai achhai prataap pekheeai | 16 | 176 |","meaning_en":"","page":120}]},{"type":"verse","number":[17,177],"number_text":"੧੭। ੧੭੭।","page":120,"lines":[{"gurmukhi":"ਨ ਕਰਮ ਹੈ ਨ ਭਰਮ ਹੈ ਨ ਧਰਮ ਕੋ ਪ੍ਰਭਾਉ ਹੈ।","roman":"Na karam hai na bharam hai na dharam ko prabhaau hai |","meaning_en":"","page":120},{"gurmukhi":"ਨ ਜੰਤ੍ਰ ਹੈ ਨ ਤੰਤ੍ਰ ਹੈ ਨ ਮੰਤ੍ਰ ਕੋ ਰਲਾਉ ਹੈ।","roman":"Na jantr hai na tantr hai na mantr ko ralaau hai |","meaning_en":"","page":120},{"gurmukhi":"ਨ ਛਲ ਹੈ ਨ ਛਿਦ੍ਰ ਹੈ ਨ ਛਿਦ੍ਰ ਕੇ ਸਰੂਪ ਹੈ।","roman":"Na chhal hai na chhidr hai na chhidr ke saroop hai |","meaning_en":"","page":120},{"gurmukhi":"ਅਭੰਗ ਹੈ ਅਨੰਗ ਹੈ ਅਗੰਜ ਸੀ ਬਿਭੂਤਿ ਹੈ। ੧੭। ੧੭੭।","roman":"Abhang hai anang hai aganj see bibhooti hai | 17 | 177 |","meaning_en":"","page":120}]},{"type":"verse","number":[18,178],"number_text":"੧੮।੧੭੮।","page":120,"lines":[{"gurmukhi":"ਨ ਕਾਮ ਹੈ ਨ ਕ੍ਰੋਧ ਹੈ ਨ ਲੋਭ ਮੋਹ ਕਾਰ ਹੈ।","roman":"Na kaam hai na krodh hai na lobh moh kaar hai |","meaning_en":"","page":120},{"gurmukhi":"ਨ ਆਧਿ ਹੈ ਨ ਗਾਧ ਹੈ ਨ ਬਿਆਧ ਕੋ ਬਿਚਾਰ ਹੈ।","roman":"Na aadhi hai na gaadh hai na biaadh ko bichaar hai |","meaning_en":"","page":120},{"gurmukhi":"ਨ ਰਾਗ ਰੰਗ ਰੂਪ ਹੈ ਨ ਰੂਪ ਰੇਖ ਰਾਰ ਹੈ।","roman":"Na raag rang roop hai na roop rekh raar hai |","meaning_en":"","page":120},{"gurmukhi":"ਨ ਹਾਉ ਹੈ ਨ ਭਾਉ ਹੈ ਨ ਦਾਉ ਕੋ ਪ੍ਰਕਾਰ ਹੈ। ੧੮।੧੭੮।","roman":"Na haau hai na bhaau hai na daau ko prakaar hai | 18 | 178 |","meaning_en":"","page":120}]},{"type":"verse","number":[19,179],"number_text":"੧੯। ੧੭੯।","page":120,"lines":[{"gurmukhi":"ਗਜਾਧਪੀ ਨਰਾਧਪੀ ਕਰੰਤ ਸੇਵ ਹੈ ਸਦਾ।","roman":"Gajaadhpee naraadhpee karant sev hai sadaa |","meaning_en":"","page":120},{"gurmukhi":"ਸਿਤਸਪਤੀ ਤਪਸਪਤੀ ਬਨਸਪਤੀ ਜਪਸ ਸਦਾ।","roman":"Sitsaptee tapsaptee bansaptee japas sadaa |","meaning_en":"","page":120},{"gurmukhi":"ਅਗਸਤ ਆਦਿ ਜੇ ਬੜੇ ਤਪਸਪਤੀ ਬਿਸੇਖੀਐ।","roman":"Agsat aadi je bare tapsaptee bisekheeai |","meaning_en":"","page":120},{"gurmukhi":"ਬਿਅੰਤ ਬਿਅੰਤ ਬਿਅੰਤ ਕੋ ਕਰੰਤ ਪਾਠ ਪੇਖੀਐ। ੧੯। ੧੭੯।","roman":"Biant biant biant ko karant paath pekheeai | 19 | 179 |","meaning_en":"","page":120}]},{"type":"verse","number":[20,180],"number_text":"੨੦। ੧੮੦।","page":120,"lines":[{"gurmukhi":"ਅਗਾਧ ਆਦਿ ਦੇਵ ਕੀ ਅਨਾਦਿ ਬਾਤ ਮਾਨੀਐ।","roman":"Agaadh aadi dev kee anaadi baat maaneeai |","meaning_en":"","page":120},{"gurmukhi":"ਨ ਜਾਤਿ ਪਾਤਿ ਮੰਤ੍ਰਿ ਮਿਤ੍ਰ ਸਤ੍ਰ ਸਨੇਹ ਜਾਨੀਐ।","roman":"Na jaati paati mantri mitr satr saneh jaaneeai |","meaning_en":"","page":120},{"gurmukhi":"ਸਦੀਵ ਸਰਬ ਲੋਕ ਕੋ ਕ੍ਰਿਪਾਲ ਖਿਆਲ ਮੈ ਰਹੈ।","roman":"Sadeev sarab lok ko kripaal khiaal mai rahai |","meaning_en":"","page":120},{"gurmukhi":"ਤੁਰੰਤ ਦ੍ਰੋਹ ਦੇਹ ਕੇ ਅਨੰਤ ਭਾਤਿ ਸੋ ਦਹੈ। ੨੦। ੧੮੦।","roman":"Turant droh deh ke anant bhaati so dahai | 20 | 180 |","meaning_en":"","page":120}]},{"type":"heading","kind":"chhand","name":"ਰੂਆਮਲ ਛੰਦ","gurmukhi":"ਤ੍ਵਪ੍ਰਸਾਦਿ। ਰੂਆਮਲ ਛੰਦ","roman":"Tvaprasaadi | rooaamal chhand","meaning_en":"","page":120,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[1,181],"number_text":"੧। ੧੮੧।","page":120,"lines":[{"gurmukhi":"ਰੂਪ ਰਾਗ ਨ ਰੇਖ ਰੰਗ ਨ ਜਨਮ ਮਰਨ ਬਿਹੀਨ।","roman":"Roop raag na rekh rang na janam maran biheen |","meaning_en":"","page":120},{"gurmukhi":"ਆਦਿ ਨਾਥ ਅਗਾਧ ਪੁਰਖ ਸੁ ਧਰਮ ਕਰਮ ਪ੍ਰਬੀਨ।","roman":"Aadi naath agaadh purakh su dharam karam prabeen |","meaning_en":"","page":120},{"gurmukhi":"ਜੰਤ੍ਰ ਮੰਤ੍ਰ ਨ ਤੰਤ੍ਰ ਜਾ ਕੋ ਆਦਿ ਪੁਰੁਖ ਅਪਾਰ।","roman":"Jantr mantr na tantr jaa ko aadi purukh apaar |","meaning_en":"","page":120},{"gurmukhi":"ਹਸਤਿ ਕੀਟ ਬਿਖੈ ਬਸੈ ਸਬ ਠਉਰ ਮੈ ਨਿਰਧਾਰ। ੧। ੧੮੧।","roman":"Hasti keet bikhai basai sab thaur mai nirdhaar | 1 | 181 |","meaning_en":"","page":120}]},{"type":"verse","number":[2,182],"number_text":"੨। ੧੮੨।","page":120,"lines":[{"gurmukhi":"ਜਾਤਿ ਪਾਤਿ ਨ ਤਾਤ ਜਾ ਕੋ ਮੰਤ੍ਰ ਮਾਤ ਨ ਮਿਤ੍ਰ।","roman":"Jaati paati na taat jaa ko mantr maat na mitr |","meaning_en":"","page":120},{"gurmukhi":"ਸਰਬ ਠਉਰ ਬਿਖੈ ਰਮਿਓ ਜਿਹ ਚਕ੍ਰ ਚਿਹਨ ਨ ਚਿਤ੍ਰ।","roman":"Sarab thaur bikhai ramio jih chakr chihan na chitr |","meaning_en":"","page":120},{"gurmukhi":"ਆਦਿ ਦੇਵ ਉਦਾਰ ਮੂਰਤਿ ਅਗਾਧ ਨਾਥ ਅਨੰਤ।","roman":"Aadi dev udaar moorti agaadh naath anant |","meaning_en":"","page":120},{"gurmukhi":"ਆਦਿ ਅੰਤਿ ਨ ਜਾਨੀਐ ਅਬਿਖਾਦ ਦੇਵ ਦੁਰੰਤ। ੨। ੧੮੨।","roman":"Aadi anti na jaaneeai abikhaad dev durant | 2 | 182 |","meaning_en":"","page":120}]},{"type":"verse","number":[3,183],"number_text":"੩। ੧੮੩।","page":121,"lines":[{"gurmukhi":"ਦੇਵ ਭੇਵ ਨ ਜਾਨਹੀ ਜਿਸ ਮਰਮ ਬੇਦ ਕਤੇਬ।","roman":"Dev bhev na jaanhee jis maram bed kateb |","meaning_en":"","page":121},{"gurmukhi":"ਸਨਕ ਅਉ ਸਨਕੇਸੁ ਨੰਦਨ ਪਾਵਹੀ ਨ ਹਸੇਬ।","roman":"Sanak au sankesu nandan paavhee na haseb |","meaning_en":"","page":121},{"gurmukhi":"ਜਛ ਕਿੰਨਰ ਮਛ ਮਾਨਸ ਮੁਰਗ ਉਰਗ ਅਪਾਰ।","roman":"Jachh kinnar machh maanas murag urag apaar |","meaning_en":"","page":121},{"gurmukhi":"ਨੇਤਿ ਨੇਤਿ ਪੁਕਾਰਹੀ ਸਿਵ ਸਕ੍ਰ ਔ ਮੁਖਚਾਰ। ੩। ੧੮੩।","roman":"Neti neti pukaarhee siv sakr au mukhchaar | 3 | 183 |","meaning_en":"","page":121}]},{"type":"verse","number":[4,184],"number_text":"੪।੧੮੪।","page":121,"lines":[{"gurmukhi":"ਸਰਬ ਸਪਤ ਪਤਾਰ ਕੇ ਤਰਿ ਜਾਪਹੀ ਜਿਹ ਜਾਪ।","roman":"Sarab sapat pataar ke tari jaaphee jih jaap |","meaning_en":"","page":121},{"gurmukhi":"ਆਦਿ ਦੇਵ ਅਗਾਧਿ ਤੇਜ ਅਨਾਦਿ ਮੂਰਤਿ ਅਤਾਪ।","roman":"Aadi dev agaadhi tej anaadi moorti ataap |","meaning_en":"","page":121},{"gurmukhi":"ਜੰਤ੍ਰ ਮੰਤ੍ਰ ਨ ਆਵਈ ਕਰਿ ਤੰਤ੍ਰ ਮੰਤ੍ਰ ਨ ਕੀਨ।","roman":"Jantr mantr na aavaee kari tantr mantr na keen |","meaning_en":"","page":121},{"gurmukhi":"ਸਰਬ ਠਉਰ ਰਹਿਓ ਬਿਰਾਜ ਧਿਰਾਜ ਰਾਜ ਪ੍ਰਬੀਨ। ੪।੧੮੪।","roman":"Sarab thaur rahio biraaj dhiraaj raaj prabeen | 4 | 184 |","meaning_en":"","page":121}]},{"type":"verse","number":[5,185],"number_text":"੫। ੧੮੫।","page":121,"lines":[{"gurmukhi":"ਜਛ ਗੰਧ੍ਰਬ ਦੇਵ ਦਾਨੋ ਨ ਬ੍ਰਹਮ ਛਤ੍ਰੀਅਨ ਮਾਹਿ।","roman":"Jachh gandhrab dev daano na braham chhatreean maahi |","meaning_en":"","page":121},{"gurmukhi":"ਬੈਸਨੰ ਕੇ ਬਿਖੈ ਬਿਰਾਜੈ ਸੂਦ੍ਰ ਭੀ ਵਹ ਨਾਹਿ।","roman":"Baisnan ke bikhai biraajai soodr bhee vah naahi |","meaning_en":"","page":121},{"gurmukhi":"ਗੂੜ ਗਉਡ ਨ ਭੀਲ ਭੀ ਕਰ ਬ੍ਰਹਮ ਸੇਖ ਸਰੂਪ।","roman":"Goor gaud na bheel bhee kar braham sekh saroop |","meaning_en":"","page":121},{"gurmukhi":"ਰਾਤਿ ਦਿਵਸ ਨ ਮਧ ਉਰਧ ਨ ਭੂਮਿ ਅਕਾਸ ਅਨੂਪ। ੫। ੧੮੫।","roman":"Raati divas na madh uradh na bhoomi akaas anoop | 5 | 185 |","meaning_en":"","page":121}]},{"type":"verse","number":[6,186],"number_text":"੬। ੧੮੬।","page":121,"lines":[{"gurmukhi":"ਜਾਤਿ ਜਨਮ ਨ ਕਾਲ ਕਰਮ ਨ ਧਰਮ ਕਰਮ ਬਿਹੀਨ।","roman":"Jaati janam na kaal karam na dharam karam biheen |","meaning_en":"","page":121},{"gurmukhi":"ਤੀਰਥ ਜਾਤ੍ਰ ਨ ਦੇਵ ਪੂਜਾ ਗੋਰ ਕੇ ਨ ਅਧੀਨ।","roman":"Teerath jaatr na dev poojaa gor ke na adheen |","meaning_en":"","page":121},{"gurmukhi":"ਸਰਬ ਸਪਤ ਪਤਾਰ ਕੇ ਤਰਿ ਜਾਨੀਐ ਜਿਹ ਜੋਤਿ।","roman":"Sarab sapat pataar ke tari jaaneeai jih joti |","meaning_en":"","page":121},{"gurmukhi":"ਸੇਸ ਨਾਮ ਸਹੰਸਫਨਿ ਨਹਿ ਨੇਤ ਪੂਰਨ ਹੋਤ। ੬। ੧੮੬।","roman":"Ses naam sahansaphni nahi net pooran hot | 6 | 186 |","meaning_en":"","page":121}]},{"type":"verse","number":[7,187],"number_text":"੭। ੧੮੭।","page":121,"lines":[{"gurmukhi":"ਸੋਧਿ ਸੋਧਿ ਹਟੇ ਸਭੈ ਸੁਰ ਬਿਰੋਧ ਦਾਨਵ ਸਰਬ।","roman":"Sodhi sodhi hate sabhai sur birodh daanav sarab |","meaning_en":"","page":121},{"gurmukhi":"ਗਾਇ ਗਾਇ ਹਟੇ ਗੰਧ੍ਰਬ ਗਵਾਇ ਕਿੰਨਰ ਗਰਬ।","roman":"Gaai gaai hate gandhrab gavaai kinnar garab |","meaning_en":"","page":121},{"gurmukhi":"ਪੜਤ ਪੜਤ ਥਕੇ ਮਹਾ ਕਬਿ ਗੜਤ ਗਾੜ ਅਨੰਤ।","roman":"Parat parat thake mahaa kabi garat gaar anant |","meaning_en":"","page":121},{"gurmukhi":"ਹਾਰ ਹਾਰ ਕਹਿਓ ਸਭੂ ਮਿਲਿ ਨਾਮ ਨਾਮ ਦੁਰੰਤ। ੭। ੧੮੭।","roman":"Haar haar kahio sabhoo mili naam naam durant | 7 | 187 |","meaning_en":"","page":121}]},{"type":"verse","number":[8,188],"number_text":"੮।੧੮੮।","page":121,"lines":[{"gurmukhi":"ਬੇਦ ਭੇਦ ਨ ਪਾਇਓ ਲਖਿਓਨ ਸੇਬ ਕਤੇਬ।","roman":"Bed bhed na paaio lakhion seb kateb |","meaning_en":"","page":121},{"gurmukhi":"ਦੇਵ ਦਾਨੋ ਮੂੜ ਮਾਨੋ ਜਛ ਨ ਜਾਨੈ ਜੇਬ।","roman":"Dev daano moor maano jachh na jaanai jeb |","meaning_en":"","page":121},{"gurmukhi":"ਭੂਤ ਭਬ ਭਵਾਨ ਭੂਪਤਿ ਆਦਿ ਨਾਥ ਅਨਾਥ।","roman":"Bhoot bhab bhavaan bhoopti aadi naath anaath |","meaning_en":"","page":121},{"gurmukhi":"ਅਗਨਿ ਬਾਇ ਜਲੇ ਥਲੇ ਮਹਿ ਸਰਬ ਠਉਰ ਨਿਵਾਸ।੮।੧੮੮।","roman":"Agni baai jale thale mahi sarab thaur nivaas | 8 | 188 |","meaning_en":"","page":121}]},{"type":"verse","number":[9,189],"number_text":"੯। ੧੮੯।","page":121,"lines":[{"gurmukhi":"ਦੇਹ ਗੇਹ ਨ ਨੇਹ ਸਨੇਹਿ ਅਬੇਹ ਨਾਕ ਅਜੀਤ।","roman":"Deh geh na neh sanehi abeh naak ajeet |","meaning_en":"","page":121},{"gurmukhi":"ਸਰਬ ਗੰਜਨ ਸਰਬ ਭੰਜਨ ਸਰਬ ਤੇ ਅਨਭੀਤ।","roman":"Sarab ganjan sarab bhanjan sarab te anbheet |","meaning_en":"","page":121},{"gurmukhi":"ਸਰਬ ਕਰਤਾ ਸਰਬ ਹਰਤਾ ਸਰਬ ਦਯਾਲ ਅਦ੍ਵੈਖ।","roman":"Sarab kartaa sarab hartaa sarab dayaal advaikh |","meaning_en":"","page":121},{"gurmukhi":"ਚਕ੍ਰ ਚਿਹਨ ਨ ਬਰਨ ਜਾ ਕੋ ਜਾਤਿ ਪਾਤਿ ਨ ਭੇਖ। ੯। ੧੮੯।","roman":"Chakr chihan na baran jaa ko jaati paati na bhekh | 9 | 189 |","meaning_en":"","page":121}]},{"type":"verse","number":[10,190],"number_text":"੧੦। ੧੯੦।","page":122,"lines":[{"gurmukhi":"ਰੂਪ ਰੇਖ ਨ ਰੰਗ ਜਾ ਕੋ ਰਾਗ ਰੂਪ ਨ ਰੰਗ।","roman":"Roop rekh na rang jaa ko raag roop na rang |","meaning_en":"","page":122},{"gurmukhi":"ਸਰਬ ਲਾਇਕ ਸਰਬ ਘਾਇਕ ਸਰਬ ਤੇ ਅਨਭੰਗ।","roman":"Sarab laaik sarab ghaaik sarab te anbhang |","meaning_en":"","page":122},{"gurmukhi":"ਸਰਬ ਦਾਤਾ ਸਰਬ ਗਿਆਤਾ ਸਰਬ ਕੋ ਪ੍ਰਤਿਪਾਲ।","roman":"Sarab daataa sarab giaataa sarab ko pratipaal |","meaning_en":"","page":122},{"gurmukhi":"ਦੀਨਬੰਧੁ ਦਯਾਲ ਸੁਆਮੀ ਆਦਿ ਦੇਵ ਅਪਾਲ। ੧੦। ੧੯੦।","roman":"Deenbandhu dayaal suaamee aadi dev apaal | 10 | 190 |","meaning_en":"","page":122}]},{"type":"verse","number":[11,191],"number_text":"੧੧। ੧੯੧।","page":122,"lines":[{"gurmukhi":"ਦੀਨਬੰਧੁ ਪ੍ਰਬੀਨ ਸ੍ਰੀਪਤਿ ਸਰਬ ਕੋ ਕਰਤਾਰ।","roman":"Deenbandhu prabeen sreepti sarab ko kartaar |","meaning_en":"","page":122},{"gurmukhi":"ਬਰਨ ਚਿਹਨ ਨ ਚਕ੍ਰ ਜਾਕੋ ਚਕ੍ਰ ਚਿਹਨ ਅਕਾਰ।","roman":"Baran chihan na chakr jaako chakr chihan akaar |","meaning_en":"","page":122},{"gurmukhi":"ਜਾਤਿ ਪਾਤਿ ਨ ਗੋਤ੍ਰ ਗਾਥਾ ਰੂਪ ਰੇਖ ਨ ਬਰਨ।","roman":"Jaati paati na gotr gaathaa roop rekh na baran |","meaning_en":"","page":122},{"gurmukhi":"ਸਰਬ ਦਾਤਾ ਸਰਬ ਗ੍ਯਾਤਾ ਸਰਬ ਭੂਅ ਕੋ ਭਰਨ। ੧੧। ੧੯੧।","roman":"Sarab daataa sarab gyaataa sarab bhooa ko bharan | 11 | 191 |","meaning_en":"","page":122}]},{"type":"verse","number":[12,192],"number_text":"੧੨। ੧੯੨।","page":122,"lines":[{"gurmukhi":"ਦੁਸਟ ਗੰਜਨ ਸਤ੍ਰ ਭੰਜਨ ਪਰਮ ਪੁਰੁਖ ਪ੍ਰਮਾਥ।","roman":"Dusat ganjan satr bhanjan param purukh pramaath |","meaning_en":"","page":122},{"gurmukhi":"ਦੁਸਟ ਹਰਤਾ ਸ੍ਰਿਸਟ ਕਰਤਾ ਜਗਤ ਮੈ ਜਿਹ ਗਾਥ।","roman":"Dusat hartaa srisat kartaa jagat mai jih gaath |","meaning_en":"","page":122},{"gurmukhi":"ਭੂਤ ਭਬ ਭਵਿਖ ਭਵਾਨ ਪ੍ਰਮਾਨ ਦੇਵ ਅਗੰਜ।","roman":"Bhoot bhab bhavikh bhavaan pramaan dev aganj |","meaning_en":"","page":122},{"gurmukhi":"ਆਦਿ ਅੰਤ ਅਨਾਦਿ ਸ੍ਰੀਪਤਿ ਪਰਮ ਪੁਰੁਖ ਅਭੰਜ। ੧੨। ੧੯੨।","roman":"Aadi ant anaadi sreepti param purukh abhanj | 12 | 192 |","meaning_en":"","page":122}]},{"type":"verse","number":[13,193],"number_text":"੧੩। ੧੯੩।","page":122,"lines":[{"gurmukhi":"ਧਰਮ ਕੇ ਅਨ ਕ੍ਰਮ ਜੇਤਕ ਕੀਨ ਤਉਨ ਪਸਾਰ।","roman":"Dharam ke an kram jetak keen taun pasaar |","meaning_en":"","page":122},{"gurmukhi":"ਦੇਵ ਅਦੇਵ ਗੰਧਰਬ ਕਿੰਨਰ ਮਛ ਕਛ ਅਪਾਰ।","roman":"Dev adev gandhrab kinnar machh kachh apaar |","meaning_en":"","page":122},{"gurmukhi":"ਭੂਮਿ ਅਕਾਸ ਜਲੇ ਥਲੇ ਮਹਿ ਮਾਨੀਐ ਜਿਹ ਨਾਮੁ।","roman":"Bhoomi akaas jale thale mahi maaneeai jih naamu |","meaning_en":"","page":122},{"gurmukhi":"ਦੁਸਟ ਹਰਤਾ ਪੁਸਟ ਕਰਤਾ ਸ੍ਰਿਸਟਿ ਹਰਤਾ ਕਾਮ। ੧੩। ੧੯੩।","roman":"Dusat hartaa pusat kartaa sristi hartaa kaam | 13 | 193 |","meaning_en":"","page":122}]},{"type":"verse","number":[14,194],"number_text":"੧੪। ੧੯੪।","page":122,"lines":[{"gurmukhi":"ਦੁਸਟ ਹਰਨਾ ਸ੍ਰਿਸਟ ਕਰਨਾ ਦਯਾਲ ਲਾਲ ਗੋਬਿੰਦ।","roman":"Dusat harnaa srisat karnaa dayaal laal gobind |","meaning_en":"","page":122},{"gurmukhi":"ਮਿਤ੍ਰ ਪਾਲਕ ਸਤ੍ਰ ਘਾਲਕ ਦੀਨ ਦਯਾਲ ਮੁਕੰਦ।","roman":"Mitr paalak satr ghaalak deen dayaal mukand |","meaning_en":"","page":122},{"gurmukhi":"ਅਘਉ ਡੰਡਣ ਦੁਸਟ ਖੰਡਣ ਕਾਲ ਹੂੰ ਕੇ ਕਾਲ।","roman":"Aghau dandan dusat khandan kaal hoon ke kaal |","meaning_en":"","page":122},{"gurmukhi":"ਦੁਸਟ ਹਰਣੰ ਪੁਸਟ ਕਰਣੰ ਸਰਬ ਕੇ ਪ੍ਰਤਿਪਾਲ। ੧੪। ੧੯੪।","roman":"Dusat harnan pusat karnan sarab ke pratipaal | 14 | 194 |","meaning_en":"","page":122}]},{"type":"verse","number":[15,195],"number_text":"੧੫। ੧੯੫।","page":122,"lines":[{"gurmukhi":"ਸਰਬ ਕਰਤਾ ਸਰਬ ਹਰਤਾ ਸਰਬ ਕੇ ਅਨਕਾਮ।","roman":"Sarab kartaa sarab hartaa sarab ke ankaam |","meaning_en":"","page":122},{"gurmukhi":"ਸਰਬ ਖੰਡਣ ਸਰਬ ਦੰਡਣ ਸਰਬ ਕੇ ਨਿਜ ਭਾਮ।","roman":"Sarab khandan sarab dandan sarab ke nij bhaam |","meaning_en":"","page":122},{"gurmukhi":"ਸਰਬ ਭੁਗਤਾ ਸਰਬ ਜੁਗਤਾ ਸਰਬ ਕਰਮ ਪ੍ਰਬੀਨ।","roman":"Sarab bhugtaa sarab jugtaa sarab karam prabeen |","meaning_en":"","page":122},{"gurmukhi":"ਸਰਬ ਖੰਡਣ ਸਰਬ ਦੰਡਣ ਸਰਬ ਕਰਮ ਅਧੀਨ। ੧੫। ੧੯੫।","roman":"Sarab khandan sarab dandan sarab karam adheen | 15 | 195 |","meaning_en":"","page":122}]},{"type":"verse","number":[16,196],"number_text":"੧੬। ੧੯੬।","page":122,"lines":[{"gurmukhi":"ਸਰਬ ਸਿੰਮ੍ਰਿਤਨ ਸਰਬ ਸਾਸਤ੍ਰਨ ਸਰਬ ਬੇਦ ਬਿਚਾਰ।","roman":"Sarab sinmritan sarab saastran sarab bed bichaar |","meaning_en":"","page":122},{"gurmukhi":"ਦੁਸਟ ਹਰਤਾ ਬਿਸ੍ਵ ਭਰਤਾ ਆਦਿ ਰੂਪ ਅਪਾਰ।","roman":"Dusat hartaa bisv bhartaa aadi roop apaar |","meaning_en":"","page":122},{"gurmukhi":"ਦੁਸਟ ਦੰਡਣ ਪੁਸਟ ਖੰਡਣ ਆਦਿ ਦੇਵ ਅਖੰਡ।","roman":"Dusat dandan pusat khandan aadi dev akhand |","meaning_en":"","page":122},{"gurmukhi":"ਭੂਮਿ ਅਕਾਸ ਜਲੇ ਥਲੇ ਮਹਿ ਜਪਤ ਜਾਪ ਅਮੰਡ। ੧੬। ੧੯੬।","roman":"Bhoomi akaas jale thale mahi japat jaap amand | 16 | 196 |","meaning_en":"","page":122}]},{"type":"verse","number":[17,197],"number_text":"੧੭। ੧੯੭।","page":123,"lines":[{"gurmukhi":"ਸ੍ਰਿਸਟਚਾਰ ਬਿਚਾਰ ਜੇਤੇ ਜਾਨੀਐ ਸਬਿਚਾਰ।","roman":"Srisatchaar bichaar jete jaaneeai sabichaar |","meaning_en":"","page":123},{"gurmukhi":"ਆਦਿ ਦੇਵ ਅਪਾਰ ਸ੍ਰੀ ਪਤਿ ਦੁਸਟ ਪੁਸਟ ਪ੍ਰਹਾਰ।","roman":"Aadi dev apaar sree pati dusat pusat prahaar |","meaning_en":"","page":123},{"gurmukhi":"ਅੰਨ ਦਾਤਾ ਗ੍ਯਾਨ ਗਿਆਤਾ ਸ੍ਰਬ ਮਾਨ ਮਹਿੰਦ੍ਰ।","roman":"Ann daataa gyaan giaataa srab maan mahindr |","meaning_en":"","page":123},{"gurmukhi":"ਬੇਦ ਬਿਆਸ ਕਰੇ ਕਈ ਦਿਨ ਕੋਟਿ ਇੰਦ੍ਰ ਉਪਿੰਦ੍ਰ। ੧੭। ੧੯੭।","roman":"Bed biaas kare kaee din koti indr upindr | 17 | 197 |","meaning_en":"","page":123}]},{"type":"verse","number":[18,198],"number_text":"੧੮। ੧੯੮।","page":123,"lines":[{"gurmukhi":"ਜਨਮ ਜਾਤਾ ਕਰਮ ਗ੍ਯਾਤਾ ਧਰਮ ਚਾਰੁ ਬਿਚਾਰ।","roman":"Janam jaataa karam gyaataa dharam chaaru bichaar |","meaning_en":"","page":123},{"gurmukhi":"ਬੇਦ ਭੇਵ ਨ ਪਾਵਈ ਸਿਵ ਰੁਦ੍ਰ ਅਉ ਮੁਖਚਾਰ।","roman":"Bed bhev na paavaee siv rudr au mukhchaar |","meaning_en":"","page":123},{"gurmukhi":"ਕੋਟਿ ਇੰਦ੍ਰ ਉਪਇੰਦ੍ਰ ਬਿਆਸ ਸਨਕ ਸਨਤ ਕੁਮਾਰ।","roman":"Koti indr upaindr biaas sanak sanat kumaar |","meaning_en":"","page":123},{"gurmukhi":"ਗਾਇ ਗਾਇ ਥਕੇ ਸਭੇ ਗੁਨ ਚਕ੍ਰਤ ਭੇ ਮੁਖਚਾਰ। ੧੮। ੧੯੮।","roman":"Gaai gaai thake sabhe gun chakrat bhe mukhchaar | 18 | 198 |","meaning_en":"","page":123}]},{"type":"verse","number":[19,199],"number_text":"੧੯। ੧੯੯।","page":123,"lines":[{"gurmukhi":"ਆਦਿ ਅੰਤਿ ਨ ਮਧ ਜਾ ਕੋ ਭੂਤ ਭਬ ਭਵਾਨ।","roman":"Aadi anti na madh jaa ko bhoot bhab bhavaan |","meaning_en":"","page":123},{"gurmukhi":"ਸਤਿ ਦੁਆਪਰ ਤ੍ਰਿਤੀਆ ਕਲਿਜੁਗ ਚਤ੍ਰ ਕਾਲ ਪ੍ਰਧਾਨ।","roman":"Sati duaapar triteeaa kalijug chatr kaal pradhaan |","meaning_en":"","page":123},{"gurmukhi":"ਧਿਆਇ ਧਿਆਇ ਥਕੇ ਮਹਾ ਮੁਨ ਗਾਇ ਗੰਧ੍ਰਬ ਅਪਾਰ।","roman":"Dhiaai dhiaai thake mahaa mun gaai gandhrab apaar |","meaning_en":"","page":123},{"gurmukhi":"ਹਾਰਿ ਹਾਰਿ ਥਕੇ ਸਭੈ ਨਹੀ ਪਾਈਐ ਤਿਹ ਪਾਰ। ੧੯। ੧੯੯।","roman":"Haari haari thake sabhai nahee paaeeai tih paar | 19 | 199 |","meaning_en":"","page":123}]},{"type":"verse","number":[20,200],"number_text":"੨੦। ੨੦੦।","page":123,"lines":[{"gurmukhi":"ਨਾਰਦ ਆਦਿਕ ਬੇਦ ਬਿਆਸਕ ਮੁਨਿ ਮਹਾਨ ਅਨੰਤ।","roman":"Naarad aadik bed biaasak muni mahaan anant |","meaning_en":"","page":123},{"gurmukhi":"ਧਿਆਇ ਧਿਆਇ ਥਕੇ ਸਭੈ ਕਰਿ ਕੋਟਿ ਕਸਟ ਦੁਰੰਤ।","roman":"Dhiaai dhiaai thake sabhai kari koti kasat durant |","meaning_en":"","page":123},{"gurmukhi":"ਗਾਇ ਗਾਇ ਥਕੇ ਗੰਧ੍ਰਬ ਨਾਰਿ ਅਪਛ੍ਰ ਅਪਾਰ।","roman":"Gaai gaai thake gandhrab naari apachhr apaar |","meaning_en":"","page":123},{"gurmukhi":"ਸੋਧਿ ਸੋਧਿ ਥਕੇ ਮਹਾ ਸੁਰ ਪਾਇਓ ਨਹਿ ਪਾਰ। ੨੦। ੨੦੦।","roman":"Sodhi sodhi thake mahaa sur paaio nahi paar | 20 | 200 |","meaning_en":"","page":123}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਤ੍ਵਪ੍ਰਸਾਦਿ। ਦੋਹਰਾ","roman":"Tvaprasaadi | dohraa","meaning_en":"","page":123,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[1,201],"number_text":"੧। ੨੦੧।","page":123,"lines":[{"gurmukhi":"ਏਕ ਸਮੇ ਸ੍ਰੀ ਆਤਮਾ ਉਚਰਿਓ ਮਤਿ ਸਿਉ ਬੈਨ।","roman":"Ek same sree aatmaa uchrio mati siu bain |","meaning_en":"","page":123},{"gurmukhi":"ਸਭ ਪ੍ਰਤਾਪ ਜਗਦੀਸ ਕੋ ਕਹਹੁ ਸਕਲ ਬਿਧਿ ਤੈਨ। ੧। ੨੦੧।","roman":"Sabh prataap jagdees ko kahhu sakal bidhi tain | 1 | 201 |","meaning_en":"","page":123}]},{"type":"verse","number":[2,202],"number_text":"੨। ੨੦੨।","page":123,"lines":[{"gurmukhi":"ਕੋ ਆਤਮਾ ਸਰੂਪ ਹੈ ਕਹਾ ਸ੍ਰਿਸਟਿ ਕੋ ਬਿਚਾਰ।","roman":"Ko aatmaa saroop hai kahaa sristi ko bichaar |","meaning_en":"","page":123},{"gurmukhi":"ਕਉਨ ਧਰਮ ਕੋ ਕਰਮ ਹੈ ਕਹਹੁ ਸਕਲ ਬਿਸਥਾਰ। ੨। ੨੦੨।","roman":"Kaun dharam ko karam hai kahhu sakal bisthaar | 2 | 202 |","meaning_en":"","page":123}]},{"type":"verse","number":[3,203],"number_text":"੩। ੨੦੩।","page":123,"lines":[{"gurmukhi":"ਕਹਾ ਜੀਤਬ ਕਹਾ ਮਰਨ ਹੈ ਕਵਨ ਸੁਰਗ ਕਹਾ ਨਰਕ।","roman":"Kahaa jeetab kahaa maran hai kavan surag kahaa narak |","meaning_en":"","page":123},{"gurmukhi":"ਕੋ ਸੁਘੜਾ ਕੋ ਮੂੜਤਾ ਕਹਾ ਤਰਕ ਅਵਤਰਕ। ੩। ੨੦੩।","roman":"Ko sughraa ko moortaa kahaa tarak avatrak | 3 | 203 |","meaning_en":"","page":123}]},{"type":"verse","number":[4,204],"number_text":"੪। ੨੦੪।","page":123,"lines":[{"gurmukhi":"ਕੋ ਨਿੰਦਾ ਜਸ ਹੈ ਕਵਨ ਕਵਨ ਪਾਪ ਕਹਾ ਧਰਮ।","roman":"Ko nindaa jas hai kavan kavan paap kahaa dharam |","meaning_en":"","page":123},{"gurmukhi":"ਕਵਨ ਜੋਗ ਕੋ ਭੋਗ ਹੈ ਕਵਨ ਕਰਮ ਅਪਕਰਮ। ੪। ੨੦੪।","roman":"Kavan jog ko bhog hai kavan karam apakram | 4 | 204 |","meaning_en":"","page":123}]},{"type":"verse","number":[5,205],"number_text":"੫। ੨੦੫।","page":123,"lines":[{"gurmukhi":"ਕਹਹੁ ਸੁਸ੍ਰਮ ਕਾ ਸੋ ਕਹਹਿ ਦਮ ਕੋ ਕਹਾ ਕਹੰਤ।","roman":"Kahhu susram kaa so kahhi dam ko kahaa kahant |","meaning_en":"","page":123},{"gurmukhi":"ਕੋ ਸੂਰਾ ਦਾਤਾ ਕਵਨ ਕਹਹੁ ਤੰਤ ਕੋ ਮੰਤ। ੫। ੨੦੫।","roman":"Ko sooraa daataa kavan kahhu tant ko mant | 5 | 205 |","meaning_en":"","page":123}]},{"type":"verse","number":[6,206],"number_text":"੬। ੨੦੬।","page":123,"lines":[{"gurmukhi":"ਕਹਾ ਰੰਕ ਰਾਜਾ ਕਵਨ ਹਰਖ ਸੋਗ ਹੈ ਕਵਨ।","roman":"Kahaa rank raajaa kavan harakh sog hai kavan |","meaning_en":"","page":123},{"gurmukhi":"ਕੋ ਰੋਗੀ ਰਾਗੀ ਕਵਨ ਕਹਹੁ ਤਤੁ ਮੁਹਿ ਤਵਨ। ੬। ੨੦੬।","roman":"Ko rogee raagee kavan kahhu tatu muhi tavan | 6 | 206 |","meaning_en":"","page":123}]},{"type":"verse","number":[7,207],"number_text":"੭। ੨੦੭।","page":124,"lines":[{"gurmukhi":"ਕਵਨ ਰਿਸਟ ਕੋ ਪੁਸਟ ਹੈ ਕਹਾ ਸ੍ਰਿਸਟ ਕੋ ਬਿਚਾਰ।","roman":"Kavan risat ko pusat hai kahaa srisat ko bichaar |","meaning_en":"","page":124},{"gurmukhi":"ਕਵਨ ਧ੍ਰਿਸਟ ਕੋ ਭ੍ਰਿਸਟ ਹੈ ਕਹੋ ਸਕਲ ਬਿਸਥਾਰ। ੭। ੨੦੭।","roman":"Kavan dhrisat ko bhrisat hai kaho sakal bisthaar | 7 | 207 |","meaning_en":"","page":124}]},{"type":"verse","number":[8,208],"number_text":"੮। ੨੦੮।","page":124,"lines":[{"gurmukhi":"ਕਹਾ ਕਰਮ ਕੋ ਕਰਮ ਹੈ ਕਹਾ ਭਰਮ ਕੋ ਨਾਸ।","roman":"Kahaa karam ko karam hai kahaa bharam ko naas |","meaning_en":"","page":124},{"gurmukhi":"ਕਹਾ ਚਿਤਨ ਕੀ ਚੇਸਟਾ ਕਹਾ ਅਚੇਤ ਪ੍ਰਕਾਸ। ੮। ੨੦੮।","roman":"Kahaa chitan kee chestaa kahaa achet prakaas | 8 | 208 |","meaning_en":"","page":124}]},{"type":"verse","number":[9,209],"number_text":"੯। ੨੦੯।","page":124,"lines":[{"gurmukhi":"ਕਹਾ ਨੇਮ ਸੰਜਮ ਕਹਾ ਕਹਾ ਗਿਆਨ ਅਗਿਆਨ।","roman":"Kahaa nem sanjam kahaa kahaa giaan agiaan |","meaning_en":"","page":124},{"gurmukhi":"ਕੋ ਰੋਗੀ ਸੋਗੀ ਕਵਨ ਕਹਾ ਧਰਮ ਕੀ ਹਾਨਿ। ੯। ੨੦੯।","roman":"Ko rogee sogee kavan kahaa dharam kee haani | 9 | 209 |","meaning_en":"","page":124}]},{"type":"verse","number":[10,210],"number_text":"੧੦। ੨੧੦।","page":124,"lines":[{"gurmukhi":"ਕੋ ਸੂਰ ਸੁੰਦਰ ਕਵਨ ਕਹਾ ਜੋਗ ਕੋ ਸਾਰ।","roman":"Ko soor sundar kavan kahaa jog ko saar |","meaning_en":"","page":124},{"gurmukhi":"ਕੋ ਦਾਤਾ ਗਿਆਨੀ ਕਵਨ ਕਹੋ ਬਿਚਾਰ ਬਿਚਾਰਿ। ੧੦। ੨੧੦।","roman":"Ko daataa giaanee kavan kaho bichaar bichaari | 10 | 210 |","meaning_en":"","page":124}]},{"type":"heading","kind":"chhand","name":"ਦੀਘਰ ਤ੍ਰਿਭੰਗੀ ਛੰਦ","gurmukhi":"ਤ੍ਵਪ੍ਰਸਾਦਿ। ਦੀਘਰ ਤ੍ਰਿਭੰਗੀ ਛੰਦ","roman":"Tvaprasaadi | deeghar tribhangee chhand","meaning_en":"","page":124,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[1,211],"number_text":"੧। ੨੧੧।","page":124,"lines":[{"gurmukhi":"ਦੁਰਜਨ ਦਲ ਦੰਡਣ ਅਸੁਰ ਬਿਹੰਡਣ ਦੁਸਟ ਨਿਕੰਦਣ ਆਦਿ ਬ੍ਰਿਤੇ।","roman":"Durjan dal dandan asur bihandan dusat nikandan aadi brite |","meaning_en":"","page":124},{"gurmukhi":"ਚਛਰਾਸੁਰ ਮਾਰਣ ਪਤਿਤ ਉਧਾਰਣ ਨਰਕ ਨਿਵਾਰਣ ਗੂੜ ਗਤੇ।","roman":"Chachhraasur maaran patit udhaaran narak nivaaran goor gate |","meaning_en":"","page":124},{"gurmukhi":"ਅਛੇ ਅਖੰਡੇ ਤੇਜ ਪ੍ਰਚੰਡੇ ਖੰਡ ਉਦੰਡੇ ਅਲਖ ਮਤੇ।","roman":"Achhe akhande tej prachande khand udande alakh mate |","meaning_en":"","page":124},{"gurmukhi":"ਜੈ ਜੈ ਹੋਸੀ ਮਹਿਖਾਸੁਰਿ ਮਰਦਨ ਰੰਮ ਕਪਰਦਨ ਛਤ੍ਰ ਛਿਤੇ। ੧। ੨੧੧।","roman":"Jai jai hosee mahikhaasuri mardan ranm kapardan chhatr chhite | 1 | 211 |","meaning_en":"","page":124}]},{"type":"verse","number":[2,212],"number_text":"੨।੨੧੨।","page":124,"lines":[{"gurmukhi":"ਆਸੁਰੀ ਬਿਹੰਡਣ ਦੁਸਟ ਨਿਕੰਦਣ ਪੁਸਟ ਉਦੰਡਣ ਰੂਪ ਅਤੇ।","roman":"Aasuree bihandan dusat nikandan pusat udandan roop ate |","meaning_en":"","page":124},{"gurmukhi":"ਚੰਡਾਸੁਰ ਚੰਡਣ ਮੁੰਡ ਬਿਹੰਡਣ ਧੂਮ੍ਰ ਬਿਧੁੰਸਣ ਮਹਿਖ ਮਤੇ।","roman":"Chandaasur chandan mund bihandan dhoomr bidhunsan mahikh mate |","meaning_en":"","page":124},{"gurmukhi":"ਦਾਨਵ ਪ੍ਰਹਾਰਨ ਨਰਕ ਨਿਵਾਰਨ ਅਧਮ ਉਧਾਰਨ ਉਰਧ ਅਧੇ।","roman":"Daanav prahaaran narak nivaaran adham udhaaran uradh adhe |","meaning_en":"","page":124},{"gurmukhi":"ਜੈ ਜੈ ਹੋਸੀ ਮਹਿਖਾਸੁਰ ਮਰਦਨ ਰੰਮ ਕਪਰਦਨ ਆਦਿ ਬ੍ਰਿਤੇ।੨।੨੧੨।","roman":"Jai jai hosee mahikhaasur mardan ranm kapardan aadi brite | 2 | 212 |","meaning_en":"","page":124}]},{"type":"verse","number":[3,213],"number_text":"੩। ੨੧੩।","page":124,"lines":[{"gurmukhi":"ਡਾਵਰੂ ਡਵੰਕੈ ਬਬਰ ਬਵੰਕੈ ਭੁਜਾ ਫਰੰਕੈ ਤੇਜ ਬਰੰ।","roman":"Daavroo davankai babar bavankai bhujaa pharankai tej baran |","meaning_en":"","page":124},{"gurmukhi":"ਲੰਕੁੜੀਆ ਫਾਧੈ ਆਯੁਧ ਬਾਧੈ ਸੈਨ ਬਿਮਰਦਨ ਕਾਲ ਅਸੁਰੰ।","roman":"Lankureeaa phaadhai aayudh baadhai sain bimardan kaal asuran |","meaning_en":"","page":124},{"gurmukhi":"ਅਸਟਾਯੁਧ ਚਮਕੈ ਭੂਖਨ ਦਮਕੈ ਅਤਿ ਸਿਤ ਝਮਕੈ ਫੰਕ ਫੰਣੰ।","roman":"Astaayudh chamkai bhookhan damkai ati sit jhamkai phank phannan |","meaning_en":"","page":124},{"gurmukhi":"ਜੈ ਜੈ ਹੋਸੀ ਮਹਿਖਾਸੁਰ ਮਰਦਨ ਰੰਮ ਕਪਰਦਨ ਦੈਤ ਜਿਣੰ। ੩। ੨੧੩।","roman":"Jai jai hosee mahikhaasur mardan ranm kapardan dait jinan | 3 | 213 |","meaning_en":"","page":124}]},{"type":"verse","number":[4,214],"number_text":"੪।੨੧੪।","page":124,"lines":[{"gurmukhi":"ਚੰਡਾਸੁਰ ਚੰਡਣ ਮੁੰਡ ਬਿਮੁੰਡਣ ਖੰਡ ਅਖੰਡਣ ਖੂਨ ਖਿਤੇ।","roman":"Chandaasur chandan mund bimundan khand akhandan khoon khite |","meaning_en":"","page":124},{"gurmukhi":"ਦਾਮਿਨੀ ਦਮੰਕਣ ਧੁਜਾ ਫਰੰਕਣ ਫਣੀ ਫੁੰਕਾਰਣ ਜੋਧ ਜਿਤੇ।","roman":"Daaminee damankan dhujaa pharankan phanee phunkaaran jodh jite |","meaning_en":"","page":124},{"gurmukhi":"ਸਰ ਧਾਰ ਬਿਬਰਖਣ ਦੁਸਟ ਪ੍ਰਕਰਖਣ ਪੁਸਟ ਪ੍ਰਹਰਖਣ ਦੁਸਟ ਮਥੇ।","roman":"Sar dhaar bibarkhan dusat prakarkhan pusat praharkhan dusat mathe |","meaning_en":"","page":124},{"gurmukhi":"ਜੈ ਜੈ ਹੋਸੀ ਮਹਿਖਾਸੁਰ ਮਰਦਨ ਭੂਮਿ ਆਕਾਸ ਤਲ ਉਰਧ ਅਧੇ।੪।੨੧੪।","roman":"Jai jai hosee mahikhaasur mardan bhoomi aakaas tal uradh adhe | 4 | 214 |","meaning_en":"","page":124}]},{"type":"verse","number":[5,215],"number_text":"੫। ੨੧੫।","page":125,"lines":[{"gurmukhi":"ਦਾਮਿਨੀ ਪ੍ਰਹਾਸਨ ਸੁਛਬਿ ਨਿਵਾਸਨ ਸ੍ਰਿਸਟਿ ਪ੍ਰਕਾਸਨ ਗੂੜ ਗਤੇ।","roman":"Daaminee prahaasan suchhbi nivaasan sristi prakaasan goor gate |","meaning_en":"","page":125},{"gurmukhi":"ਰਕਤਾਸੁਰ ਆਚਨ ਜੁਧ ਪ੍ਰਮਾਚਨ ਨ੍ਰਿਦੈ ਨਰਾਚਨ ਧਰਮ ਬ੍ਰਿਤੇ।","roman":"Raktaasur aachan judh pramaachan nridai naraachan dharam brite |","meaning_en":"","page":125},{"gurmukhi":"ਸ੍ਰੋਣੰਤ ਅਚਿੰਤੀ ਅਨਲ ਬਿਵੰਤੀ ਜੋਗ ਜਯੰਤੀ ਖੜਗ ਧਰੇ।","roman":"Sronant achintee anal bivantee jog jayantee kharag dhare |","meaning_en":"","page":125},{"gurmukhi":"ਜੈ ਜੈ ਹੋਸੀ ਮਹਿਖਾਸੁਰ ਮਰਦਨ ਪਾਪ ਬਿਨਾਸਨ ਧਰਮ ਕਰੇ। ੫। ੨੧੫।","roman":"Jai jai hosee mahikhaasur mardan paap binaasan dharam kare | 5 | 215 |","meaning_en":"","page":125}]},{"type":"verse","number":[6,216],"number_text":"੬। ੨੧੬।","page":125,"lines":[{"gurmukhi":"ਅਘ ਓਘ ਨਿਵਾਰਨ ਦੁਸਟ ਪ੍ਰਜਾਰਨ ਸ੍ਰਿਸਟਿ ਉਬਾਰਨ ਸੁਧ ਮਤੇ।","roman":"Agh ogh nivaaran dusat prajaaran sristi ubaaran sudh mate |","meaning_en":"","page":125},{"gurmukhi":"ਫਣੀਅਰ ਫੁੰਕਾਰਨ ਬਾਘ ਬੁਕਾਰਣ ਸਸਤ੍ਰ ਪ੍ਰਹਾਰਣ ਸਾਧ ਮਤੇ।","roman":"Phaneear phunkaaran baagh bukaaran sasatr prahaaran saadh mate |","meaning_en":"","page":125},{"gurmukhi":"ਸੈਹਥੀ ਸਨਾਹਨਿ ਅਸਟ ਪ੍ਰਬਾਹਨ ਬੋਲ ਨਿਬਾਹਨ ਤੇਜ ਅਤੁਲੰ।","roman":"Saihthee sanaahni asat prabaahan bol nibaahan tej atulan |","meaning_en":"","page":125},{"gurmukhi":"ਜੈ ਜੈ ਹੋਸੀ ਮਹਿਖਾਸੁਰ ਮਰਦਨ ਭੂਮਿ ਅਕਾਸ ਪਤਾਲ ਜਲੰ। ੬। ੨੧੬।","roman":"Jai jai hosee mahikhaasur mardan bhoomi akaas pataal jalan | 6 | 216 |","meaning_en":"","page":125}]},{"type":"verse","number":[7,217],"number_text":"੭। ੨੧੭।","page":125,"lines":[{"gurmukhi":"ਚਾਚਰਿ ਚਮਕਾਰਨ ਛਿਛੁਰ ਹਾਰਨ ਧੂਮ ਧੁਕਾਰਨ ਦ੍ਰਪ ਮਥੇ।","roman":"Chaachri chamkaaran chhichhur haaran dhoom dhukaaran drap mathe |","meaning_en":"","page":125},{"gurmukhi":"ਦਾੜਵੀ ਪ੍ਰਦੰਤੇ ਜੋਗ ਜਯੰਤੇ ਮਨੁਜ ਮਥੰਤੇ ਗੂੜ ਕਥੇ।","roman":"Daarvee pradante jog jayante manuj mathante goor kathe |","meaning_en":"","page":125},{"gurmukhi":"ਕਰਮ ਪ੍ਰਣਾਸਨ ਚੰਦ ਪ੍ਰਕਾਸਨ ਸੂਰਜ ਪ੍ਰਤੇਜਨ ਅਸਟਭੁਜੇ।","roman":"Karam pranaasan chand prakaasan sooraj pratejan asatbhuje |","meaning_en":"","page":125},{"gurmukhi":"ਜੈ ਜੈ ਹੋਸੀ ਮਹਿਖਾਸੁਰ ਮਰਦਨ ਭਰਮ ਬਿਨਾਸਨ ਧਰਮ ਧੁਜੇ। ੭। ੨੧੭।","roman":"Jai jai hosee mahikhaasur mardan bharam binaasan dharam dhuje | 7 | 217 |","meaning_en":"","page":125}]},{"type":"verse","number":[8,218],"number_text":"੮। ੨੧੮।","page":125,"lines":[{"gurmukhi":"ਘੁੰਘਰੂ ਘਮੰਕਣ ਸਸਤ੍ਰ ਝਮੰਕਣ ਫਣੀਅਰ ਫੁੰਕਾਰਣ ਧਰਮ ਧੁਜੇ।","roman":"Ghunghroo ghamankan sasatr jhamankan phaneear phunkaaran dharam dhuje |","meaning_en":"","page":125},{"gurmukhi":"ਅਸਟਾਟ ਪ੍ਰਹਾਸਨ ਸ੍ਰਿਸਟਿ ਨਿਵਾਸਨ ਦੁਸਟ ਪ੍ਰਣਾਸਨ ਚਕ੍ਰ ਗਤੇ।","roman":"Astaat prahaasan sristi nivaasan dusat pranaasan chakr gate |","meaning_en":"","page":125},{"gurmukhi":"ਕੇਸਰੀ ਪ੍ਰਵਾਹੇ ਸੁਧ ਸਨਾਹੇ ਅਗਮ ਅਥਾਹੇ ਏਕ ਬ੍ਰਿਤੇ।","roman":"Kesree pravaahe sudh sanaahe agam athaahe ek brite |","meaning_en":"","page":125},{"gurmukhi":"ਜੈ ਜੈ ਹੋਸੀ ਮਹਿਖਾਸੁਰ ਮਰਦਨ ਆਦਿ ਕੁਮਾਰਿ ਅਗਾਧ ਬ੍ਰਿਤੇ। ੮। ੨੧੮।","roman":"Jai jai hosee mahikhaasur mardan aadi kumaari agaadh brite | 8 | 218 |","meaning_en":"","page":125}]},{"type":"verse","number":[9,219],"number_text":"੯। ੨੧੯।","page":125,"lines":[{"gurmukhi":"ਸੁਰ ਨਰ ਮੁਨਿ ਬੰਦਨ ਦੁਸਟ ਨਿਕੰਦਨ ਭ੍ਰਿਸਟ ਬਿਨਾਸਨ ਮ੍ਰਿਤ ਮਥੇ।","roman":"Sur nar muni bandan dusat nikandan bhrisat binaasan mrit mathe |","meaning_en":"","page":125},{"gurmukhi":"ਕਾਵਰੂ ਕੁਮਾਰੇ ਅਧਮ ਉਧਾਰੇ ਨਰਕ ਨਿਵਾਰੇ ਆਦਿ ਕਥੇ।","roman":"Kaavroo kumaare adham udhaare narak nivaare aadi kathe |","meaning_en":"","page":125},{"gurmukhi":"ਕਿੰਕਣੀ ਪ੍ਰਸੋਹਣਿ ਸੁਰ ਨਰ ਮੋਹਣਿ ਸਿੰਘਾਰੋਹਣਿ ਬਿਤਲ ਤਲੇ।","roman":"Kinknee prasohni sur nar mohni singhaarohni bital tale |","meaning_en":"","page":125},{"gurmukhi":"ਜੈ ਜੈ ਹੋਸੀ ਸਭ ਠਉਰਿ ਨਿਵਾਸਨ ਬਾਇ ਪਤਾਲ ਅਕਾਸ ਅਨਲੇ। ੯। ੨੧੯।","roman":"Jai jai hosee sabh thauri nivaasan baai pataal akaas anle | 9 | 219 |","meaning_en":"","page":125}]},{"type":"verse","number":[10,220],"number_text":"੧੦। ੨੨੦।","page":126,"lines":[{"gurmukhi":"ਸੰਕਟੀ ਨਿਵਾਰਣ ਅਧਮ ਉਧਾਰਣ ਤੇਜ ਪ੍ਰਕਰਖਣ ਤੁੰਦ ਤਬੇ।","roman":"Sanktee nivaaran adham udhaaran tej prakarkhan tund tabe |","meaning_en":"","page":126},{"gurmukhi":"ਦੁਖ ਦੋਖ ਦਹੰਤੀ ਜੁਆਲ ਜਯੰਤੀ ਆਦਿ ਅਨਾਦਿ ਅਗਾਧ ਅਛੇ।","roman":"Dukh dokh dahantee juaal jayantee aadi anaadi agaadh achhe |","meaning_en":"","page":126},{"gurmukhi":"ਸੁਧਤਾ ਸਮਰਪਣ ਤਰਕ ਬਿਤਰਕਣ ਤਪਤ ਪ੍ਰਤਾਪਣ ਜਪਤ ਜਿਵੈ।","roman":"Sudhtaa samarpan tarak bitarkan tapat prataapan japat jivai |","meaning_en":"","page":126},{"gurmukhi":"ਜੈ ਜੈ ਹੋਸੀ ਸਸਤ੍ਰ ਪ੍ਰਕਰਖਣ ਆਦਿ ਅਨੀਲ ਅਗਾਧਿ ਅਭੈ। ੧੦। ੨੨੦।","roman":"Jai jai hosee sasatr prakarkhan aadi aneel agaadhi abhai | 10 | 220 |","meaning_en":"","page":126}]},{"type":"verse","number":[11,221],"number_text":"੧੧। ੨੨੧।","page":126,"lines":[{"gurmukhi":"ਚੰਚਲਾ ਚਖੰਗੀ ਅਲਕ ਭੁਜੰਗੀ ਤੁੰਦ ਤੁਰੰਗਣ ਤਿਛ ਸਰੇ।","roman":"Chanchlaa chakhangee alak bhujangee tund turangan tichh sare |","meaning_en":"","page":126},{"gurmukhi":"ਕਰਕਸਾ ਕੁਠਾਰੇ ਨਰਕ ਨਿਵਾਰੇ ਅਧਮ ਉਧਾਰੇ ਤੂਰ ਭਜੇ।","roman":"Karaksaa kuthaare narak nivaare adham udhaare toor bhaje |","meaning_en":"","page":126},{"gurmukhi":"ਦਾਮਿਨੀ ਦਮੰਕੇ ਕੇਹਰਿ ਲੰਕੇ ਆਦਿ ਅਤੰਕੇ ਕ੍ਰੂਰ ਕਥੇ।","roman":"Daaminee damanke kehri lanke aadi atanke kroor kathe |","meaning_en":"","page":126},{"gurmukhi":"ਜੈ ਜੈ ਹੋਸੀ ਰਕਤਾਸੁਰ ਖੰਡਣ ਸੁੰਭ ਚਕ੍ਰਤਨ ਨਿਸੁੰਭ ਮਥੇ। ੧੧। ੨੨੧।","roman":"Jai jai hosee raktaasur khandan sunbh chakratan nisunbh mathe | 11 | 221 |","meaning_en":"","page":126}]},{"type":"verse","number":[12,222],"number_text":"੧੨। ੨੨੨।","page":126,"lines":[{"gurmukhi":"ਬਾਰਿਜ ਬਿਲੋਚਨ ਬ੍ਰਿਤਨ ਬਿਮੋਚਨ ਸੋਚ ਬਿਸੋਚਨ ਕਉਚ ਕਸੇ।","roman":"Baarij bilochan britan bimochan soch bisochan kauch kase |","meaning_en":"","page":126},{"gurmukhi":"ਦਾਮਿਨੀ ਪ੍ਰਹਾਸੇ ਸੁਕ ਸਰ ਨਾਸੇ ਸੁਬ੍ਰਿਤ ਸੁਬਾਸੇ ਦੁਸਟ ਗ੍ਰਸੇ।","roman":"Daaminee prahaase suk sar naase subrit subaase dusat grase |","meaning_en":"","page":126},{"gurmukhi":"ਚੰਚਲਾ ਪ੍ਰਿਅੰਗੀ ਬੇਦ ਪ੍ਰਸੰਗੀ ਤੇਜ ਤੁਰੰਗੀ ਖੰਡ ਅਸੁਰੰ।","roman":"Chanchlaa priangee bed prasangee tej turangee khand asuran |","meaning_en":"","page":126},{"gurmukhi":"ਜੈ ਜੈ ਹੋਸੀ ਮਹਿਖਾਸੁਰ ਮਰਦਨ ਆਦਿ ਅਨਾਦਿ ਅਗਾਧਿ ਉਰਧੰ। ੧੨। ੨੨੨।","roman":"Jai jai hosee mahikhaasur mardan aadi anaadi agaadhi urdhan | 12 | 222 |","meaning_en":"","page":126}]},{"type":"verse","number":[13,223],"number_text":"੧੩। ੨੨੩।","page":126,"lines":[{"gurmukhi":"ਘੰਟਕਾ ਬਿਰਾਜੈ ਰੁਣਝੁਣ ਬਾਜੈ ਭ੍ਰਮ ਭੈ ਭਾਜੈ ਸੁਨਤ ਸੁਰੰ।","roman":"Ghantkaa biraajai runjhun baajai bhram bhai bhaajai sunat suran |","meaning_en":"","page":126},{"gurmukhi":"ਕੋਕਿਲ ਸੁਨਿ ਲਾਜੈ ਕਿਲਬਿਖ ਭਾਜੈ ਸੁਖ ਉਪਰਾਜੈ ਮਧਿ ਉਰੰ।","roman":"Kokil suni laajai kilbikh bhaajai sukh upraajai madhi uran |","meaning_en":"","page":126},{"gurmukhi":"ਦੁਰਜਨ ਦਲ ਦਝੈ ਮਨ ਤਨ ਰਿਝੈ ਸਭੈ ਨ ਭਜੈ ਰੋਹਰਣੰ।","roman":"Durjan dal dajhai man tan rijhai sabhai na bhajai roharnan |","meaning_en":"","page":126},{"gurmukhi":"ਜੈ ਜੈ ਹੋਸੀ ਮਹਿਖਾਸੁਰ ਮਰਦਨ ਚੰਡ ਚਕ੍ਰਤਨ ਆਦਿ ਗੁਰੰ। ੧੩। ੨੨੩।","roman":"Jai jai hosee mahikhaasur mardan chand chakratan aadi guran | 13 | 223 |","meaning_en":"","page":126}]},{"type":"verse","number":[14,224],"number_text":"੧੪। ੨੨੪।","page":126,"lines":[{"gurmukhi":"ਚਾਚਰੀ ਪ੍ਰਜੋਧਨ ਦੁਸਟ ਬਿਰੋਧਨ ਰੋਸ ਅਰੋਧਨ ਕ੍ਰੂਰ ਬ੍ਰਿਤੇ।","roman":"Chaachree prajodhan dusat birodhan ros arodhan kroor brite |","meaning_en":"","page":126},{"gurmukhi":"ਧੂਮ੍ਰਾਛ ਬਿਧੁੰਸਨ ਪ੍ਰਲੈ ਪ੍ਰਜੁੰਸਨ ਜਗਿ ਬਿਧੁੰਸਨ ਸੁਧ ਮਤੇ।","roman":"Dhoomraachh bidhunsan pralai prajunsan jagi bidhunsan sudh mate |","meaning_en":"","page":126},{"gurmukhi":"ਜਾਲਪਾ ਜਯੰਤੀ ਸਤ੍ਰ ਮਥੰਤੀ ਦੁਸਟ ਪ੍ਰਦਾਹਨ ਗਾੜ ਮਤੇ।","roman":"Jaalpaa jayantee satr mathantee dusat pradaahan gaar mate |","meaning_en":"","page":126},{"gurmukhi":"ਜੈ ਜੈ ਹੋਸੀ ਮਹਿਖਾਸੁਰ ਮਰਦਨ ਆਦਿ ਜੁਗਾਦਿ ਅਗਾਧਿ ਗਤੇ। ੧੪। ੨੨੪।","roman":"Jai jai hosee mahikhaasur mardan aadi jugaadi agaadhi gate | 14 | 224 |","meaning_en":"","page":126}]},{"type":"verse","number":[15,225],"number_text":"੧੫। ੨੨੫।","page":126,"lines":[{"gurmukhi":"ਖਤ੍ਰਿਆਣਿ ਖਤੰਗੀ ਅਭੈ ਅਭੰਗੀ ਆਦਿ ਅਨੰਗੀ ਅਗਾਧਿ ਗਤੇ।","roman":"Khatriaani khatangee abhai abhangee aadi anangee agaadhi gate |","meaning_en":"","page":126},{"gurmukhi":"ਬ੍ਰਿੜਲਾਛ ਬਿਹੰਡਣ ਚਛਰ ਦੰਡਣ ਤੇਜ ਪ੍ਰਚੰਡਣ ਆਦਿ ਬ੍ਰਿਤੇ।","roman":"Brirlaachh bihandan chachhar dandan tej prachandan aadi brite |","meaning_en":"","page":126},{"gurmukhi":"ਸੁਰ ਨਰ ਪ੍ਰਤਿਪਾਰਣ ਪਤਿਤ ਉਧਾਰਣ ਦੁਸਟ ਨਿਵਾਰਣ ਦੋਖ ਹਰੇ।","roman":"Sur nar pratipaaran patit udhaaran dusat nivaaran dokh hare |","meaning_en":"","page":126},{"gurmukhi":"ਜੈ ਜੈ ਹੋਸੀ ਮਹਿਖਾਸੁਰ ਮਰਦਨ ਬਿਸ ਬਿਧੁੰਸਨ ਸ੍ਰਿਸਟਿ ਕਰੇ। ੧੫। ੨੨੫।","roman":"Jai jai hosee mahikhaasur mardan bis bidhunsan sristi kare | 15 | 225 |","meaning_en":"","page":126}]},{"type":"verse","number":[16,226],"number_text":"੧੬। ੨੨੬।","page":127,"lines":[{"gurmukhi":"ਦਾਮਿਨੀ ਪ੍ਰਕਾਸੇ ਉਨਤ ਨਾਸੇ ਜੋਤਿ ਪ੍ਰਕਾਸੇ ਅਤੁਲ ਬਲੇ।","roman":"Daaminee prakaase unat naase joti prakaase atul bale |","meaning_en":"","page":127},{"gurmukhi":"ਦਾਨਵੀ ਪ੍ਰਕਰਖਣ ਸਰ ਵਰ ਵਰਖਣ ਦੁਸਟ ਪ੍ਰਧਰਖਣ ਬਿਤਲ ਤਲੇ।","roman":"Daanvee prakarkhan sar var varkhan dusat pradharkhan bital tale |","meaning_en":"","page":127},{"gurmukhi":"ਅਸਟਾਯੁਧ ਬਾਹਣ ਬੋਲ ਨਿਬਾਹਣ ਸੰਤ ਪਨਾਹਣ ਗੂੜ ਗਤੇ।","roman":"Astaayudh baahan bol nibaahan sant panaahan goor gate |","meaning_en":"","page":127},{"gurmukhi":"ਜੈ ਜੈ ਹੋਸੀ ਮਹਿਖਾਸੁਰ ਮਰਦਨ ਆਦਿ ਅਨਾਦਿ ਅਗਾਧਿ ਬ੍ਰਿਤੇ। ੧੬। ੨੨੬।","roman":"Jai jai hosee mahikhaasur mardan aadi anaadi agaadhi brite | 16 | 226 |","meaning_en":"","page":127}]},{"type":"verse","number":[17,227],"number_text":"੧੭। ੨੨੭।","page":127,"lines":[{"gurmukhi":"ਦੁਖ ਦੋਖ ਪ੍ਰਭਛਣ ਸੇਵਕ ਰਛਣ ਸੰਤ ਪ੍ਰਤਛਣ ਸੁਧ ਸਰੇ।","roman":"Dukh dokh prabhchhan sevak rachhan sant pratchhan sudh sare |","meaning_en":"","page":127},{"gurmukhi":"ਸਾਰੰਗ ਸਨਾਹੇ ਦੁਸਟ ਪ੍ਰਦਾਹੇ ਅਰਿ ਦਲ ਗਾਹੇ ਦੋਖ ਹਰੇ।","roman":"Saarang sanaahe dusat pradaahe ari dal gaahe dokh hare |","meaning_en":"","page":127},{"gurmukhi":"ਗੰਜਨ ਗੁਮਾਨੇ ਅਤੁਲ ਪ੍ਰਵਾਨੇ ਸੰਤਿ ਜਮਾਨੇ ਆਦਿ ਅੰਤੇ।","roman":"Ganjan gumaane atul pravaane santi jamaane aadi ante |","meaning_en":"","page":127},{"gurmukhi":"ਜੈ ਜੈ ਹੋਸੀ ਮਹਿਖਾਸੁਰ ਮਰਦਨ ਸਾਧ ਪ੍ਰਦਛਨ ਦੁਸਟ ਹੰਤੇ। ੧੭। ੨੨੭।","roman":"Jai jai hosee mahikhaasur mardan saadh pradchhan dusat hante | 17 | 227 |","meaning_en":"","page":127}]},{"type":"verse","number":[18,228],"number_text":"੧੮।੨੨੮।","page":127,"lines":[{"gurmukhi":"ਕਾਰਣ ਕਰੀਲੀ ਗਰਬ ਗਹੀਲੀ ਜੋਤਿ ਜਿਤੀਲੀ ਤੁੰਦ ਮਤੇ।","roman":"Kaaran kareelee garab gaheelee joti jiteelee tund mate |","meaning_en":"","page":127},{"gurmukhi":"ਅਸਟਾਇਧ ਚਮਕਣ ਸਸਤ੍ਰ ਝਮਕਣ ਦਾਮਿਨਿ ਦਮਕਣ ਆਦਿ ਬ੍ਰਿਤੇ।","roman":"Astaaidh chamkan sasatr jhamkan daamini damkan aadi brite |","meaning_en":"","page":127},{"gurmukhi":"ਡੁਕਡੁਕੀ ਡਮੰਕੈ ਬਾਘ ਬਬੰਕੈ ਭੁਜਾ ਫਰੰਕੈ ਸੁਧ ਗਤੇ।","roman":"Dukdukee damankai baagh babankai bhujaa pharankai sudh gate |","meaning_en":"","page":127},{"gurmukhi":"ਜੈ ਜੈ ਹੋਸੀ ਮਹਿਖਾਸੁਰ ਮਰਦਨ ਆਦਿ ਜੁਗਾਦਿ ਅਨਾਦਿ ਮਤੇ। ੧੮।੨੨੮।","roman":"Jai jai hosee mahikhaasur mardan aadi jugaadi anaadi mate | 18 | 228 |","meaning_en":"","page":127}]},{"type":"verse","number":[19,229],"number_text":"੧੯। ੨੨੯।","page":127,"lines":[{"gurmukhi":"ਚਛਰਾਸੁਰ ਮਾਰਣ ਨਰਕ ਨਿਵਾਰਣ ਪਤਿਤ ਉਧਾਰਣ ਏਕ ਭਟੇ।","roman":"Chachhraasur maaran narak nivaaran patit udhaaran ek bhate |","meaning_en":"","page":127},{"gurmukhi":"ਪਾਪਾਨ ਬਿਹੰਡਨ ਦੁਸਟ ਪ੍ਰਚੰਡਣ ਖੰਡ ਅਖੰਡਣ ਕਾਲ ਕਟੇ।","roman":"Paapaan bihandan dusat prachandan khand akhandan kaal kate |","meaning_en":"","page":127},{"gurmukhi":"ਚੰਦ੍ਰਾਨਨ ਚਾਰੈ ਨਰਕ ਨਿਵਾਰੈ ਪਤਿਤ ਉਧਾਰੈ ਮੁੰਡ ਮਥੇ।","roman":"Chandraanan chaarai narak nivaarai patit udhaarai mund mathe |","meaning_en":"","page":127},{"gurmukhi":"ਜੈ ਜੈ ਹੋਸੀ ਮਹਿਖਾਸੁਰ ਮਰਦਨ ਧੂਮ੍ਰ ਬਿਧੁੰਸਨ ਆਦਿ ਕਥੇ। ੧੯। ੨੨੯।","roman":"Jai jai hosee mahikhaasur mardan dhoomr bidhunsan aadi kathe | 19 | 229 |","meaning_en":"","page":127}]},{"type":"verse","number":[20,230],"number_text":"੨੦। ੨੩੦।","page":127,"lines":[{"gurmukhi":"ਰਕਤਾਸੁਰ ਮਰਦਨ ਚੰਡ ਚਕ੍ਰਦਨ ਦਾਨਵ ਅਰਦਨ ਬਿੜਾਲ ਬਧੇ।","roman":"Raktaasur mardan chand chakradan daanav ardan biraal badhe |","meaning_en":"","page":127},{"gurmukhi":"ਸਰ ਧਾਰ ਬਿਬਰਖਣ ਦੁਰਜਨ ਧਰਖਣ ਅਤੁਲ ਅਮਰਖਣ ਧਰਮ ਧੁਜੇ।","roman":"Sar dhaar bibarkhan durjan dharkhan atul amarkhan dharam dhuje |","meaning_en":"","page":127},{"gurmukhi":"ਧੂਮ੍ਰਾਛ ਬਿਧੁੰਸਨ ਸ੍ਰੋਣਤ ਚੁੰਸਨ ਸੁੰਭ ਨਿਪਾਤ ਨਿਸੁੰਭ ਮਥੇ।","roman":"Dhoomraachh bidhunsan sronat chunsan sunbh nipaat nisunbh mathe |","meaning_en":"","page":127},{"gurmukhi":"ਜੈ ਜੈ ਹੋਸੀ ਮਹਿਖਾਸੁਰ ਮਰਦਨ ਆਦਿ ਅਨੀਲ ਅਗਾਧਿ ਕਥੇ। ੨੦। ੨੩੦।","roman":"Jai jai hosee mahikhaasur mardan aadi aneel agaadhi kathe | 20 | 230 |","meaning_en":"","page":127}]},{"type":"heading","kind":"chhand","name":"ਪਾਧੜੀ ਛੰਦ","gurmukhi":"ਤ੍ਵਪ੍ਰਸਾਦਿ। ਪਾਧੜੀ ਛੰਦ","roman":"Tvaprasaadi | paadhree chhand","meaning_en":"","page":128,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[1,231],"number_text":"੧। ੨੩੧।","page":128,"lines":[{"gurmukhi":"ਤੁਮ ਕਹੋ ਦੇਵ ਸਰਬੰ ਬਿਚਾਰ। ਜਿਮ ਕੀਓ ਆਪਿ ਕਰਤੇ ਪਸਾਰ।","roman":"Tum kaho dev sarban bichaar | jim keeo aapi karte pasaar |","meaning_en":"","page":128},{"gurmukhi":"ਜਦਪਿ ਅਭੂਤ ਅਨਭੈ ਅਨੰਤ। ਤਉ ਕਹੋ ਜਥਾ ਮਤਿ ਤ੍ਰੈਣ ਤੰਤ। ੧। ੨੩੧।","roman":"Jadpi abhoot anbhai anant | tau kaho jathaa mati train tant | 1 | 231 |","meaning_en":"","page":128}]},{"type":"verse","number":[2,232],"number_text":"੨। ੨੩੨।","page":128,"lines":[{"gurmukhi":"ਕਰਤਾ ਕਰੀਮ ਕਾਦਿਰ ਕ੍ਰਿਪਾਲ। ਅਦ੍ਵੈ ਅਭੂਤ ਅਨਭੈ ਦਿਆਲ।","roman":"Kartaa kareem kaadir kripaal | advai abhoot anbhai diaal |","meaning_en":"","page":128},{"gurmukhi":"ਦਾਤਾ ਦੁਰੰਤ ਦੁਖ ਦੋਖ ਰਹਤ। ਜਿਹ ਨੇਤਿ ਨੇਤਿ ਸਭ ਬੇਦ ਕਹਤ। ੨। ੨੩੨।","roman":"Daataa durant dukh dokh rahat | jih neti neti sabh bed kahat | 2 | 232 |","meaning_en":"","page":128}]},{"type":"verse","number":[3,233],"number_text":"੩। ੨੩੩।","page":128,"lines":[{"gurmukhi":"ਕਈ ਊਚ ਨੀਚ ਕੀਨੋ ਬਨਾਉ। ਸਭ ਵਾਰ ਪਾਰ ਜਾ ਕੋ ਪ੍ਰਭਾਉ।","roman":"Kaee ooch neech keeno banaau | sabh vaar paar jaa ko prabhaau |","meaning_en":"","page":128},{"gurmukhi":"ਸਭ ਜੀਵ ਜੰਤ ਜਾਨੰਤ ਜਾਹਿ। ਮਨ ਮੂੜ ਕਿਉ ਨ ਸੇਵੰਤ ਤਾਹਿ। ੩। ੨੩੩।","roman":"Sabh jeev jant jaanant jaahi | man moor kiu na sevant taahi | 3 | 233 |","meaning_en":"","page":128}]},{"type":"verse","number":[4,234],"number_text":"੪। ੨੩੪।","page":128,"lines":[{"gurmukhi":"ਕਈ ਮੂੜ ਪਤ੍ਰ ਪੂਜਾ ਕਰੰਤ। ਕਈ ਸਿਧ ਸਾਧੁ ਸੂਰਜ ਸਿਵੰਤ।","roman":"Kaee moor patr poojaa karant | kaee sidh saadhu sooraj sivant |","meaning_en":"","page":128},{"gurmukhi":"ਕਈ ਪਲਟਿ ਸੂਰਜ ਸਿਜਦਾ ਕਰਾਇ। ਪ੍ਰਭ ਏਕ ਰੂਪ ਦ੍ਵੈ ਕੈ ਲਖਾਇ। ੪। ੨੩੪।","roman":"Kaee palti sooraj sijdaa karaai | prabh ek roop dvai kai lakhaai | 4 | 234 |","meaning_en":"","page":128}]},{"type":"verse","number":[5,235],"number_text":"੫। ੨੩੫।","page":128,"lines":[{"gurmukhi":"ਅਨਛਿਜ ਤੇਜ ਅਨਭੈ ਪ੍ਰਕਾਸ। ਦਾਤਾ ਦੁਰੰਤ ਅਦ੍ਵੈ ਅਨਾਸ।","roman":"Anchhij tej anbhai prakaas | daataa durant advai anaas |","meaning_en":"","page":128},{"gurmukhi":"ਸਭ ਰੋਗ ਸੋਗ ਤੇ ਰਹਤ ਰੂਪ। ਅਨਭੈ ਅਕਾਲ ਅਛੈ ਸਰੂਪ। ੫। ੨੩੫।","roman":"Sabh rog sog te rahat roop | anbhai akaal achhai saroop | 5 | 235 |","meaning_en":"","page":128}]},{"type":"verse","number":[6,236],"number_text":"੬। ੨੩੬।","page":128,"lines":[{"gurmukhi":"ਕਰੁਣਾ ਨਿਧਾਨ ਕਾਮਿਲ ਕ੍ਰਿਪਾਲ। ਦੂਖ ਦੋਖ ਹਰਤ ਦਾਤਾ ਦਿਆਲ।","roman":"Karunaa nidhaan kaamil kripaal | dookh dokh harat daataa diaal |","meaning_en":"","page":128},{"gurmukhi":"ਅੰਜਨ ਬਿਹੀਨ ਅਨਭੰਜ ਨਾਥ। ਜਲ ਥਲ ਪ੍ਰਭਾਉ ਸਰਬਤ੍ਰ ਸਾਥ। ੬। ੨੩੬।","roman":"Anjan biheen anbhanj naath | jal thal prabhaau sarbatr saath | 6 | 236 |","meaning_en":"","page":128}]},{"type":"verse","number":[7,237],"number_text":"੭। ੨੩੭।","page":128,"lines":[{"gurmukhi":"ਜਿਹ ਜਾਤਿ ਪਾਤਿ ਨਹੀ ਭੇਦ ਭਰਮ। ਜਿਹ ਰੰਗ ਰੂਪ ਨਹੀ ਏਕ ਧਰਮ।","roman":"Jih jaati paati nahee bhed bharam | jih rang roop nahee ek dharam |","meaning_en":"","page":128},{"gurmukhi":"ਜਿਹ ਸਤ੍ਰੁ ਮਿਤ੍ਰ ਦੋਊ ਏਕ ਸਾਰ। ਅਛੈ ਸਰੂਪ ਅਬਿਚਲ ਅਪਾਰ। ੭। ੨੩੭।","roman":"Jih satru mitr do'oo ek saar | achhai saroop abichal apaar | 7 | 237 |","meaning_en":"","page":128}]},{"type":"verse","number":[8,238],"number_text":"੮। ੨੩੮।","page":128,"lines":[{"gurmukhi":"ਜਾਨੀ ਨ ਜਾਇ ਜਿਹ ਰੂਪ ਰੇਖ। ਕਹਿ ਬਾਸੁ ਤਾਸੁ ਕਹਿ ਕਉਨੁ ਭੇਖ।","roman":"Jaanee na jaai jih roop rekh | kahi baasu taasu kahi kaunu bhekh |","meaning_en":"","page":128},{"gurmukhi":"ਕਹਿ ਨਾਮ ਤਾਸੁ ਹੈ ਕਵਨ ਜਾਤਿ। ਜਿਹ ਸਤ੍ਰੁ ਮਿਤ੍ਰ ਨਹੀ ਪੁਤ੍ਰ ਭ੍ਰਾਤ। ੮। ੨੩੮।","roman":"Kahi naam taasu hai kavan jaati | jih satru mitr nahee putr bhraat | 8 | 238 |","meaning_en":"","page":128}]},{"type":"verse","number":[9,239],"number_text":"੯। ੨੩੯।","page":128,"lines":[{"gurmukhi":"ਕਰੁਣਾ ਨਿਧਾਨ ਕਾਰਣ ਸਰੂਪ। ਜਿਹ ਚਕ੍ਰ ਚਿਹਨ ਨਹੀ ਰੰਗ ਰੂਪ।","roman":"Karunaa nidhaan kaaran saroop | jih chakr chihan nahee rang roop |","meaning_en":"","page":128},{"gurmukhi":"ਜਿਹ ਖੇਦ ਭੇਦ ਨਹੀ ਕਰਮ ਕਾਲ। ਸਭ ਜੀਵ ਜੰਤ ਕੀ ਕਰਤ ਪਾਲ। ੯। ੨੩੯।","roman":"Jih khed bhed nahee karam kaal | sabh jeev jant kee karat paal | 9 | 239 |","meaning_en":"","page":128}]},{"type":"verse","number":[10,240],"number_text":"੧੦। ੨੪੦।","page":128,"lines":[{"gurmukhi":"ਉਰਧੰ ਬਿਰਹਤ ਸਿਧ ਸਰੂਪ। ਬੁਧੰ ਅਪਾਲ ਜੁਧੰ ਅਨੂਪ।","roman":"Urdhan birhat sidh saroop | budhan apaal judhan anoop |","meaning_en":"","page":128},{"gurmukhi":"ਜਿਹ ਰੂਪ ਰੇਖ ਨਹੀ ਰੰਗ ਰਾਗ। ਅਨਛਿਜ ਤੇਜ ਅਨਭਿਜ ਅਦਾਗ। ੧੦। ੨੪੦।","roman":"Jih roop rekh nahee rang raag | anchhij tej anbhij adaag | 10 | 240 |","meaning_en":"","page":128}]},{"type":"verse","number":[11,241],"number_text":"੧੧। ੨੪੧।","page":129,"lines":[{"gurmukhi":"ਜਲ ਥਲ ਮਹੀਪ ਬਨ ਤਨ ਦੁਰੰਤ। ਜਿਹ ਨੇਤਿ ਨੇਤਿ ਨਿਸਿ ਦਿਨ ਉਚਰੰਤ।","roman":"Jal thal maheep ban tan durant | jih neti neti nisi din uchrant |","meaning_en":"","page":129},{"gurmukhi":"ਪਾਇਓ ਨ ਜਾਇ ਜਿਹ ਪੈਰਿ ਪਾਰ। ਦੀਨਾਨ ਦੋਖ ਦਹਿਤਾ ਉਦਾਰ। ੧੧। ੨੪੧।","roman":"Paaio na jaai jih pairi paar | deenaan dokh dahitaa udaar | 11 | 241 |","meaning_en":"","page":129}]},{"type":"verse","number":[12,242],"number_text":"੧੨। ੨੪੨।","page":129,"lines":[{"gurmukhi":"ਕਈ ਕੋਟਿ ਇੰਦ੍ਰ ਜਿਹ ਪਾਨਿਹਾਰ। ਕਈ ਕੋਟਿ ਰੁਦ੍ਰ ਜੁਗੀਆ ਦੁਆਰ।","roman":"Kaee koti indr jih paanihaar | kaee koti rudr jugeeaa duaar |","meaning_en":"","page":129},{"gurmukhi":"ਕਈ ਬੇਦ ਬਿਆਸ ਬ੍ਰਹਮਾ ਅਨੰਤ। ਜਿਹ ਨੇਤਿ ਨੇਤਿ ਨਿਸਿ ਦਿਨ ਉਚਰੰਤ। ੧੨। ੨੪੨।","roman":"Kaee bed biaas brahmaa anant | jih neti neti nisi din uchrant | 12 | 242 |","meaning_en":"","page":129}]},{"type":"heading","kind":"chhand","name":"ਸ੍ਵੈਯੇ","gurmukhi":"ਤ੍ਵਪ੍ਰਸਾਦਿ। ਸ੍ਵੈਯੇ","roman":"Tvaprasaadi | svaiye","meaning_en":"","page":129,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[1,243],"number_text":"੧। ੨੪੩।","page":129,"lines":[{"gurmukhi":"ਦੀਨਿਨ ਕੀ ਪ੍ਰਤਿਪਾਲ ਕਰੈ ਨਿਤ ਸੰਤ ਉਬਾਰਿ ਗਨੀਮਨ ਗਾਰੈ।","roman":"Deenin kee pratipaal karai nit sant ubaari ganeeman gaarai |","meaning_en":"","page":129},{"gurmukhi":"ਪਛ ਪਸੂ ਨਗ ਨਾਗ ਨਰਾਧਿਪ ਸਰਬ ਸਮੈ ਸਭ ਕੋ ਪ੍ਰਤਿਪਾਰੈ।","roman":"Pachh pasoo nag naag naraadhip sarab samai sabh ko pratipaarai |","meaning_en":"","page":129},{"gurmukhi":"ਪੋਖਤ ਹੈ ਜਲ ਮੈ ਥਲ ਮੈ ਪਲ ਮੈ ਕਲਿ ਕੇ ਨਹੀ ਕਰਮ ਬਿਚਾਰੈ।","roman":"Pokhat hai jal mai thal mai pal mai kali ke nahee karam bichaarai |","meaning_en":"","page":129},{"gurmukhi":"ਦੀਨ ਦਇਆਲ ਦਇਆਨਿਧਿ ਦੋਖਨ ਦੇਖਤ ਹੈ ਪਰੁ ਦੇਤ ਨ ਹਾਰੈ। ੧। ੨੪੩।","roman":"Deen daiaal daiaanidhi dokhan dekhat hai paru det na haarai | 1 | 243 |","meaning_en":"","page":129}]},{"type":"verse","number":[2,244],"number_text":"੨। ੨੪੪।","page":129,"lines":[{"gurmukhi":"ਦਾਹਤ ਹੈ ਦੁਖ ਦੋਖਨ ਕੌ ਦਲ ਦੁਜਨ ਕੇ ਪਲ ਮੈ ਦਲ ਡਾਰੈ।","roman":"Daahat hai dukh dokhan kau dal dujan ke pal mai dal daarai |","meaning_en":"","page":129},{"gurmukhi":"ਖੰਡ ਅਖੰਡ ਪ੍ਰਚੰਡ ਪ੍ਰਹਾਰਨ ਪੂਰਨ ਪ੍ਰੇਮ ਕੀ ਪ੍ਰੀਤਿ ਸੰਭਾਰੈ।","roman":"Khand akhand prachand prahaaran pooran prem kee preeti sanbhaarai |","meaning_en":"","page":129},{"gurmukhi":"ਪਾਰੁ ਨ ਪਾਇ ਸਕੈ ਪਦਮਾਪਤਿ ਬੇਦ ਕਤੇਬ ਅਭੇਦ ਉਚਾਰੈ।","roman":"Paaru na paai sakai padmaapti bed kateb abhed uchaarai |","meaning_en":"","page":129},{"gurmukhi":"ਰੋਜ ਹੀ ਰਾਜ ਬਿਲੋਕਤ ਰਾਜਿਕ ਰੋਖਿ ਰੂਹਾਨ ਕੀ ਰੋਜੀ ਨ ਟਾਰੈ। ੨। ੨੪੪।","roman":"Roj hee raaj bilokat raajik rokhi roohaan kee rojee na taarai | 2 | 244 |","meaning_en":"","page":129}]},{"type":"verse","number":[3,245],"number_text":"੩। ੨੪੫।","page":129,"lines":[{"gurmukhi":"ਕੀਟ ਪਤੰਗ ਕੁਰੰਗ ਭੁਜੰਗਮ ਭੂਤ ਭਵਿਖ ਭਵਾਨ ਬਨਾਏ।","roman":"Keet patang kurang bhujangam bhoot bhavikh bhavaan banaae |","meaning_en":"","page":129},{"gurmukhi":"ਦੇਵ ਅਦੇਵ ਖਪੇ ਅਹੰਮੇਵ ਨ ਭੇਵ ਲਖਿਓ ਭ੍ਰਮ ਸਿਉ ਭਰਮਾਏ।","roman":"Dev adev khape ahanmev na bhev lakhio bhram siu bharmaae |","meaning_en":"","page":129},{"gurmukhi":"ਬੇਦ ਪੁਰਾਨ ਕਤੇਬ ਕੁਰਾਨ ਹਸੇਬ ਥਕੇ ਕਰ ਹਾਥਿ ਨ ਆਏ।","roman":"Bed puraan kateb kuraan haseb thake kar haathi na aae |","meaning_en":"","page":129},{"gurmukhi":"ਪੂਰਨ ਪ੍ਰੇਮ ਪ੍ਰਭਾਉ ਬਿਨਾ ਪਤਿ ਸਿਉ ਕਿਨ ਸ੍ਰੀ ਪਦਮਾਪਤਿ ਪਾਏ। ੩। ੨੪੫।","roman":"Pooran prem prabhaau binaa pati siu kin sree padmaapti paae | 3 | 245 |","meaning_en":"","page":129}]},{"type":"verse","number":[4,246],"number_text":"੪। ੨੪੬।","page":129,"lines":[{"gurmukhi":"ਆਦਿ ਅਨੰਤ ਅਗਾਧਿ ਅਦ੍ਵੈਖ ਸੁ ਭੂਤ ਭਵਿਖ ਭਵਾਨ ਅਭੈ ਹੈ।","roman":"Aadi anant agaadhi advaikh su bhoot bhavikh bhavaan abhai hai |","meaning_en":"","page":129},{"gurmukhi":"ਅੰਤਿ ਬਿਹੀਨ ਅਨਾਤਮ ਆਪ ਅਦਾਗ ਅਦੋਖ ਅਛਿਦ੍ਰ ਅਛੈ ਹੈ।","roman":"Anti biheen anaatam aap adaag adokh achhidr achhai hai |","meaning_en":"","page":129},{"gurmukhi":"ਲੋਗਨ ਕੇ ਕਰਤਾ ਹਰਤਾ ਜਲ ਮੈ ਥਲ ਮੈ ਭਰਤਾ ਪ੍ਰਭ ਵੈ ਹੈ।","roman":"Logan ke kartaa hartaa jal mai thal mai bhartaa prabh vai hai |","meaning_en":"","page":129},{"gurmukhi":"ਦੀਨ ਦਇਆਲ ਦਇਆ ਕਰ ਸ੍ਰੀਪਤਿ ਸੁੰਦਰ ਸ੍ਰੀ ਪਦਮਾਪਤਿ ਏ ਹੈ। ੪। ੨੪੬।","roman":"Deen daiaal daiaa kar sreepti sundar sree padmaapti e hai | 4 | 246 |","meaning_en":"","page":129}]},{"type":"verse","number":[5,247],"number_text":"੫। ੨੪੭।","page":129,"lines":[{"gurmukhi":"ਕਾਮ ਨ ਕ੍ਰੋਧ ਨ ਲੋਭ ਨ ਮੋਹ ਨ ਰੋਗ ਨ ਸੋਗ ਨ ਭੋਗ ਨ ਭੈ ਹੈ।","roman":"Kaam na krodh na lobh na moh na rog na sog na bhog na bhai hai |","meaning_en":"","page":129,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}]},{"gurmukhi":"ਦੇਹ ਬਿਹੀਨ ਸਨੇਹ ਸਭੋ ਤਨ ਨੇਹ ਬਿਰਕਤ ਅਗੇਹ ਅਛੈ ਹੈ।","roman":"Deh biheen saneh sabho tan neh birkat ageh achhai hai |","meaning_en":"","page":129},{"gurmukhi":"ਜਾਨ ਕੋ ਦੇਤ ਅਜਾਨ ਕੋ ਦੇਤ ਜਮੀਨ ਕੋ ਦੇਤ ਜਮਾਨ ਕੋ ਦੈ ਹੈ।","roman":"Jaan ko det ajaan ko det jameen ko det jamaan ko dai hai |","meaning_en":"","page":129},{"gurmukhi":"ਕਾਹੇ ਕੋ ਡੋਲਤ ਹੈ ਤੁਮਰੀ ਸੁਧਿ ਸੁੰਦਰ ਸ੍ਰੀ ਪਦਮਾਪਤਿ ਲੈ ਹੈ। ੫। ੨੪੭।","roman":"Kaahe ko dolat hai tumree sudhi sundar sree padmaapti lai hai | 5 | 247 |","meaning_en":"","page":129}]},{"type":"verse","number":[6,248],"number_text":"੬। ੨੪੮।","page":130,"lines":[{"gurmukhi":"ਰੋਗਨ ਤੇ ਅਰੁ ਸੋਗਨ ਤੇ ਜਲ ਜੋਗਨ ਤੇ ਬਹੁ ਭਾਤਿ ਬਚਾਵੈ।","roman":"Rogan te aru sogan te jal jogan te bahu bhaati bachaavai |","meaning_en":"","page":130},{"gurmukhi":"ਸਤ੍ਰ ਅਨੇਕ ਚਲਾਵਤ ਘਾਵ ਤਊ ਤਨਿ ਏਕੁ ਨ ਲਾਗਨ ਪਾਵੈ।","roman":"Satr anek chalaavat ghaav taoo tani eku na laagan paavai |","meaning_en":"","page":130},{"gurmukhi":"ਰਾਖਤ ਹੈ ਅਪਨੋ ਕਰੁ ਦੈ ਕਰਿ ਪਾਪ ਸਬੂਹ ਨ ਭੇਟਨ ਪਾਵੈ।","roman":"Raakhat hai apno karu dai kari paap sabooh na bhetan paavai |","meaning_en":"","page":130},{"gurmukhi":"ਔਰ ਕੀ ਬਾਤ ਕਹਾ ਕਹ ਤੋ ਸੌ ਸੁ ਪੇਟ ਹੀ ਕੇ ਪਟ ਬੀਚ ਬਚਾਵੈ। ੬। ੨੪੮।","roman":"Aur kee baat kahaa kah to sau su pet hee ke pat beech bachaavai | 6 | 248 |","meaning_en":"","page":130}]},{"type":"verse","number":[7,249],"number_text":"੭। ੨੪੯।","page":130,"lines":[{"gurmukhi":"ਜਛ ਭੁਜੰਗ ਸੁ ਦਾਨਵ ਦੇਵ ਅਭੇਵ ਤੁਮੈ ਸਭ ਹੀ ਕਰਿ ਧਿਆਵੈ।","roman":"Jachh bhujang su daanav dev abhev tumai sabh hee kari dhiaavai |","meaning_en":"","page":130},{"gurmukhi":"ਭੂਮਿ ਅਕਾਸ ਪਤਾਲ ਰਸਾਤਲ ਜਛ ਭੁਜੰਗ ਸਭੈ ਸਿਰ ਨਿਆਵੈ।","roman":"Bhoomi akaas pataal rasaatal jachh bhujang sabhai sir niaavai |","meaning_en":"","page":130},{"gurmukhi":"ਪਾਇ ਸਕੈ ਨਹੀ ਪਾਰ ਪ੍ਰਭਾ ਹੂੰ ਕੋ ਨੇਤਿ ਹੀ ਨੇਤਹ ਬੇਦ ਬਤਾਵੈ।","roman":"Paai sakai nahee paar prabhaa hoon ko neti hee netah bed bataavai |","meaning_en":"","page":130},{"gurmukhi":"ਖੋਜ ਥਕੈ ਸਭ ਹੀ ਖੁਜੀਆ ਸੁਰ ਹਾਰ ਪਰੇ ਹਰਿ ਹਾਥਿ ਨ ਆਵੈ। ੭। ੨੪੯।","roman":"Khoj thakai sabh hee khujeeaa sur haar pare hari haathi na aavai | 7 | 249 |","meaning_en":"","page":130}]},{"type":"verse","number":[8,250],"number_text":"੮। ੨੫੦।","page":130,"lines":[{"gurmukhi":"ਨਾਰਦ ਸੇ ਚਤੁਰਾਨਨ ਸੇ ਰੁਮਨਾਰਿਖ ਸੇ ਸਭਹੂੰ ਮਿਲਿ ਗਾਇਓ।","roman":"Naarad se chaturaanan se rumnaarikh se sabhhoon mili gaaio |","meaning_en":"","page":130},{"gurmukhi":"ਬੇਦ ਕਤੇਬ ਨ ਭੇਦ ਲਖਿਓ ਸਭ ਹਾਰਿ ਪਰੇ ਹਰਿ ਹਾਥਿ ਨ ਆਇਓ।","roman":"Bed kateb na bhed lakhio sabh haari pare hari haathi na aaio |","meaning_en":"","page":130},{"gurmukhi":"ਪਾਇ ਸਕੈ ਨਹੀ ਪਾਰ ਉਮਾਪਤਿ ਸਿਧ ਸਨਾਥ ਸਨੰਤਨ ਧਿਆਇਓ।","roman":"Paai sakai nahee paar umaapti sidh sanaath sanantan dhiaaio |","meaning_en":"","page":130},{"gurmukhi":"ਧਿਆਨ ਧਰੋ ਤਿਹ ਕੋ ਮਨ ਮੈ ਜਿਹ ਕੋ ਅਮਿਤੋਜ ਸਭੈ ਜਗਿ ਛਾਇਓ। ੮। ੨੫੦।","roman":"Dhiaan dharo tih ko man mai jih ko amitoj sabhai jagi chhaaio | 8 | 250 |","meaning_en":"","page":130}]},{"type":"verse","number":[9,251],"number_text":"੯। ੨੫੧।","page":130,"lines":[{"gurmukhi":"ਬੇਦ ਪੁਰਾਨ ਕਤੇਬ ਕੁਰਾਨ ਅਭੇਦ ਨ੍ਰਿਪਾਨ ਸਭੈ ਪਚਿਹਾਰੇ।","roman":"Bed puraan kateb kuraan abhed nripaan sabhai pachihaare |","meaning_en":"","page":130},{"gurmukhi":"ਭੇਦ ਨ ਪਾਇ ਸਕਿਓ ਅਨਭੇਦ ਕੋ ਖੇਦਤ ਹੈ ਅਨਛੇਦ ਪੁਕਾਰੇ।","roman":"Bhed na paai sakio anbhed ko khedat hai anchhed pukaare |","meaning_en":"","page":130},{"gurmukhi":"ਰਾਗ ਨ ਰੂਪ ਨ ਰੇਖ ਨ ਰੰਗ ਨ ਸਾਕ ਨ ਸੋਗ ਨ ਸੰਗ ਤਿਹਾਰੇ।","roman":"Raag na roop na rekh na rang na saak na sog na sang tihaare |","meaning_en":"","page":130},{"gurmukhi":"ਆਦਿ ਅਨਾਦਿ ਅਗਾਧਿ ਅਭੇਖ ਅਦ੍ਵੈਖ ਜਪਿਓ ਤਿਨ ਹੀ ਕੁਲ ਤਾਰੇ। ੯। ੨੫੧।","roman":"Aadi anaadi agaadhi abhekh advaikh japio tin hee kul taare | 9 | 251 |","meaning_en":"","page":130}]},{"type":"verse","number":[10,252],"number_text":"੧੦। ੨੫੨।","page":130,"lines":[{"gurmukhi":"ਤੀਰਥ ਕੋਟ ਕੀਏ ਇਸਨਾਨ ਦੀਏ ਬਹੁ ਦਾਨ ਮਹਾ ਬ੍ਰਤ ਧਾਰੇ।","roman":"Teerath kot kee'e isnaan dee'e bahu daan mahaa brat dhaare |","meaning_en":"","page":130},{"gurmukhi":"ਦੇਸ ਫਿਰਿਓ ਕਰ ਭੇਸ ਤਪੋਧਨ ਕੇਸ ਧਰੇ ਨ ਮਿਲੇ ਹਰਿ ਪਿਆਰੇ।","roman":"Des phirio kar bhes tapodhan kes dhare na mile hari piaare |","meaning_en":"","page":130},{"gurmukhi":"ਆਸਨ ਕੋਟਿ ਕਰੇ ਅਸਟਾਂਗ ਧਰੇ ਬਹੁ ਨਿਆਸ ਕਰੇ ਮੁਖ ਕਾਰੇ।","roman":"Aasan koti kare astaang dhare bahu niaas kare mukh kaare |","meaning_en":"","page":130},{"gurmukhi":"ਦੀਨ ਦਇਆਲ ਅਕਾਲ ਭਜੇ ਬਿਨੁ ਅੰਤ ਕੋ ਅੰਤ ਕੇ ਧਾਮ ਸਿਧਾਰੇ। ੧੦। ੨੫੨।","roman":"Deen daiaal akaal bhaje binu ant ko ant ke dhaam sidhaare | 10 | 252 |","meaning_en":"","page":130}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਤ੍ਵਪ੍ਰਸਾਦਿ। ਕਬਿਤੁ","roman":"Tvaprasaadi | kabitu","meaning_en":"","page":130,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[1,253],"number_text":"੧। ੨੫੩।","page":130,"lines":[{"gurmukhi":"ਅਤ੍ਰ ਕੇ ਚਲਯਾ ਛਿਤ੍ਰ ਛਤ੍ਰ ਕੇ ਧਰਯਾ","roman":"Atr ke chalyaa chhitr chhatr ke dharyaa","meaning_en":"","page":130},{"gurmukhi":"ਛਤ੍ਰਧਾਰੀਓ ਕੇ ਛਲਯਾ ਮਹਾ ਸਤ੍ਰਨ ਕੇ ਸਾਲ ਹੈਂ।","roman":"Chhatradhaareeo ke chhalyaa mahaa satran ke saal hain |","meaning_en":"","page":130},{"gurmukhi":"ਦਾਨ ਕੇ ਦਿਵਯਾ ਮਹਾ ਮਾਨ ਕੇ ਬਢਯਾ","roman":"Daan ke divyaa mahaa maan ke badhyaa","meaning_en":"","page":130},{"gurmukhi":"ਅਵਸਾਨ ਕੇ ਦਿਵਯਾ ਹੈਂ ਕਟਯਾ ਜਮ ਜਾਲ ਹੈਂ।","roman":"Avsaan ke divyaa hain katyaa jam jaal hain |","meaning_en":"","page":130},{"gurmukhi":"ਜੁਧ ਕੇ ਜਿਤਯਾ ਅਉ ਬਿਰੁਧ ਕੇ ਮਿਟਯਾ","roman":"Judh ke jityaa au birudh ke mityaa","meaning_en":"","page":130},{"gurmukhi":"ਮਹਾ ਬੁਧਿ ਕੇ ਦਿਵਯਾ ਮਹਾ ਮਾਨ ਹੂੰ ਕੇ ਮਾਨ ਹੈਂ।","roman":"Mahaa budhi ke divyaa mahaa maan hoon ke maan hain |","meaning_en":"","page":131},{"gurmukhi":"ਗਿਆਨ ਹੂੰ ਕੇ ਗਿਆਤਾ ਮਹਾ ਬੁਧਿਤਾ ਕੇ ਦਾਤਾ ਦੇਵ","roman":"Giaan hoon ke giaataa mahaa budhitaa ke daataa dev","meaning_en":"","page":131},{"gurmukhi":"ਕਾਲ ਹੂੰ ਕੇ ਕਾਲ ਮਹਾ ਕਾਲ ਹੂੰ ਕੇ ਕਾਲ ਹੈਂ। ੧। ੨੫੩।","roman":"Kaal hoon ke kaal mahaa kaal hoon ke kaal hain | 1 | 253 |","meaning_en":"","page":131}]},{"type":"verse","number":[2,254],"number_text":"੨। ੨੫੪।","page":131,"lines":[{"gurmukhi":"ਪੂਰਬੀ ਨ ਪਾਰ ਪਾਵੈ ਹਿੰਗੁਲਾ ਹਿਮਾਲੇ ਧਿਆਵੈ","roman":"Poorbee na paar paavai hingulaa himaale dhiaavai","meaning_en":"","page":131},{"gurmukhi":"ਗੋਰਿ ਗਰਦੇਜੀ ਗੁਨ ਗਾਵੈ ਤੇਰੇ ਨਾਮ ਹੈਂ।","roman":"Gori gardejee gun gaavai tere naam hain |","meaning_en":"","page":131},{"gurmukhi":"ਜੋਗੀ ਜੋਗ ਸਾਧੈ ਪਉਨ ਸਾਧਨਾ ਕਿਤੇਕ ਬਾਧੈ","roman":"Jogee jog saadhai paun saadhnaa kitek baadhai","meaning_en":"","page":131},{"gurmukhi":"ਆਰਬ ਕੇ ਆਰਬੀ ਅਰਾਧੇ ਤੇਰੇ ਨਾਮ ਹੈਂ।","roman":"Aarab ke aarbee araadhe tere naam hain |","meaning_en":"","page":131},{"gurmukhi":"ਫਰਾਂ ਕੇ ਫਿਰੰਗੀ ਮਾਨੈ ਕੰਧਾਰੀ ਕੁਰੈਸੀ ਜਾਨੈ","roman":"Pharaan ke phirangee maanai kandhaaree kuraisee jaanai","meaning_en":"","page":131},{"gurmukhi":"ਪਛਮ ਕੇ ਪਛਮੀ ਪਛਾਨੈ ਨਿਜ ਕਾਮ ਹੈਂ।","roman":"Pachham ke pachhmee pachhaanai nij kaam hain |","meaning_en":"","page":131},{"gurmukhi":"ਮਰਹਟਾ ਮਘੇਲੇ ਤੇਰੀ ਮਨ ਸੋ ਤਪਸਿਆ ਕਰੈ","roman":"Marahtaa maghele teree man so tapsiaa karai","meaning_en":"","page":131},{"gurmukhi":"ਦ੍ਰਿੜਵੈ ਤਿਲੰਗੀ ਪਹਚਾਨੇ ਧਰਮ ਧਾਮ ਹੈਂ। ੨। ੨੫੪।","roman":"Drirvai tilangee pahchaane dharam dhaam hain | 2 | 254 |","meaning_en":"","page":131}]},{"type":"verse","number":[3,255],"number_text":"੩। ੨੫੫।","page":131,"lines":[{"gurmukhi":"ਬੰਗ ਕੇ ਬੰਗਾਲੀ ਫਿਰਹੰਗ ਕੇ ਫਿਰੰਗਾ ਵਾਲੀ","roman":"Bang ke bangaalee phirhang ke phirangaa vaalee","meaning_en":"","page":131},{"gurmukhi":"ਦਿਲੀ ਕੇ ਦਿਲਵਾਲੀ ਤੇਰੀ ਆਗਿਆ ਮੈ ਚਲਤ ਹੈਂ।","roman":"Dilee ke dilvaalee teree aagiaa mai chalat hain |","meaning_en":"","page":131},{"gurmukhi":"ਰੋਹ ਕੇ ਰੁਹੇਲੇ ਮਾਘ ਦੇਸ ਕੇ ਮਘੇਲੇ ਬੀਰ","roman":"Roh ke ruhele maagh des ke maghele beer","meaning_en":"","page":131},{"gurmukhi":"ਬੰਗਸੀ ਬੁੰਦੇਲੇ ਪਾਪ ਪੁੰਜ ਕੋ ਮਲਤ ਹੈਂ।","roman":"Bangsee bundele paap punj ko malat hain |","meaning_en":"","page":131},{"gurmukhi":"ਗੋਖਾ ਗੁਨ ਗਾਵੈ ਚੀਨ ਮਚੀਨ ਕੇ ਸੀਸ ਨ੍ਯਾਵੈ","roman":"Gokhaa gun gaavai cheen macheen ke sees nyaavai","meaning_en":"","page":131},{"gurmukhi":"ਤਿਬਤੀ ਧਿਆਇ ਦੋਖ ਦੇਹ ਕੇ ਦਲਤ ਹੈਂ।","roman":"Tibtee dhiaai dokh deh ke dalat hain |","meaning_en":"","page":131},{"gurmukhi":"ਜਿਨੈ ਤੋਹਿ ਧਿਆਇਓ ਤਿਨੈ ਪੂਰਨ ਪ੍ਰਤਾਪ ਪਾਇਓ","roman":"Jinai tohi dhiaaio tinai pooran prataap paaio","meaning_en":"","page":131},{"gurmukhi":"ਸਰਬ ਧਨ ਧਾਮ ਫਲ ਫੁਲ ਸੋ ਫਲਤ ਹੈਂ। ੩। ੨੫੫।","roman":"Sarab dhan dhaam phal phul so phalat hain | 3 | 255 |","meaning_en":"","page":131}]},{"type":"verse","number":[4,256],"number_text":"੪। ੨੫੬।","page":131,"lines":[{"gurmukhi":"ਦੇਵ ਦੇਵਤਾਨ ਕੌ ਸੁਰੇਸ ਦਾਨਵਾਨ ਕੌ","roman":"Dev devtaan kau sures daanvaan kau","meaning_en":"","page":131},{"gurmukhi":"ਮਹੇਸ ਗੰਗ ਧਾਨ ਕੌ ਅਭੇਸ ਕਹੀਅਤੁ ਹੈਂ।","roman":"Mahes gang dhaan kau abhes kaheeatu hain |","meaning_en":"","page":131},{"gurmukhi":"ਰੰਗ ਮੈ ਰੰਗੀਨ ਰਾਗ ਰੂਪ ਮੈ ਪ੍ਰਬੀਨ","roman":"Rang mai rangeen raag roop mai prabeen","meaning_en":"","page":131},{"gurmukhi":"ਔਰ ਕਾਹੂੰ ਪੈ ਨ ਦੀਨ ਸਾਧ ਅਧੀਨ ਕਹੀਅਤੁ ਹੈਂ।","roman":"Aur kaahoon pai na deen saadh adheen kaheeatu hain |","meaning_en":"","page":131},{"gurmukhi":"ਪਾਈਐ ਨ ਪਾਰੁ ਤੇਜ ਪੁੰਜ ਮੈ ਅਪਾਰ","roman":"Paaeeai na paaru tej punj mai apaar","meaning_en":"","page":131},{"gurmukhi":"ਸਰਬ ਬਿਦਿਆ ਕੇ ਉਦਾਰ ਹੈਂ ਅਪਾਰ ਕਹੀਅਤੁ ਹੈਂ।","roman":"Sarab bidiaa ke udaar hain apaar kaheeatu hain |","meaning_en":"","page":131},{"gurmukhi":"ਹਾਥੀ ਕੀ ਪੁਕਾਰ ਪਲ ਪਾਛੇ ਪਹੁੰਚਤ ਤਾਹਿ","roman":"Haathee kee pukaar pal paachhe pahunchat taahi","meaning_en":"","page":131},{"gurmukhi":"ਚੀਟੀ ਕੀ ਚਿੰਘਾਰ ਪਹਿਲੇ ਹੀ ਸੁਨੀਅਤੁ ਹੈਂ। ੪। ੨੫੬।","roman":"Cheetee kee chinghaar pahile hee suneeatu hain | 4 | 256 |","meaning_en":"","page":131}]},{"type":"verse","number":[5,257],"number_text":"੫। ੨੫੭।","page":131,"lines":[{"gurmukhi":"ਕੇਤੇ ਇੰਦ੍ਰ ਦੁਆਰਾ ਕੇਤੇ ਬ੍ਰਹਮਾ ਮੁਖਚਾਰ","roman":"Kete indr duaaraa kete brahmaa mukhchaar","meaning_en":"","page":131},{"gurmukhi":"ਕੇਤੇ ਕ੍ਰਿਸਨ ਅਵਤਾਰ ਕੇਤੇ ਰਾਮ ਕਹੀਅਤੁ ਹੈਂ।","roman":"Kete krisan avtaar kete raam kaheeatu hain |","meaning_en":"","page":131},{"gurmukhi":"ਕੇਤੇ ਸਸਿ ਰਾਸੀ ਕੇਤੇ ਸੂਰਜ ਪ੍ਰਕਾਸੀ","roman":"Kete sasi raasee kete sooraj prakaasee","meaning_en":"","page":131},{"gurmukhi":"ਕੇਤੇ ਮੁੰਡੀਆ ਉਦਾਸੀ ਜੋਗ ਦੁਆਰ ਦਹੀਅਤੁ ਹੈਂ।","roman":"Kete mundeeaa udaasee jog duaar daheeatu hain |","meaning_en":"","page":131},{"gurmukhi":"ਕੇਤੇ ਮਹਾਦੀਨ ਕੇਤੇ ਬਿਆਸ ਸੇ ਪ੍ਰਬੀਨ","roman":"Kete mahaadeen kete biaas se prabeen","meaning_en":"","page":131},{"gurmukhi":"ਕੇਤੇ ਕੁਮੇਰ ਕੁਲੀਨ ਕੇਤੇ ਜਛ ਕਹੀਅਤੁ ਹੈਂ।","roman":"Kete kumer kuleen kete jachh kaheeatu hain |","meaning_en":"","page":131},{"gurmukhi":"ਕਰਤੇ ਹੈ ਬਿਚਾਰ ਪੈ ਨ ਪੂਰਨ ਕੋ ਪਾਵੈ ਪਾਰ","roman":"Karte hai bichaar pai na pooran ko paavai paar","meaning_en":"","page":131},{"gurmukhi":"ਤਾਹੀ ਤੇ ਅਪਾਰ ਨਿਰਾਧਾਰ ਲਹੀਅਤੁ ਹੈਂ। ੫। ੨੫੭।","roman":"Taahee te apaar niraadhaar laheeatu hain | 5 | 257 |","meaning_en":"","page":131}]},{"type":"verse","number":[6,258],"number_text":"੬।੨੫੮।","page":132,"lines":[{"gurmukhi":"ਪੂਰਨ ਅਵਤਾਰ ਨਿਰਾਧਾਰ ਹੈ ਨ ਪਾਰਾਵਾਰ","roman":"Pooran avtaar niraadhaar hai na paaraavaar","meaning_en":"","page":132},{"gurmukhi":"ਪਾਈਐ ਨ ਪਾਰ ਪੈ ਅਪਾਰ ਕੈ ਬਖਾਨੀਐ।","roman":"Paaeeai na paar pai apaar kai bakhaaneeai |","meaning_en":"","page":132},{"gurmukhi":"ਅਦ੍ਵੈ ਅਬਿਨਾਸੀ ਪਰਮ ਪੂਰਨ ਪ੍ਰਕਾਸੀ","roman":"Advai abinaasee param pooran prakaasee","meaning_en":"","page":132},{"gurmukhi":"ਮਹਾ ਰੂਪ ਹੂੰ ਕੇ ਰਾਸੀ ਹੈ ਅਨਾਸੀ ਕੈ ਕੈ ਮਾਨੀਐ।","roman":"Mahaa roop hoon ke raasee hai anaasee kai kai maaneeai |","meaning_en":"","page":132},{"gurmukhi":"ਜੰਤ੍ਰ ਹੂੰ ਨ ਜਾਤਿ ਜਾ ਕੀ ਬਾਪ ਹੂੰ ਨ ਮਾਇ ਤਾ ਕੀ","roman":"Jantr hoon na jaati jaa kee baap hoon na maai taa kee","meaning_en":"","page":132},{"gurmukhi":"ਪੂਰਨ ਪ੍ਰਭਾ ਕੀ ਸੁ ਛਟਾ ਕੈ ਅਨੁਮਾਨੀਐ।","roman":"Pooran prabhaa kee su chhataa kai anumaaneeai |","meaning_en":"","page":132},{"gurmukhi":"ਤੇਜ ਹੂੰ ਕੋ ਤੰਤ੍ਰ ਹੈ ਕਿ ਰਾਜਸੀ ਕੋ ਜੰਤ੍ਰ ਹੈ","roman":"Tej hoon ko tantr hai ki raajsee ko jantr hai","meaning_en":"","page":132},{"gurmukhi":"ਮੋਹਨੀ ਕੋ ਮੰਤ੍ਰ ਹੈ ਨਿਜੰਤ੍ਰ ਕੈ ਕੈ ਜਾਨੀਐ।੬।੨੫੮।","roman":"Mohnee ko mantr hai nijantr kai kai jaaneeai | 6 | 258 |","meaning_en":"","page":132}]},{"type":"verse","number":[7,259],"number_text":"੭।੨੫੯।","page":132,"lines":[{"gurmukhi":"ਤੇਜ ਹੂੰ ਕੋ ਤਰੁ ਹੈ ਕਿ ਰਾਜਸੀ ਕੋ ਸਰੁ ਹੈ","roman":"Tej hoon ko taru hai ki raajsee ko saru hai","meaning_en":"","page":132},{"gurmukhi":"ਸੁਧਤਾ ਕੋ ਘਰੁ ਹੈ ਕਿ ਸਿਧਤਾ ਕੀ ਸਾਰੁ ਹੈ।","roman":"Sudhtaa ko gharu hai ki sidhtaa kee saaru hai |","meaning_en":"","page":132},{"gurmukhi":"ਕਾਮਨਾ ਕੀ ਖਾਨ ਹੈ ਕਿ ਸਾਧਨਾ ਦੀ ਸਾਨ ਹੈ","roman":"Kaamnaa kee khaan hai ki saadhnaa dee saan hai","meaning_en":"","page":132},{"gurmukhi":"ਬਿਰਕਤਤਾ ਕੀ ਬਾਨ ਹੈ ਕਿ ਬੁਧਿ ਕੋ ਉਦਾਰ ਹੈ।","roman":"Birkattaa kee baan hai ki budhi ko udaar hai |","meaning_en":"","page":132},{"gurmukhi":"ਸੁੰਦਰ ਸਰੂਪ ਹੈ ਕਿ ਭੂਪਨ ਕੋ ਭੂਪ ਹੈ","roman":"Sundar saroop hai ki bhoopan ko bhoop hai","meaning_en":"","page":132},{"gurmukhi":"ਕਿ ਰੂਪ ਹੂੰ ਕੋ ਰੂਪ ਹੈ ਕੁਮਤਿ ਕੋ ਪ੍ਰਹਾਰੁ ਹੈ।","roman":"Ki roop hoon ko roop hai kumti ko prahaaru hai |","meaning_en":"","page":132},{"gurmukhi":"ਦੀਨਨ ਕੋ ਦਾਤਾ ਹੈ ਗਨੀਮਨ ਕੋ ਗਾਰਕ ਹੈ","roman":"Deenan ko daataa hai ganeeman ko gaarak hai","meaning_en":"","page":132},{"gurmukhi":"ਸਾਧਨ ਕੋ ਰਛਕ ਹੈ ਗੁਨਨ ਕੋ ਪਹਾਰੁਹੈ।੭।੨੫੯।","roman":"Saadhan ko rachhak hai gunan ko pahaaruhai | 7 | 259 |","meaning_en":"","page":132}]},{"type":"verse","number":[8,260],"number_text":"੮। ੨੬੦।","page":132,"lines":[{"gurmukhi":"ਸਿਧਿ ਕੋ ਸਰੂਪ ਹੈ ਕਿ ਬੁਧਿ ਕੋ ਬਿਭੂਤਿ ਹੈ","roman":"Sidhi ko saroop hai ki budhi ko bibhooti hai","meaning_en":"","page":132},{"gurmukhi":"ਕਿ ਕ੍ਰੁਧ ਕੋ ਅਭੂਤ ਹੈ ਕਿ ਅਛੈ ਅਬਿਨਾਸੀ ਹੈ।","roman":"Ki krudh ko abhoot hai ki achhai abinaasee hai |","meaning_en":"","page":132,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}]},{"gurmukhi":"ਕਾਮ ਕੋ ਕੁਨਿੰਦਾ ਹੈ ਕਿ ਖੂਬੀ ਕੋ ਦਿਹੰਦਾ ਹੈ","roman":"Kaam ko kunindaa hai ki khoobee ko dihandaa hai","meaning_en":"","page":132},{"gurmukhi":"ਗਨੀਮਨ ਗਿਰਿੰਦਾ ਹੈ ਕਿ ਤੇਜ ਕੋ ਪ੍ਰਕਾਸੀ ਹੈ।","roman":"Ganeeman girindaa hai ki tej ko prakaasee hai |","meaning_en":"","page":132},{"gurmukhi":"ਕਾਲ ਹੂੰ ਕੇ ਕਾਲ ਹੈ ਕਿ ਸਤ੍ਰਨ ਕੇ ਸਾਲ ਹੈ","roman":"Kaal hoon ke kaal hai ki satran ke saal hai","meaning_en":"","page":132},{"gurmukhi":"ਕਿ ਮਿਤ੍ਰਨ ਕੋ ਪੋਖਤ ਹੈ ਕਿ ਬ੍ਰਿਧਤਾ ਕੇ ਬਾਸੀ ਹੈ।","roman":"Ki mitran ko pokhat hai ki bridhtaa ke baasee hai |","meaning_en":"","page":132},{"gurmukhi":"ਜੋਗ ਹੂੰ ਕੋ ਜੰਤ੍ਰ ਹੈ ਕਿ ਤੇਜ ਹੂੰ ਕੋ ਤੰਤ੍ਰ ਹੈ","roman":"Jog hoon ko jantr hai ki tej hoon ko tantr hai","meaning_en":"","page":132},{"gurmukhi":"ਕਿ ਮੋਹਨੀ ਕੋ ਮੰਤ੍ਰ ਹੈ ਕਿ ਪੂਰਨ ਪ੍ਰਕਾਸੀ ਹੈ। ੮। ੨੬੦।","roman":"Ki mohnee ko mantr hai ki pooran prakaasee hai | 8 | 260 |","meaning_en":"","page":132}]},{"type":"verse","number":[9,261],"number_text":"੯। ੨੬੧।","page":132,"lines":[{"gurmukhi":"ਰੂਪ ਕੋ ਨਿਵਾਸ ਹੈ ਕਿ ਬੁਧਿ ਕੋ ਪ੍ਰਕਾਸ ਹੈ","roman":"Roop ko nivaas hai ki budhi ko prakaas hai","meaning_en":"","page":132},{"gurmukhi":"ਕਿ ਸਿਧਤਾ ਕੋ ਬਾਸ ਹੈ ਕਿ ਬੁਧਿ ਹੂੰ ਕੇ ਘਰੁ ਹੈ।","roman":"Ki sidhtaa ko baas hai ki budhi hoon ke gharu hai |","meaning_en":"","page":132},{"gurmukhi":"ਦੇਵਨ ਕੋ ਦੇਵ ਹੈ ਨਿਰੰਜਨ ਅਭੇਵ ਹੈ","roman":"Devan ko dev hai niranjan abhev hai","meaning_en":"","page":132},{"gurmukhi":"ਅਦੇਵਨ ਕੋ ਦੇਵ ਹੈ ਕਿ ਸੁਧਤਾ ਕੋ ਸਰੁ ਹੈ।","roman":"Adevan ko dev hai ki sudhtaa ko saru hai |","meaning_en":"","page":132},{"gurmukhi":"ਜਾਨ ਕੋ ਬਚਯਾ ਹੈ ਇਮਾਨ ਕੋ ਦਿਵਯਾ ਹੈ","roman":"Jaan ko bachyaa hai imaan ko divyaa hai","meaning_en":"","page":132},{"gurmukhi":"ਜਮਜਾਲ ਕੋ ਕਟਯਾ ਹੈ ਕਿ ਕਾਮਨਾ ਕੋ ਕਰ ਹੈ।","roman":"Jamjaal ko katyaa hai ki kaamnaa ko kar hai |","meaning_en":"","page":132},{"gurmukhi":"ਤੇਜ ਕੋ ਪ੍ਰਚੰਡ ਹੈ ਅਖੰਡਣ ਕੋ ਖੰਡ ਹੈ","roman":"Tej ko prachand hai akhandan ko khand hai","meaning_en":"","page":132},{"gurmukhi":"ਮਹੀਪਨ ਕੋ ਮੰਡ ਹੈ ਕਿ ਇਸਤ੍ਰੀ ਹੈ ਨ ਨਰੁ ਹੈ। ੯। ੨੬੧।","roman":"Maheepan ko mand hai ki istree hai na naru hai | 9 | 261 |","meaning_en":"","page":132}]},{"type":"verse","number":[10,262],"number_text":"੧੦। ੨੬੨।","page":132,"lines":[{"gurmukhi":"ਬਿਸ੍ਵ ਕੋ ਭਰਨ ਹੈ ਕਿ ਅਪਦਾ ਕੋ ਹਰਨ ਹੈ","roman":"Bisv ko bharan hai ki apdaa ko haran hai","meaning_en":"","page":132},{"gurmukhi":"ਕਿ ਸੁਖ ਕੋ ਕਰਨ ਹੈ ਕਿ ਤੇਜ ਕੋ ਪ੍ਰਕਾਸ ਹੈ।","roman":"Ki sukh ko karan hai ki tej ko prakaas hai |","meaning_en":"","page":132},{"gurmukhi":"ਪਾਈਐ ਨ ਪਾਰ ਪਾਰਾਵਾਰ ਹੂੰ ਕੋ ਪਾਰ ਜਾ ਕੋ","roman":"Paaeeai na paar paaraavaar hoon ko paar jaa ko","meaning_en":"","page":132},{"gurmukhi":"ਕੀਜਤ ਬਿਚਾਰ ਸੁ ਬਿਚਾਰ ਕੋ ਨਿਵਾਸ ਹੈ।","roman":"Keejat bichaar su bichaar ko nivaas hai |","meaning_en":"","page":132},{"gurmukhi":"ਹਿੰਗੁਲਾ ਹਿਮਾਲੈ ਗਾਵੈ ਅਬਸੀ ਹਲਬੀ ਧਿਆਵੈ","roman":"Hingulaa himaalai gaavai absee halbee dhiaavai","meaning_en":"","page":133},{"gurmukhi":"ਪੂਰਬੀ ਨ ਪਾਰ ਪਾਵੈ ਆਸਾ ਤੇ ਅਨਾਸ ਹੈ।","roman":"Poorbee na paar paavai aasaa te anaas hai |","meaning_en":"","page":133},{"gurmukhi":"ਦੇਵਨ ਕੋ ਦੇਵ ਮਹਾਦੇਵ ਹੂੰ ਕੇ ਦੇਵ ਹੈ","roman":"Devan ko dev mahaadev hoon ke dev hai","meaning_en":"","page":133},{"gurmukhi":"ਨਿਰੰਜਨ ਅਭੇਵ ਨਾਥ ਅਦ੍ਵੈ ਅਬਿਨਾਸਿ ਹੈ। ੧੦। ੨੬੨।","roman":"Niranjan abhev naath advai abinaasi hai | 10 | 262 |","meaning_en":"","page":133}]},{"type":"verse","number":[11,263],"number_text":"੧੧। ੨੬੩।","page":133,"lines":[{"gurmukhi":"ਅੰਜਨ ਬਿਹੀਨ ਹੈ ਨਿਰੰਜਨ ਪ੍ਰਬੀਨ ਹੈ","roman":"Anjan biheen hai niranjan prabeen hai","meaning_en":"","page":133},{"gurmukhi":"ਕਿ ਸੇਵਕ ਅਧੀਨ ਹੈ ਕਟਯਾ ਜਮ ਜਾਲ ਕੇ।","roman":"Ki sevak adheen hai katyaa jam jaal ke |","meaning_en":"","page":133},{"gurmukhi":"ਦੇਵਨ ਕੇ ਦੇਵ ਮਹਾਦੇਵ ਹੂੰ ਕੇ ਦੇਵ ਨਾਥ","roman":"Devan ke dev mahaadev hoon ke dev naath","meaning_en":"","page":133},{"gurmukhi":"ਭੂਮਿ ਕੇ ਭੁਜਯਾ ਹੈ ਮੁਹੀਯਾ ਮਹਾ ਬਾਲ ਕੇ।","roman":"Bhoomi ke bhujyaa hai muheeyaa mahaa baal ke |","meaning_en":"","page":133},{"gurmukhi":"ਰਾਜਨ ਕੇ ਰਾਜਾ ਮਹਾ ਸਾਜ ਹੂੰ ਕੇ ਸਾਜਾ","roman":"Raajan ke raajaa mahaa saaj hoon ke saajaa","meaning_en":"","page":133},{"gurmukhi":"ਮਹਾ ਜੋਗ ਹੂੰ ਕੇ ਜੋਗ ਹੈ ਧਰਯਾ ਦ੍ਰਮ ਛਾਲ ਕੇ।","roman":"Mahaa jog hoon ke jog hai dharyaa dram chhaal ke |","meaning_en":"","page":133},{"gurmukhi":"ਕਾਮਨਾ ਕੇ ਕਰ ਹੈ ਕੁਬੁਧਿਤਾ ਕੋ ਹਰ ਹੈ","roman":"Kaamnaa ke kar hai kubudhitaa ko har hai","meaning_en":"","page":133},{"gurmukhi":"ਕਿ ਸਿਧਤਾ ਕੇ ਸਾਥੀ ਹੈ ਕਿ ਕਾਲ ਹੈ ਕੁਚਾਲ ਕੇ। ੧੧। ੨੬੩।","roman":"Ki sidhtaa ke saathee hai ki kaal hai kuchaal ke | 11 | 263 |","meaning_en":"","page":133}]},{"type":"verse","number":[12,264],"number_text":"੧੨। ੨੬੪।","page":133,"lines":[{"gurmukhi":"ਛੀਰ ਕੈਸੀ ਛੀਰਾਵਧਿ ਛਾਛ ਕੈਸੀ ਛਤ੍ਰਾਨੇਰ","roman":"Chheer kaisee chheeraavdhi chhaachh kaisee chhatraaner","meaning_en":"","page":133},{"gurmukhi":"ਛਪਾਕਰ ਕੈਸੀ ਛਬਿ ਕਾਲਇੰਦ੍ਰ ਕੇ ਕੂਲ ਕੈ।","roman":"Chhapaakar kaisee chhabi kaalaindr ke kool kai |","meaning_en":"","page":133},{"gurmukhi":"ਹੰਸਨੀ ਸੀ ਸੀਹਾ ਰੂਮ ਹੀਰਾ ਸੀ ਹੁਸੈਨਾਬਾਦ","roman":"Hansnee see seehaa room heeraa see husainaabaad","meaning_en":"","page":133},{"gurmukhi":"ਗੰਗਾ ਕੈਸੀ ਧਾਰ ਚਲੀ ਸਾਤ ਸਿੰਧ ਰੂਲ ਕੈ।","roman":"Gangaa kaisee dhaar chalee saat sindh rool kai |","meaning_en":"","page":133},{"gurmukhi":"ਪਾਰਾ ਸੀ ਪਲਾਊਗਢ ਰੂਪਾ ਕੈਸੀ ਰਾਮਪੁਰ","roman":"Paaraa see palaaoogadh roopaa kaisee raampur","meaning_en":"","page":133},{"gurmukhi":"ਸੋਰਾ ਸੀ ਸੁਰੰਗਾਬਾਦ ਨੀਕੇ ਰਹੀ ਝੂਲ ਕੈ।","roman":"Soraa see surangaabaad neeke rahee jhool kai |","meaning_en":"","page":133},{"gurmukhi":"ਚੰਪਾ ਸੀ ਚੰਦੇਰੀ ਕੋਟ ਚਾਂਦਨੀ ਸੀ ਚਾਂਦਾਗੜਿ","roman":"Chanpaa see chanderee kot chaandnee see chaandaagri","meaning_en":"","page":133},{"gurmukhi":"ਕੀਰਤਿ ਤਿਹਾਰੀ ਰਹੀ ਮਾਲਤੀ ਸੀ ਫੂਲ ਕੈ। ੧੨। ੨੬੪।","roman":"Keerti tihaaree rahee maaltee see phool kai | 12 | 264 |","meaning_en":"","page":133}]},{"type":"verse","number":[13,265],"number_text":"੧੩। ੨੬੫।","page":133,"lines":[{"gurmukhi":"ਫਟਕ ਸੀ ਕੈਲਾਸ ਕਮਾਊਗੜ ਕਾਸੀਪੁਰ","roman":"Phatak see kailaas kamaaoogar kaaseepur","meaning_en":"","page":133},{"gurmukhi":"ਸੀਸਾ ਸੀ ਸੁਰੰਗਾਬਾਦਿ ਨੀਕੈ ਸੋਹੀਅਤੁ ਹੈ।","roman":"Seesaa see surangaabaadi neekai soheeatu hai |","meaning_en":"","page":133},{"gurmukhi":"ਹਿਮਾ ਸੀ ਹਿਮਾਲੈ ਹਰ ਹਾਰ ਸੀ ਹਲਬਾਨੇਰ","roman":"Himaa see himaalai har haar see halbaaner","meaning_en":"","page":133},{"gurmukhi":"ਹੰਸ ਕੈਸੀ ਹਾਜੀਪੁਰ ਦੇਖੇ ਮੋਹੀਅਤੁ ਹੈ।","roman":"Hans kaisee haajeepur dekhe moheeatu hai |","meaning_en":"","page":133},{"gurmukhi":"ਚੰਦਨ ਸੀ ਚੰਪਾਵਤੀ ਚੰਦ੍ਰਮਾ ਸੀ ਚੰਦ੍ਰਾਗਿਰ","roman":"Chandan see chanpaavtee chandramaa see chandraagir","meaning_en":"","page":133},{"gurmukhi":"ਚਾਂਦਨੀ ਸੀ ਚਾਂਦਗੜ ਜਉਨ ਜੋਹੀਅਤੁ ਹੈ।","roman":"Chaandnee see chaandgar jaun joheeatu hai |","meaning_en":"","page":133},{"gurmukhi":"ਗੰਗਾ ਸਮ ਗੰਗ ਧਾਰਿ ਬਕਾਨਿ ਸੀ ਬਿਲੰਦਾਬਾਦਿ","roman":"Gangaa sam gang dhaari bakaani see bilandaabaadi","meaning_en":"","page":133},{"gurmukhi":"ਕੀਰਤਿ ਤਿਹਾਰੀ ਕੀ ਉਜੀਆਰੀ ਸੋਹੀਅਤੁ ਹੈ। ੧੩। ੨੬੫।","roman":"Keerti tihaaree kee ujeeaaree soheeatu hai | 13 | 265 |","meaning_en":"","page":133}]},{"type":"verse","number":[14,266],"number_text":"੧੪। ੨੬੬।","page":133,"lines":[{"gurmukhi":"ਫਰਾਸੀ ਫਿਰੰਗੀ ਫਰਾਸੀਸ ਕੇ ਦੁਰੰਗੀ","roman":"Pharaasee phirangee pharaasees ke durangee","meaning_en":"","page":133},{"gurmukhi":"ਮਕਰਾਨ ਕੇ ਮ੍ਰਿਦੰਗੀ ਤੇਰੇ ਗੀਤ ਗਾਈਅਤੁ ਹੈ।","roman":"Makraan ke mridangee tere geet gaaeeatu hai |","meaning_en":"","page":133},{"gurmukhi":"ਭਖਰੀ ਕੰਧਾਰੀ ਗੋਰਿ ਗਖਰੀ ਗਰਦੇਜਾਚਾਰੀ","roman":"Bhakhree kandhaaree gori gakhree gardejaachaaree","meaning_en":"","page":133},{"gurmukhi":"ਪਉਨ ਕੇ ਅਹਾਰੀ ਤੇਰੇ ਨਾਮੁ ਧਿਆਈਅਤੁ ਹੈ।","roman":"Paun ke ahaaree tere naamu dhiaaeeatu hai |","meaning_en":"","page":133},{"gurmukhi":"ਪੂਰਬ ਪਲਾਊ ਕਾਮਰੂਪ ਅਉ ਕਮਾਊ","roman":"Poorab palaaoo kaamroop au kamaaoo","meaning_en":"","page":133},{"gurmukhi":"ਸਰਬ ਠਉਰ ਮੈ ਬਿਰਾਜੈ ਜਹਾ ਜਹਾ ਜਾਈਅਤੁ ਹੈ।","roman":"Sarab thaur mai biraajai jahaa jahaa jaaeeatu hai |","meaning_en":"","page":133},{"gurmukhi":"ਪੂਰਨ ਪ੍ਰਤਾਪੀ ਜੰਤ੍ਰ ਮੰਤ੍ਰ ਤੇ ਅਤਾਪੀ ਨਾਥ","roman":"Pooran prataapee jantr mantr te ataapee naath","meaning_en":"","page":133},{"gurmukhi":"ਕੀਰਤਿ ਤਿਹਾਰੀ ਕੋ ਨ ਪਾਰ ਪਾਈਅਤੁ ਹੈ। ੧੪। ੨੬੬।","roman":"Keerti tihaaree ko na paar paaeeatu hai | 14 | 266 |","meaning_en":"","page":133}]},{"type":"heading","kind":"chhand","name":"ਪਾਧੜੀ ਛੰਦ","gurmukhi":"ਤ੍ਵਪ੍ਰਸਾਦਿ। ਪਾਧੜੀ ਛੰਦ","roman":"Tvaprasaadi | paadhree chhand","meaning_en":"","page":134,"invocation":"ਤ੍ਵਪ੍ਰਸਾਦਿ"},{"type":"verse","number":[1,267],"number_text":"੧। ੨੬੭।","page":134,"lines":[{"gurmukhi":"ਅਦ੍ਵੈ ਅਨਾਸ ਆਸਨ ਅਡੋਲ। ਅਦ੍ਵੈ ਅਨੰਤ ਉਪਮਾ ਅਤੋਲ।","roman":"Advai anaas aasan adol | advai anant upmaa atol |","meaning_en":"","page":134},{"gurmukhi":"ਅਛੈ ਸਰੂਪ ਅਬ੍ਯਕਤ ਨਾਥ। ਆਜਾਨੁਬਾਹੁ ਸਰਬਾ ਪ੍ਰਮਾਥ। ੧। ੨੬੭।","roman":"Achhai saroop abyakat naath | aajaanubaahu sarbaa pramaath | 1 | 267 |","meaning_en":"","page":134}]},{"type":"verse","number":[2,268],"number_text":"੨। ੨੬੮।","page":134,"lines":[{"gurmukhi":"ਜਹ ਤਹ ਮਹੀਪ ਬਨ ਤਿਨ ਪ੍ਰਫੁਲ। ਸੋਭਾ ਬਸੰਤ ਜਹ ਤਹ ਪ੍ਰਜੁਲ।","roman":"Jah tah maheep ban tin praphul | sobhaa basant jah tah prajul |","meaning_en":"","page":134},{"gurmukhi":"ਬਨ ਤਨ ਦੁਰੰਤ ਖਗ ਮ੍ਰਿਗ ਮਹਾਨ। ਜਹ ਤਹ ਪ੍ਰਫੁਲ ਸੁੰਦਰ ਸੁਜਾਨ। ੨। ੨੬੮।","roman":"Ban tan durant khag mrig mahaan | jah tah praphul sundar sujaan | 2 | 268 |","meaning_en":"","page":134}]},{"type":"verse","number":[3,269],"number_text":"੩। ੨੬੯।","page":134,"lines":[{"gurmukhi":"ਫੁਲਤੰ ਪ੍ਰਫੁਲ ਲਹਿਲਹਤ ਮਉਰ। ਸਿਰਿ ਢੁਲਹਿ ਜਾਨੁ ਮਨਮਥਹ ਚਉਰ।","roman":"Phultan praphul lahilhat maur | siri dhulhi jaanu manamthah chaur |","meaning_en":"","page":134},{"gurmukhi":"ਕੁਦਰਤਿ ਕਮਾਲ ਰਾਜਿਕ ਰਹੀਮ। ਕਰੁਣਾਨਿਧਾਨ ਕਾਮਿਲ ਕਰੀਮ। ੩। ੨੬੯।","roman":"Kudarti kamaal raajik raheem | karunaanidhaan kaamil kareem | 3 | 269 |","meaning_en":"","page":134}]},{"type":"verse","number":[4,270],"number_text":"੪। ੨੭੦।","page":134,"lines":[{"gurmukhi":"ਜਹ ਤਹ ਬਿਲੋਕਿ ਤਹ ਤਹ ਪ੍ਰਸੋਹ। ਆਜਾਨੁਬਾਹੁ ਅਮਿਤੋਜ ਮੋਹ।","roman":"Jah tah biloki tah tah prasoh | aajaanubaahu amitoj moh |","meaning_en":"","page":134},{"gurmukhi":"ਰੋਸੰ ਬਿਰਹਤ ਕੁਰੁਣਾਨਿਧਾਨ। ਜਹ ਤਹ ਪ੍ਰਫੁਲ ਸੁੰਦਰ ਸੁਜਾਨ। ੪। ੨੭੦।","roman":"Rosan birhat kurunaanidhaan | jah tah praphul sundar sujaan | 4 | 270 |","meaning_en":"","page":134}]},{"type":"verse","number":[5,271],"number_text":"੫। ੨੭੧।","page":134,"lines":[{"gurmukhi":"ਬਨ ਤਿਨ ਮਹੀਪ ਜਲ ਥਲ ਮਹਾਨ। ਜਹ ਤਹ ਪ੍ਰਸੋਹ ਕਰੁਣਾਨਿਧਾਨ।","roman":"Ban tin maheep jal thal mahaan | jah tah prasoh karunaanidhaan |","meaning_en":"","page":134},{"gurmukhi":"ਜਗਮਗਤ ਤੇਜ ਪੂਰਨ ਪ੍ਰਤਾਪ। ਅੰਬਰ ਜਮੀਨ ਜਿਹ ਜਪਤ ਜਾਪ। ੫। ੨੭੧।","roman":"Jagamgat tej pooran prataap | anbar jameen jih japat jaap | 5 | 271 |","meaning_en":"","page":134}]},{"type":"verse","number":[6,272],"number_text":"੬। ੨੭੨।","page":134,"lines":[{"gurmukhi":"ਸਾਤੋ ਅਕਾਲ ਸਾਤੋ ਪਤਾਰ। ਬਿਥਰਿਓ ਅਦ੍ਰਿਸਟ ਜਿਹ ਕਰਮ ਜਾਰ। ੬। ੨੭੨।","roman":"Saato akaal saato pataar | bithrio adrisat jih karam jaar | 6 | 272 |","meaning_en":"","page":134}]}],"ending":null});
